select ac_cargar_unidad($ac${"slug":"ciencia-1","rama":"ciencia","orden":1,"nivel":1,"titulo_es":"Cómo sabemos lo que sabemos","bajada_es":"Observar, preguntar, probar y corregir: el método que permite saber que el clima cambia, que un remedio funciona o que un río está contaminado.","objetivos_es":["Distinguir observaciones de inferencias y formular preguntas investigables","Diseñar un experimento justo con variables y grupo de control","Reconocer errores de medición y la importancia del tamaño de la muestra","Diferenciar correlación de causalidad","Explicar cómo la ciencia construye consenso y se corrige"],"repasa":["tronco-2"],"requiere_tronco":1,"fuentes":["consenso-cook-2016","ipcc-ar6-syr","nasa-evidencia","chequeado","ncse-ozono","naaee-guidelines"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-1.s1","orden":1,"tipo":"leccion","titulo_es":"Observar y preguntar","bajada_es":"La diferencia entre lo que ves y lo que suponés, y cómo convertir una curiosidad en una pregunta que se pueda investigar.","minutos":11,"pasos":[{"slug":"ciencia-1.s1.p1","orden":1,"grupo":"ciencia-1.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Observación e inferencia","cuerpo":["Una observación es lo que se percibe directamente con los sentidos o con instrumentos: \"el agua del arroyo es marrón\", \"el termómetro marca 32 °C\", \"hay 12 horneros en la plaza\". Una inferencia es una interpretación de lo observado: \"el arroyo está contaminado\", \"hace más calor que antes\", \"a los horneros les gusta esta plaza\".","Las inferencias pueden ser correctas o no. El primer paso del pensamiento científico es separar lo que se ve de lo que se supone."]},"solucion":{}},{"slug":"ciencia-1.s1.p2","orden":2,"grupo":"ciencia-1.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una observación o una inferencia?","grupos":[{"id":"g1","nombre":"Observación"},{"id":"g2","nombre":"Inferencia"}],"items":[{"id":"i1","texto":"El agua del arroyo es marrón"},{"id":"i2","texto":"El arroyo está contaminado por una fábrica"},{"id":"i3","texto":"El termómetro marca 32 °C"},{"id":"i4","texto":"Este verano es más caluroso por el cambio climático"},{"id":"i5","texto":"Conté 12 horneros en la plaza"},{"id":"i6","texto":"A los horneros les gusta esta plaza"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"El agua marrón puede ser sedimento de una lluvia, no contaminación. Separar lo que se ve de lo que se supone evita conclusiones apuradas."}},{"slug":"ciencia-1.s1.p3","orden":3,"grupo":"ciencia-1.s1.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"\"El agua del arroyo está contaminada\" es una observación directa.","razones":[{"id":"r1","texto":"Porque es una interpretación que hay que comprobar midiendo"},{"id":"r2","texto":"Porque la contaminación siempre se ve a simple vista"},{"id":"r3","texto":"Porque todo lo que se dice sobre el agua es una observación"}]},"solucion":{"valor":false,"explicacion":"Es una inferencia: se ve el color, el olor o la espuma, pero para saber si está contaminada hay que medir. El agua marrón puede ser solo barro.","clave":["r1"]}},{"slug":"ciencia-1.s1.p4","orden":4,"grupo":"ciencia-1.s1.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Preguntas que se pueden investigar","cuerpo":["No toda pregunta se puede responder con ciencia. \"¿Es lindo el río?\" depende de gustos. \"¿Cuánto oxígeno disuelto tiene el río antes y después de la fábrica?\" se puede medir.","Una buena pregunta investigable es concreta, se puede responder con datos y dice qué se va a comparar o medir."]},"solucion":{}},{"slug":"ciencia-1.s1.p5","orden":5,"grupo":"ciencia-1.s1.p5","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta pregunta se puede investigar con datos o no?","grupos":[{"id":"g1","nombre":"Investigable"},{"id":"g2","nombre":"No investigable así"}],"items":[{"id":"i1","texto":"¿Crecen más los porotos con compost que sin compost?"},{"id":"i2","texto":"¿Es más lindo el ceibo que el jacarandá?"},{"id":"i3","texto":"¿Cuántas aves visitan la plaza a la mañana y a la tarde?"},{"id":"i4","texto":"¿Deberían gustarle a todos las plantas nativas?"},{"id":"i5","texto":"¿Baja la temperatura bajo los árboles de la vereda?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Las preguntas de gusto u opinión no se resuelven midiendo. Las que comparan o cuantifican, sí."}},{"slug":"ciencia-1.s1.p6","orden":6,"grupo":"ciencia-1.s1.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es la pregunta más investigable?","opciones":[{"id":"o1","texto":"¿Baja el consumo si se apagan las luces en los recreos?"},{"id":"o2","texto":"¿Es importante que todos cuidemos la energía en la escuela?"},{"id":"o3","texto":"¿Qué opina la gente sobre la energía solar en general?"},{"id":"o4","texto":"¿Está mal gastar energía durante los recreos de la escuela?"}]},"solucion":{"clave":["o1"],"explicacion":"Concreta, medible y con una comparación clara: antes y después de apagar las luces.","por_opcion":{"o3":"Se puede investigar con encuestas, pero así planteada es vaga: ¿qué gente?, ¿qué opinión?"}}},{"slug":"ciencia-1.s1.p7","orden":7,"grupo":"ciencia-1.s1.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Del problema a la pregunta","cuerpo":["Muchas veces se parte de un problema general —\"el arroyo está feo\"— y hay que convertirlo en preguntas concretas: ¿qué parámetros del agua cambian?, ¿dónde?, ¿cuándo?, ¿cuánto? Cada pregunta concreta lleva a una medición."]},"solucion":{}},{"slug":"ciencia-1.s1.p8","orden":8,"grupo":"ciencia-1.s1.p8","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para pasar de una curiosidad a una pregunta investigable.","items":[{"id":"i1","texto":"Notar algo que llama la atención"},{"id":"i2","texto":"Describir lo observado sin interpretar"},{"id":"i3","texto":"Pensar posibles explicaciones"},{"id":"i4","texto":"Formular una pregunta concreta que se pueda medir"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"De la curiosidad a la pregunta: observar, describir, imaginar y precisar."}},{"slug":"ciencia-1.s1.p9","orden":9,"grupo":"ciencia-1.s1.p9","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una pregunta sea buena para investigar? Marcá todo.","opciones":[{"id":"o1","texto":"Que sea concreta"},{"id":"o2","texto":"Que se pueda responder con datos"},{"id":"o3","texto":"Que diga qué se va a comparar o medir"},{"id":"o4","texto":"Que se pueda investigar con los recursos disponibles"},{"id":"o5","texto":"Que la respuesta ya se sepa de antemano"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Si ya se sabe la respuesta, no hay investigación: hay confirmación de prejuicios."}},{"slug":"ciencia-1.s1.p10","orden":10,"grupo":"ciencia-1.s1.p10","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada observación con una inferencia posible.","izquierda":[{"id":"a1","texto":"Hay espuma blanca en el arroyo"},{"id":"a2","texto":"Los árboles de una cuadra tienen hojas amarillas en verano"},{"id":"a3","texto":"No se ven lombrices en el cantero"},{"id":"a4","texto":"El medidor de luz gira rápido a la noche"}],"derecha":[{"id":"b1","texto":"Puede haber detergentes en el agua"},{"id":"b2","texto":"Puede faltarles agua o nutrientes"},{"id":"b3","texto":"El suelo puede estar compactado o pobre"},{"id":"b4","texto":"Puede haber un aparato encendido"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada inferencia es una posibilidad que hay que comprobar, no una conclusión."}},{"slug":"ciencia-1.s1.p11","orden":11,"grupo":"ciencia-1.s1.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe de un grupo escolar y marcá lo que es inferencia presentada como si fuera un hecho.","segmentos":[{"id":"s1","texto":"Medimos 4 mg/L de oxígeno disuelto aguas abajo del puente."},{"id":"s2","texto":"La fábrica de al lado es la culpable de la contaminación."},{"id":"s3","texto":"Aguas arriba medimos 7 mg/L."},{"id":"s4","texto":"Todos los peces del arroyo se murieron."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos son el piso. Las interpretaciones hay que presentarlas como hipótesis hasta probarlas.","por_opcion":{"s2":"Es una inferencia: hay que comparar aguas arriba y abajo de la descarga y descartar otras causas.","s4":"No se observó todo el arroyo: es una generalización que no surge de las mediciones."}}},{"slug":"ciencia-1.s1.p12","orden":12,"grupo":"ciencia-1.s1.p12","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Lo que se percibe directamente es una {{0}}; lo que se interpreta a partir de eso es una {{1}}; y una buena pregunta se puede responder con {{2}}.","banco":[{"id":"w1","texto":"observación"},{"id":"w2","texto":"inferencia"},{"id":"w3","texto":"datos"},{"id":"w4","texto":"opinión"},{"id":"w5","texto":"certeza"},{"id":"w6","texto":"gustos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para empezar a pensar como científico o científica."}},{"slug":"ciencia-1.s1.p13","orden":13,"grupo":"ciencia-1.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Una inferencia siempre es falsa.","razones":[{"id":"r1","texto":"Porque puede ser correcta o no, y por eso se comprueba"},{"id":"r2","texto":"Porque las inferencias nunca se pueden comprobar"},{"id":"r3","texto":"Porque las inferencias son lo mismo que las observaciones"}]},"solucion":{"valor":false,"explicacion":"Las inferencias pueden ser correctas o no: por eso se comprueban. Muchas inferencias bien hechas terminan confirmadas con datos.","clave":["r1"]}}]},{"slug":"ciencia-1.s2","orden":2,"tipo":"leccion","titulo_es":"Hipótesis y experimentos","bajada_es":"Variables, grupo de control y repeticiones: cómo diseñar una prueba justa.","minutos":12,"pasos":[{"slug":"ciencia-1.s2.p1","orden":1,"grupo":"ciencia-1.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La hipótesis","cuerpo":["Una hipótesis es una explicación posible que se puede poner a prueba. Suele escribirse como una predicción: \"si agrego compost a las macetas, los porotos crecerán más que sin compost\".","Una buena hipótesis puede resultar falsa: si no hay ningún resultado posible que la contradiga, no se puede poner a prueba."]},"solucion":{}},{"slug":"ciencia-1.s2.p2","orden":2,"grupo":"ciencia-1.s2.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es una hipótesis que se puede poner a prueba?","opciones":[{"id":"o1","texto":"Regadas con lluvia, crecerán más que con agua de red"},{"id":"o2","texto":"Las plantas son seres maravillosos y llenos de vida"},{"id":"o3","texto":"Las plantas crecen y cambian con el paso del tiempo"},{"id":"o4","texto":"Algunas plantas pueden crecer más o menos que otras"}]},"solucion":{"clave":["o1"],"explicacion":"Una hipótesis útil predice algo concreto que podría no cumplirse.","por_opcion":{"o3":"Es cierto, pero no predice nada que se pueda comparar."}}},{"slug":"ciencia-1.s2.p3","orden":3,"grupo":"ciencia-1.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Variables","cuerpo":["En un experimento hay tres tipos de variables. La variable independiente es la que se cambia a propósito (con o sin compost). La variable dependiente es la que se mide para ver el efecto (la altura de los porotos). Y las variables controladas son todas las demás, que se mantienen iguales (la luz, el agua, la maceta, la semilla).","Si cambian varias cosas a la vez, no se puede saber cuál causó la diferencia."]},"solucion":{}},{"slug":"ciencia-1.s2.p4","orden":4,"grupo":"ciencia-1.s2.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"En el experimento de los porotos con y sin compost, uní cada cosa con su tipo de variable.","izquierda":[{"id":"a1","texto":"Con o sin compost"},{"id":"a2","texto":"Altura de los porotos"},{"id":"a3","texto":"Cantidad de agua de riego"}],"derecha":[{"id":"b1","texto":"Variable independiente"},{"id":"b2","texto":"Variable dependiente"},{"id":"b3","texto":"Variable controlada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3"},"explicacion":"Se cambia una sola cosa, se mide el efecto y todo lo demás se mantiene igual."}},{"slug":"ciencia-1.s2.p5","orden":5,"grupo":"ciencia-1.s2.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El grupo de control","cuerpo":["Para saber si algo tiene efecto hay que compararlo con un grupo al que no se le aplica: el grupo de control. Si se agrega compost a todas las macetas, no hay con qué comparar. Se necesitan macetas iguales sin compost.","Y hacen falta varias macetas en cada grupo, no una: con una sola, una semilla mala puede arruinar la conclusión. Repetir es la forma de separar el efecto real del azar."]},"solucion":{}},{"slug":"ciencia-1.s2.p6","orden":6,"grupo":"ciencia-1.s2.p6","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué hacen falta varias macetas en cada grupo.","items":[{"id":"i1","texto":"Cada semilla es un poco distinta"},{"id":"i2","texto":"Con una sola maceta por grupo, una semilla mala cambia todo"},{"id":"i3","texto":"Con muchas macetas, las diferencias al azar se compensan"},{"id":"i4","texto":"La comparación entre grupos se vuelve confiable"},{"id":"i5","texto":"Con más macetas las plantas crecen más rápido"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Repetir es la defensa contra el azar. Por eso los ensayos serios usan muchas repeticiones."}},{"slug":"ciencia-1.s2.p7","orden":7,"grupo":"ciencia-1.s2.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para probar si el compost ayuda, alcanza con poner compost en una maceta y ver si la planta crece.","razones":[{"id":"r1","texto":"Porque sin comparación y sin repeticiones no se sabe si fue el compost"},{"id":"r2","texto":"Porque el compost nunca tiene efecto"},{"id":"r3","texto":"Porque las plantas no crecen en macetas"}]},"solucion":{"valor":false,"explicacion":"Sin grupo de control no se sabe si habría crecido igual sin compost. Y con una sola maceta, el azar puede engañar.","clave":["r1"]}},{"slug":"ciencia-1.s2.p8","orden":8,"grupo":"ciencia-1.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una prueba justa","cuerpo":["Un experimento es justo cuando la única diferencia entre los grupos es la variable que se estudia. Si las macetas con compost están al sol y las otras a la sombra, cualquier diferencia podría deberse a la luz.","Para evitar sesgos, a veces se asignan las macetas a cada grupo al azar, y quien mide no sabe cuál es cuál."]},"solucion":{}},{"slug":"ciencia-1.s2.p9","orden":9,"grupo":"ciencia-1.s2.p9","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este diseño de experimento y marcá los errores.","segmentos":[{"id":"s1","texto":"Queremos saber si el compost ayuda a crecer a los porotos."},{"id":"s2","texto":"Pusimos las macetas con compost al sol y las sin compost a la sombra."},{"id":"s3","texto":"Usamos 10 macetas por grupo, con el mismo tipo de semilla."},{"id":"s4","texto":"Las macetas con compost las regamos el doble."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una sola diferencia entre grupos. Todo lo demás, igual.","por_opcion":{"s2":"La luz cambia entre grupos: no se sabe si la diferencia es por el compost o por el sol.","s4":"El riego debe ser igual: si no, no se sabe qué causó la diferencia."}}},{"slug":"ciencia-1.s2.p10","orden":10,"grupo":"ciencia-1.s2.p10","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de un experimento sobre el compost.","items":[{"id":"i1","texto":"Formular la hipótesis"},{"id":"i2","texto":"Preparar dos grupos de macetas iguales"},{"id":"i3","texto":"Agregar compost solo a uno de los grupos"},{"id":"i4","texto":"Cuidar todas las macetas igual durante semanas"},{"id":"i5","texto":"Medir la altura y comparar los grupos"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Hipótesis, grupos, tratamiento, condiciones iguales y medición."}},{"slug":"ciencia-1.s2.p11","orden":11,"grupo":"ciencia-1.s2.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más confiable un experimento? Marcá todo.","opciones":[{"id":"o1","texto":"Tener un grupo de control"},{"id":"o2","texto":"Repetir con varias unidades por grupo"},{"id":"o3","texto":"Cambiar solo una variable"},{"id":"o4","texto":"Asignar al azar cuál unidad va a cada grupo"},{"id":"o5","texto":"Elegir para el tratamiento las plantas más lindas"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Elegir las más lindas para el tratamiento sesga el resultado a favor de la hipótesis."}},{"slug":"ciencia-1.s2.p12","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 12, 14, 13, 15, 16. Sin compost: 10, 11, 9, 12, 13. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Promedio con compost: 14 cm. Sin compost: 11 cm. Diferencia: 3 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p12.v2","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 20, 22, 18, 21, 19. Sin compost: 17, 18, 16, 19, 15. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":3,"tolerancia":0.06,"explicacion":"Promedio con compost: 20 cm. Sin compost: 17 cm. Diferencia: 3 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p12.v3","orden":12,"grupo":"ciencia-1.s2.p12","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Alturas en cm con compost: 8, 9, 10, 9, 9. Sin compost: 7, 8, 7, 9, 9. ¿Cuántos cm más mide en promedio el grupo con compost?","unidad":"cm","decimales":1},"solucion":{"valor":1,"tolerancia":0.05,"explicacion":"Promedio con compost: 9 cm. Sin compost: 8 cm. Diferencia: 1 cm. Comparar promedios de varios casos es más confiable que comparar una planta con otra."}},{"slug":"ciencia-1.s2.p13","orden":13,"grupo":"ciencia-1.s2.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un experimento se cambia la variable {{0}}, se mide la variable {{1}} y se compara con un grupo de {{2}}.","banco":[{"id":"w1","texto":"independiente"},{"id":"w2","texto":"dependiente"},{"id":"w3","texto":"control"},{"id":"w4","texto":"aleatoria"},{"id":"w5","texto":"favorita"},{"id":"w6","texto":"azar"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La estructura básica de cualquier experimento justo."}},{"slug":"ciencia-1.s2.p14","orden":14,"grupo":"ciencia-1.s2.p14","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta variable del experimento del compost hay que mantenerla igual en los dos grupos o es la que se cambia?","grupos":[{"id":"g1","nombre":"Se mantiene igual"},{"id":"g2","nombre":"Se cambia a propósito"}],"items":[{"id":"i1","texto":"Tipo de semilla"},{"id":"i2","texto":"Presencia de compost"},{"id":"i3","texto":"Tamaño de la maceta"},{"id":"i4","texto":"Horas de sol"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g1"},"explicacion":"Todas menos una. Por eso se dice que se controlan las variables."}}]},{"slug":"ciencia-1.s3","orden":3,"tipo":"leccion","titulo_es":"Medir bien","bajada_es":"Exactitud, precisión, errores y muestras: por qué una medición mal hecha puede llevar a conclusiones falsas.","minutos":11,"pasos":[{"slug":"ciencia-1.s3.p1","orden":1,"grupo":"ciencia-1.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Exactitud y precisión","cuerpo":["Una medición es exacta cuando se acerca al valor real. Es precisa cuando, al repetirla, da valores parecidos entre sí. Un termómetro mal calibrado puede ser muy preciso (siempre marca 2 °C de más) pero no exacto.","Por eso los instrumentos se calibran, comparándolos con una referencia conocida."]},"solucion":{}},{"slug":"ciencia-1.s3.p2","orden":2,"grupo":"ciencia-1.s3.p2","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada situación con cómo es la medición.","izquierda":[{"id":"a1","texto":"Tres mediciones de 25,1; 25,0 y 25,2 °C, con valor real 25 °C"},{"id":"a2","texto":"Tres mediciones de 27,1; 27,0 y 27,2 °C, con valor real 25 °C"},{"id":"a3","texto":"Tres mediciones de 22; 28 y 25 °C, con valor real 25 °C"},{"id":"a4","texto":"Tres mediciones de 30; 21 y 34 °C, con valor real 25 °C"}],"derecha":[{"id":"b1","texto":"Exacta y precisa"},{"id":"b2","texto":"Precisa pero no exacta"},{"id":"b3","texto":"Exacta en promedio pero poco precisa"},{"id":"b4","texto":"Ni exacta ni precisa"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Precisión es repetir parecido; exactitud es acertar al valor real. Se pueden tener una sin la otra."}},{"slug":"ciencia-1.s3.p3","orden":3,"grupo":"ciencia-1.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Errores","cuerpo":["Toda medición tiene algún error. Los errores al azar hacen que los valores se dispersen para un lado y para el otro; se reducen repitiendo y promediando. Los errores sistemáticos empujan siempre en la misma dirección —un termómetro al sol, una balanza mal tarada— y no se arreglan promediando: hay que corregir el método o el instrumento."]},"solucion":{}},{"slug":"ciencia-1.s3.p4","orden":4,"grupo":"ciencia-1.s3.p4","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un error al azar o sistemático?","grupos":[{"id":"g1","nombre":"Al azar"},{"id":"g2","nombre":"Sistemático"}],"items":[{"id":"i1","texto":"Pequeñas diferencias al leer una regla"},{"id":"i2","texto":"Un termómetro colgado al sol"},{"id":"i3","texto":"Variaciones de una medición a otra con el mismo instrumento"},{"id":"i4","texto":"Una balanza que marca 100 g aunque esté vacía"},{"id":"i5","texto":"Medir siempre el tránsito en el horario pico"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Promediar arregla el azar, pero no el sesgo. Un termómetro al sol siempre va a marcar de más."}},{"slug":"ciencia-1.s3.p5","orden":5,"grupo":"ciencia-1.s3.p5","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un termómetro está al sol, alcanza con medir muchas veces y promediar para corregir el error.","razones":[{"id":"r1","texto":"Porque es un error sistemático que empuja siempre hacia arriba"},{"id":"r2","texto":"Porque los termómetros no se ven afectados por el sol"},{"id":"r3","texto":"Porque promediar corrige cualquier error"}]},"solucion":{"valor":false,"explicacion":"Es un error sistemático: todas las mediciones van a estar altas. Promediar no lo corrige; hay que ponerlo a la sombra, como en las estaciones meteorológicas.","clave":["r1"]}},{"slug":"ciencia-1.s3.p6","orden":6,"grupo":"ciencia-1.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La muestra","cuerpo":["Casi nunca se puede medir todo: todos los árboles de una ciudad, todas las casas, toda el agua de un río. Se mide una muestra y se generaliza. Para que eso funcione, la muestra tiene que ser suficientemente grande y representativa: parecida al conjunto en lo que importa.","Si se encuesta solo a los vecinos de un barrio rico sobre el acceso al agua, la conclusión no vale para toda la ciudad."]},"solucion":{}},{"slug":"ciencia-1.s3.p7","orden":7,"grupo":"ciencia-1.s3.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Querés saber cuánta basura genera por día cada casa de tu ciudad. ¿Qué muestra es mejor?","opciones":[{"id":"o1","texto":"Casas de distintos barrios elegidas al azar"},{"id":"o2","texto":"Las casas de tu cuadra"},{"id":"o3","texto":"Las casas de tus amigos"},{"id":"o4","texto":"Solo las casas más grandes, que generan más"}]},"solucion":{"clave":["o1"],"explicacion":"Al azar y de distintos barrios: así la muestra se parece a la ciudad.","por_opcion":{"o3":"Se parecen a vos: la muestra estaría sesgada."}}},{"slug":"ciencia-1.s3.p8","orden":8,"grupo":"ciencia-1.s3.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo una muestra sesgada lleva a una conclusión falsa.","items":[{"id":"i1","texto":"Se encuesta solo a personas en un gimnasio"},{"id":"i2","texto":"La muestra tiene más gente que hace ejercicio"},{"id":"i3","texto":"El resultado muestra mucha actividad física"},{"id":"i4","texto":"Se concluye que toda la ciudad hace mucho ejercicio"},{"id":"i5","texto":"La muestra del gimnasio representa bien a toda la ciudad"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El problema no es el cálculo: es a quién se le preguntó."}},{"slug":"ciencia-1.s3.p9","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 120, 118, 122, 119, 121. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":120,"tolerancia":2.4,"explicacion":"(120 + 118 + 122 + 119 + 121) ÷ 5 = 120. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p9.v2","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 48, 52, 50, 49, 51. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(48 + 52 + 50 + 49 + 51) ÷ 5 = 50. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p9.v3","orden":9,"grupo":"ciencia-1.s3.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cinco mediciones repetidas de lo mismo dieron: 7, 9, 8, 8, 8. ¿Cuál es el promedio?","unidad":"","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"(7 + 9 + 8 + 8 + 8) ÷ 5 = 8. Repetir y promediar reduce el efecto de los errores al azar."}},{"slug":"ciencia-1.s3.p10","orden":10,"grupo":"ciencia-1.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué mejora la calidad de una medición? Marcá todo.","opciones":[{"id":"o1","texto":"Calibrar el instrumento"},{"id":"o2","texto":"Repetir la medición varias veces"},{"id":"o3","texto":"Medir siempre con el mismo método"},{"id":"o4","texto":"Anotar las condiciones en que se midió"},{"id":"o5","texto":"Redondear los números para que queden lindos"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Calibrar, repetir, estandarizar y registrar. Redondear de más pierde información."}},{"slug":"ciencia-1.s3.p11","orden":11,"grupo":"ciencia-1.s3.p11","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas muestras de la más confiable a la menos, para estimar el consumo de agua de una ciudad.","items":[{"id":"i1","texto":"1.000 casas elegidas al azar en toda la ciudad"},{"id":"i2","texto":"1.000 casas de un solo barrio"},{"id":"i3","texto":"20 casas elegidas al azar"},{"id":"i4","texto":"Tu casa"}],"extremos":["Más confiable","Menos confiable"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Tamaño y representatividad importan los dos. Mil casas de un barrio no dicen lo mismo que mil al azar.","valores":{"i1":"grande y representativa","i2":"grande pero sesgada","i3":"representativa pero chica","i4":"un solo caso"}}},{"slug":"ciencia-1.s3.p12","orden":12,"grupo":"ciencia-1.s3.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta conclusión y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"Medimos la temperatura con un termómetro calibrado, a la sombra."},{"id":"s2","texto":"Le preguntamos a 5 compañeros y el 100 % recicla: en la ciudad todos reciclan."},{"id":"s3","texto":"Repetimos cada medición tres veces y promediamos."},{"id":"s4","texto":"La balanza marcaba 50 g vacía, pero no importa porque pesamos muchas veces."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Muestras y errores: dos lugares donde se esconden las conclusiones falsas.","por_opcion":{"s2":"Muestra chica y no representativa: no se puede generalizar a la ciudad.","s4":"Es un error sistemático: hay que tarar la balanza o restar esos 50 g."}}},{"slug":"ciencia-1.s3.p13","orden":13,"grupo":"ciencia-1.s3.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una medición cercana al valor real es {{0}}; una que da valores parecidos al repetirla es {{1}}; y una muestra tiene que ser {{2}}.","banco":[{"id":"w1","texto":"exacta"},{"id":"w2","texto":"precisa"},{"id":"w3","texto":"representativa"},{"id":"w4","texto":"rápida"},{"id":"w5","texto":"redonda"},{"id":"w6","texto":"enorme"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres palabras para evaluar cualquier dato."}}]},{"slug":"ciencia-1.s4","orden":4,"tipo":"leccion","titulo_es":"Correlación no es causa","bajada_es":"Cuando dos cosas suben juntas, no siempre una causa la otra. Terceras variables, azar y causas inversas.","minutos":11,"pasos":[{"slug":"ciencia-1.s4.p1","orden":1,"grupo":"ciencia-1.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ir juntas no es causar","cuerpo":["Dos cosas están correlacionadas cuando cambian juntas: cuando una sube, la otra también sube (o baja). Pero eso no quiere decir que una cause la otra. En verano se venden más helados y también hay más ahogamientos en el mar. Los helados no causan ahogamientos: el calor hace que haya más helados y más gente bañándose.","Ese calor es una tercera variable, o variable de confusión: causa las dos cosas y hace que parezcan relacionadas."]},"solucion":{}},{"slug":"ciencia-1.s4.p2","orden":2,"grupo":"ciencia-1.s4.p2","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En verano suben las ventas de helado y también los casos de insolación. ¿Cuál es la explicación más probable?","opciones":[{"id":"o1","texto":"El calor causa las dos cosas"},{"id":"o2","texto":"Los helados causan insolación"},{"id":"o3","texto":"La insolación hace que la gente coma helado"},{"id":"o4","texto":"Es pura casualidad y no hay relación"}]},"solucion":{"clave":["o1"],"explicacion":"Una tercera variable, el calor, explica las dos. Es el caso típico de correlación sin causalidad directa.","por_opcion":{"o3":"Es posible que alguien con calor coma helado, pero la causa común de las dos cosas es el calor."}}},{"slug":"ciencia-1.s4.p3","orden":3,"grupo":"ciencia-1.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres trampas","cuerpo":["Cuando dos cosas aparecen juntas, hay varias posibilidades además de que A cause B: puede ser que B cause A (causa inversa), que una tercera variable cause las dos (confusión) o que sea casualidad, sobre todo si se buscan muchas relaciones a la vez.","Para saber si hay causa, hacen falta experimentos, un mecanismo que lo explique o muchos estudios que descarten las otras opciones."]},"solucion":{}},{"slug":"ciencia-1.s4.p4","orden":4,"grupo":"ciencia-1.s4.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada caso con la trampa que representa.","izquierda":[{"id":"a1","texto":"Barrios con más bomberos tienen más incendios"},{"id":"a2","texto":"Ciudades con más plazas tienen más perros"},{"id":"a3","texto":"Un año la venta de paraguas coincidió con goles de un equipo"},{"id":"a4","texto":"Más horas de estudio, mejores notas"}],"derecha":[{"id":"b1","texto":"Causa inversa: más incendios llevan a poner más bomberos"},{"id":"b2","texto":"Tercera variable: el tamaño de la ciudad"},{"id":"b3","texto":"Casualidad"},{"id":"b4","texto":"Probable causa, confirmable con más evidencia"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"No todo lo que va junto se explica igual. Pensar las alternativas es parte del método."}},{"slug":"ciencia-1.s4.p5","orden":5,"grupo":"ciencia-1.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si dos cosas están muy correlacionadas, entonces una causa la otra.","razones":[{"id":"r1","texto":"Porque puede haber otra variable, causa inversa o casualidad"},{"id":"r2","texto":"Porque la correlación siempre es casualidad"},{"id":"r3","texto":"Porque las cosas correlacionadas nunca están relacionadas"}]},"solucion":{"valor":false,"explicacion":"Puede haber causa inversa, una tercera variable o casualidad. La correlación es una pista, no una prueba de causa.","clave":["r1"]}},{"slug":"ciencia-1.s4.p6","orden":6,"grupo":"ciencia-1.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuando sí hay causa","cuerpo":["A veces la correlación sí refleja una causa, y la ciencia lo muestra con varias líneas de evidencia. Que el aumento del CO₂ causa calentamiento se sabe no solo porque las dos cosas subieron juntas, sino porque hay un mecanismo físico conocido desde el siglo XIX (el CO₂ absorbe radiación infrarroja), experimentos de laboratorio, mediciones satelitales de la energía que sale de la Tierra y modelos que solo reproducen el calentamiento observado si incluyen los gases emitidos por las personas."]},"solucion":{}},{"slug":"ciencia-1.s4.p7","orden":7,"grupo":"ciencia-1.s4.p7","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tipos de evidencia muestran que el CO₂ emitido por las personas causa calentamiento? Marcá todos.","opciones":[{"id":"o1","texto":"Un mecanismo físico conocido: el CO₂ absorbe radiación infrarroja"},{"id":"o2","texto":"Experimentos de laboratorio"},{"id":"o3","texto":"Mediciones satelitales de la energía que sale de la Tierra"},{"id":"o4","texto":"Modelos que solo reproducen el calentamiento con esos gases"},{"id":"o5","texto":"Que en un invierno hizo más calor de lo normal"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un solo invierno no prueba nada. La causa se establece con varias líneas de evidencia que coinciden."}},{"slug":"ciencia-1.s4.p8","orden":8,"grupo":"ciencia-1.s4.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se pasa de una correlación a una causa establecida.","items":[{"id":"i1","texto":"Se observa que dos cosas cambian juntas"},{"id":"i2","texto":"Se proponen explicaciones posibles"},{"id":"i3","texto":"Se buscan un mecanismo y experimentos"},{"id":"i4","texto":"Se descartan terceras variables y la causa inversa"},{"id":"i5","texto":"Muchas líneas de evidencia coinciden"},{"id":"i6","texto":"Se publica la correlación y queda probado"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La causa se construye con evidencia acumulada, no con un gráfico."}},{"slug":"ciencia-1.s4.p9","orden":9,"grupo":"ciencia-1.s4.p9","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conclusión se puede sacar en cada caso?","grupos":[{"id":"g1","nombre":"Solo correlación (no alcanza para causa)"},{"id":"g2","nombre":"Causa con evidencia experimental"}],"items":[{"id":"i1","texto":"En los barrios con más árboles vive gente con más ingresos"},{"id":"i2","texto":"En un ensayo con grupos al azar, el compost aumentó el crecimiento"},{"id":"i3","texto":"En los días de más tránsito hay más consultas por asma"},{"id":"i4","texto":"En laboratorio, más CO₂ absorbe más radiación infrarroja"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Los experimentos con grupos al azar y los mecanismos físicos son las pruebas más fuertes de causa."}},{"slug":"ciencia-1.s4.p10","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 100 mil helados y hubo 20 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"100 ÷ 20 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p10.v2","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 150 mil helados y hubo 30 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"150 ÷ 30 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p10.v3","orden":10,"grupo":"ciencia-1.s4.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En un mes se vendieron 80 mil helados y hubo 16 insolaciones en una ciudad. Un periodista calcula 5 mil helados por insolación. ¿Cuántos mil helados por insolación dice?","unidad":"mil helados","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"80 ÷ 16 = 5. La cuenta está bien, pero no significa nada: los helados no causan insolación. Un número bien calculado puede no tener sentido."}},{"slug":"ciencia-1.s4.p11","orden":11,"grupo":"ciencia-1.s4.p11","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un estudio encuentra que quienes toman más café viven más años. ¿Qué pregunta conviene hacerse primero?","opciones":[{"id":"o1","texto":"¿Hay otra variable que explique las dos cosas?"},{"id":"o2","texto":"¿Cuántas tazas de café tengo que tomar para vivir más?"},{"id":"o3","texto":"¿Qué marca de café tomaban los que vivieron más?"},{"id":"o4","texto":"¿Por qué el café es tan bueno para la salud de todos?"}]},"solucion":{"clave":["o1"],"explicacion":"Ingresos, hábitos o salud previa podrían explicar las dos cosas. Antes de concluir causa, se buscan terceras variables.","por_opcion":{"o3":"Primero hay que ver si la relación es causal; la marca es un detalle posterior."}}},{"slug":"ciencia-1.s4.p12","orden":12,"grupo":"ciencia-1.s4.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas ayudan a evaluar si una correlación es causa? Marcá todas.","opciones":[{"id":"o1","texto":"¿Podría ser al revés, que B cause A?"},{"id":"o2","texto":"¿Hay una tercera variable que cause las dos?"},{"id":"o3","texto":"¿Hay un mecanismo que lo explique?"},{"id":"o4","texto":"¿Se confirmó con experimentos o muchos estudios?"},{"id":"o5","texto":"¿El gráfico tiene colores lindos?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas que desarman la mayoría de las conclusiones apuradas."}},{"slug":"ciencia-1.s4.p13","orden":13,"grupo":"ciencia-1.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este titular y marcá lo que no se puede concluir de los datos.","segmentos":[{"id":"s1","texto":"Los barrios con más árboles tienen menos casos de golpes de calor."},{"id":"s2","texto":"Plantar un árbol evita que tu familia tenga un golpe de calor."},{"id":"s3","texto":"Los investigadores midieron temperaturas más bajas bajo los árboles."},{"id":"s4","texto":"Por lo tanto, los golpes de calor solo dependen de los árboles."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Los datos pueden ser ciertos y la conclusión exagerada. Leer con cuidado es separar las dos cosas.","por_opcion":{"s2":"Es una correlación de barrios; no prueba el efecto individual y puede haber otras variables, como el ingreso.","s4":"Dependen de muchas cosas: edad, salud, vivienda, trabajo, agua."}}},{"slug":"ciencia-1.s4.p14","orden":14,"grupo":"ciencia-1.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Que dos cosas cambien juntas es una {{0}}; una variable que causa las dos es una variable de {{1}}; y para probar causa ayudan los {{2}}.","banco":[{"id":"w1","texto":"correlación"},{"id":"w2","texto":"confusión"},{"id":"w3","texto":"experimentos"},{"id":"w4","texto":"causa"},{"id":"w5","texto":"control"},{"id":"w6","texto":"rumores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La idea más importante de la lección, en una sola línea."}}]},{"slug":"ciencia-1.s5","orden":5,"tipo":"leccion","titulo_es":"Cómo avanza la ciencia","bajada_es":"Revisión por pares, réplica, consenso e incertidumbre: por qué la ciencia es confiable justamente porque se corrige.","minutos":12,"pasos":[{"slug":"ciencia-1.s5.p1","orden":1,"grupo":"ciencia-1.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Revisión y réplica","cuerpo":["Cuando un equipo científico obtiene un resultado, lo publica en una revista especializada. Antes de publicarse, otros especialistas lo revisan en busca de errores: es la revisión por pares. Después, otros equipos intentan repetir el estudio (réplica) o lo ponen a prueba con otros métodos.","Un resultado aislado puede estar equivocado. Un resultado que muchos equipos independientes confirman con métodos distintos es mucho más confiable."]},"solucion":{}},{"slug":"ciencia-1.s5.p2","orden":2,"grupo":"ciencia-1.s5.p2","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená el recorrido típico de un resultado científico.","items":[{"id":"i1","texto":"Un equipo investiga y obtiene un resultado"},{"id":"i2","texto":"Lo envía a una revista especializada"},{"id":"i3","texto":"Otros especialistas lo revisan antes de publicarlo"},{"id":"i4","texto":"Se publica"},{"id":"i5","texto":"Otros equipos intentan replicarlo o ponerlo a prueba"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La ciencia no termina con la publicación: ahí empieza la prueba de fuego."}},{"slug":"ciencia-1.s5.p3","orden":3,"grupo":"ciencia-1.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El consenso","cuerpo":["Cuando la gran mayoría de los especialistas coincide en una conclusión, después de revisar toda la evidencia, se habla de consenso científico. No es una votación ni una opinión de moda: es el resultado de miles de estudios que apuntan en la misma dirección.","Sobre el cambio climático, distintos estudios encontraron que alrededor del 97 % o más de los científicos del clima que publican sobre el tema coinciden en que el calentamiento reciente es causado por las actividades humanas. El IPCC, que reúne a miles de especialistas, lo resume así en sus informes."],"destacado":{"valor":"≥ 97 %","texto":"de los científicos del clima que publican sobre el tema coincide en que el calentamiento reciente es causado por las personas."}},"solucion":{}},{"slug":"ciencia-1.s5.p4","orden":4,"grupo":"ciencia-1.s5.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El consenso científico es una votación entre científicos sobre lo que prefieren creer.","razones":[{"id":"r1","texto":"Porque surge de mucha evidencia independiente que coincide"},{"id":"r2","texto":"Porque los científicos votan una vez por año"},{"id":"r3","texto":"Porque el consenso se decide por mayoría política"}]},"solucion":{"valor":false,"explicacion":"Es la coincidencia a la que se llega después de revisar muchísima evidencia de estudios independientes. No se decide por preferencia, sino por datos.","clave":["r1"]}},{"slug":"ciencia-1.s5.p5","orden":5,"grupo":"ciencia-1.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Incertidumbre no es ignorancia","cuerpo":["La ciencia expresa sus resultados con incertidumbre: rangos y probabilidades. Decir \"el calentamiento será de entre 2 y 3 °C con tal escenario\" no significa que no se sepa nada: significa que se conoce con bastante precisión dentro de ese rango.","Que haya incertidumbre en los detalles no quiere decir que haya duda sobre lo principal. Se sabe con certeza que la Tierra se calentó y por qué; hay más incertidumbre sobre cuánto exactamente se calentará cada región."]},"solucion":{}},{"slug":"ciencia-1.s5.p6","orden":6,"grupo":"ciencia-1.s5.p6","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un informe dice que el calentamiento será \"probablemente\" de entre 2 y 3 °C en cierto escenario. ¿Qué significa?","opciones":[{"id":"o1","texto":"Que los científicos estiman un rango con alta probabilidad"},{"id":"o2","texto":"Que los científicos no tienen idea de lo que va a pasar"},{"id":"o3","texto":"Que va a ser exactamente 2,5 °C"},{"id":"o4","texto":"Que el calentamiento podría ser negativo"}]},"solucion":{"clave":["o1"],"explicacion":"La incertidumbre bien expresada es una fortaleza: dice qué tan seguros estamos.","por_opcion":{"o3":"Es un rango, no un valor exacto: expresa la incertidumbre honestamente."}}},{"slug":"ciencia-1.s5.p7","orden":7,"grupo":"ciencia-1.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corregirse es una virtud","cuerpo":["La ciencia cambia cuando aparece evidencia nueva. Eso no es una debilidad: es lo que la hace confiable. El agujero de ozono, por ejemplo, se detectó en la década de 1980, se identificaron sus causas (los clorofluorocarbonos, CFC), el mundo los prohibió con el Protocolo de Montreal y hoy la capa de ozono se está recuperando lentamente.","Quien nunca cambia de opinión frente a la evidencia no está haciendo ciencia."]},"solucion":{}},{"slug":"ciencia-1.s5.p8","orden":8,"grupo":"ciencia-1.s5.p8","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena del caso del agujero de ozono.","items":[{"id":"i1","texto":"Se detecta una disminución del ozono sobre la Antártida"},{"id":"i2","texto":"Los científicos identifican a los CFC como causa"},{"id":"i3","texto":"Los países firman el Protocolo de Montreal"},{"id":"i4","texto":"Se dejan de producir los CFC"},{"id":"i5","texto":"La capa de ozono empieza a recuperarse"},{"id":"i6","texto":"El agujero se cerró solo sin que nadie hiciera nada"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un ejemplo de ciencia que detecta, explica y guía una solución que funciona."}},{"slug":"ciencia-1.s5.p9","orden":9,"grupo":"ciencia-1.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una señal de buena ciencia o de mala ciencia?","grupos":[{"id":"g1","nombre":"Buena ciencia"},{"id":"g2","nombre":"Mala ciencia"}],"items":[{"id":"i1","texto":"Publicar los datos para que otros los revisen"},{"id":"i2","texto":"Ocultar los datos para que nadie los revise"},{"id":"i3","texto":"Cambiar la conclusión ante evidencia nueva"},{"id":"i4","texto":"Elegir solo los resultados que convienen"},{"id":"i5","texto":"Informar la incertidumbre de los resultados"},{"id":"i6","texto":"Presentar un solo estudio como prueba definitiva"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Transparencia, humildad frente a la evidencia y honestidad sobre la incertidumbre."}},{"slug":"ciencia-1.s5.p10","orden":10,"grupo":"ciencia-1.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace que una conclusión científica sea muy confiable? Marcá todo.","opciones":[{"id":"o1","texto":"Que muchos equipos independientes la confirmen"},{"id":"o2","texto":"Que se base en métodos distintos que coinciden"},{"id":"o3","texto":"Que haya pasado revisión por pares"},{"id":"o4","texto":"Que exista un mecanismo que la explique"},{"id":"o5","texto":"Que la diga una persona famosa"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"La fama no es evidencia. La coincidencia de muchos estudios independientes, sí."}},{"slug":"ciencia-1.s5.p11","orden":11,"grupo":"ciencia-1.s5.p11","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada concepto con su definición.","izquierda":[{"id":"a1","texto":"Revisión por pares"},{"id":"a2","texto":"Réplica"},{"id":"a3","texto":"Consenso"},{"id":"a4","texto":"Incertidumbre"}],"derecha":[{"id":"b1","texto":"Especialistas revisan un trabajo antes de publicarlo"},{"id":"b2","texto":"Otro equipo repite el estudio para ver si da igual"},{"id":"b3","texto":"Coincidencia de la mayoría de especialistas basada en la evidencia"},{"id":"b4","texto":"Rango dentro del cual se estima un valor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro palabras para entender por qué se puede confiar en la ciencia sin que sea infalible."}},{"slug":"ciencia-1.s5.p12","orden":12,"grupo":"ciencia-1.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario en redes y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los científicos revisan los trabajos de otros antes de publicarlos."},{"id":"s2","texto":"Si la ciencia cambia de opinión, es que no sirve."},{"id":"s3","texto":"El Protocolo de Montreal ayudó a recuperar la capa de ozono."},{"id":"s4","texto":"Como hay incertidumbre, no se sabe si el clima está cambiando."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Confiar en la ciencia no es creer ciegamente: es entender cómo se construye.","por_opcion":{"s2":"Corregirse ante evidencia nueva es justamente lo que la hace confiable.","s4":"La incertidumbre está en los detalles; que el clima cambia por las personas está establecido."}}},{"slug":"ciencia-1.s5.p13","orden":13,"grupo":"ciencia-1.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Antes de publicarse, un estudio pasa por la revisión por {{0}}; cuando otros lo repiten se habla de {{1}}; y el agujero de ozono se enfrentó con el Protocolo de {{2}}.","banco":[{"id":"w1","texto":"pares"},{"id":"w2","texto":"réplica"},{"id":"w3","texto":"Montreal"},{"id":"w4","texto":"votos"},{"id":"w5","texto":"copia"},{"id":"w6","texto":"Kioto"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas sobre cómo avanza y se aplica la ciencia."}},{"slug":"ciencia-1.s5.p14","orden":14,"grupo":"ciencia-1.s5.p14","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá qué porcentaje de los científicos del clima que publican sobre el tema coincide en que el calentamiento reciente es causado por las personas.","min":0,"max":100,"paso":1,"unidad":"%","escala":"lineal"},"solucion":{"valor":97,"banda":"lineal","explicacion":"Alrededor del 97 % o más, según varios estudios que analizaron miles de publicaciones. Es uno de los consensos más sólidos de la ciencia actual."}}]},{"slug":"ciencia-1.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: cómo sabemos lo que sabemos","bajada_es":"Observación, experimentos, mediciones, causalidad y consenso, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-1.s6.p1","orden":1,"grupo":"ciencia-1.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Cómo sabemos lo que sabemos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-1.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el experimento de las macetas","bajada_es":"Un curso quiere probar si el agua de lluvia es mejor que el agua de red para las plantas. Revisá su diseño y sus conclusiones.","minutos":10,"pasos":[{"slug":"ciencia-1.s7.p1","orden":1,"grupo":"ciencia-1.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El diseño original","cuerpo":["Un curso puso 2 macetas: una regada con agua de lluvia, junto a la ventana, y otra regada con agua de red, en un rincón. A la de lluvia le pusieron una semilla de girasol y a la de red, una de poroto. Después de un mes, la de lluvia medía 30 cm y la de red 12 cm. Concluyeron: \"el agua de lluvia hace crecer más del doble a las plantas\"."]},"solucion":{}},{"slug":"ciencia-1.s7.p2","orden":2,"grupo":"ciencia-1.s7.p2","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas tiene el diseño? Marcá todos.","opciones":[{"id":"o1","texto":"Solo una maceta por grupo"},{"id":"o2","texto":"Distinta luz entre las macetas"},{"id":"o3","texto":"Distinta especie de planta en cada maceta"},{"id":"o4","texto":"No se controlaron otras variables, como la cantidad de agua"},{"id":"o5","texto":"Midieron la altura con una regla"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Tres cosas cambiaron a la vez: el agua, la luz y la especie. Así no se sabe qué causó la diferencia."}},{"slug":"ciencia-1.s7.p3","orden":3,"grupo":"ciencia-1.s7.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué conclusión se puede sacar de verdad del experimento original?","opciones":[{"id":"o1","texto":"Ninguna sobre el agua, porque cambiaron varias cosas"},{"id":"o2","texto":"Que el agua de lluvia hace crecer el doble a cualquier planta"},{"id":"o3","texto":"Que el agua de red es tóxica para las plantas"},{"id":"o4","texto":"Que los girasoles prefieren el agua de lluvia"}]},"solucion":{"clave":["o1"],"explicacion":"Con variables mezcladas, el experimento no responde la pregunta. Hay que rediseñarlo.","por_opcion":{"o3":"No hay evidencia de eso: la de red tenía otra especie y menos luz."}}},{"slug":"ciencia-1.s7.p4","orden":4,"grupo":"ciencia-1.s7.p4","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos del diseño corregido.","items":[{"id":"i1","texto":"Elegir una sola especie y semillas parecidas"},{"id":"i2","texto":"Preparar 10 macetas iguales para cada tipo de agua"},{"id":"i3","texto":"Asignar al azar qué maceta recibe cada agua"},{"id":"i4","texto":"Ponerlas todas con la misma luz y regarlas con la misma cantidad"},{"id":"i5","texto":"Medir la altura de todas y comparar los promedios"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Una sola diferencia entre grupos, repeticiones, azar y comparación de promedios."}},{"slug":"ciencia-1.s7.p5","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 18,4 cm y con agua de red 17,9 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.5,"tolerancia":0.05,"explicacion":"18,4 − 17,9 = 0,5 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p5.v2","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 20,2 cm y con agua de red 19,8 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.4,"tolerancia":0.05,"explicacion":"20,2 − 19,8 = 0,4 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p5.v3","orden":5,"grupo":"ciencia-1.s7.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con el diseño corregido, el promedio con agua de lluvia fue 15,6 cm y con agua de red 15,1 cm. ¿Cuál es la diferencia en cm?","unidad":"cm","decimales":1},"solucion":{"valor":0.5,"tolerancia":0.05,"explicacion":"15,6 − 15,1 = 0,5 cm. Una diferencia chica, que puede ser del azar: muy lejos del \"doble\" del primer experimento."}},{"slug":"ciencia-1.s7.p6","orden":6,"grupo":"ciencia-1.s7.p6","tipo":"vf","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con el diseño corregido, una diferencia de medio centímetro entre promedios prueba que el agua de lluvia es mejor.","razones":[{"id":"r1","texto":"Porque una diferencia chica puede deberse al azar"},{"id":"r2","texto":"Porque medio centímetro es una diferencia enorme"},{"id":"r3","texto":"Porque el diseño corregido sigue teniendo tres variables mezcladas"}]},"solucion":{"valor":false,"explicacion":"Una diferencia tan chica puede deberse al azar. Habría que ver cuánto varían las plantas dentro de cada grupo, repetir el experimento o usar más macetas.","clave":["r1"]}},{"slug":"ciencia-1.s7.p7","orden":7,"grupo":"ciencia-1.s7.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"Clasificá las conclusiones que propone el curso después del diseño corregido.","grupos":[{"id":"g1","nombre":"Bien fundada"},{"id":"g2","nombre":"No fundada"}],"items":[{"id":"i1","texto":"Con estas condiciones, no encontramos una diferencia clara"},{"id":"i2","texto":"El agua de red es mala para todas las plantas"},{"id":"i3","texto":"Habría que repetir con más macetas para estar seguros"},{"id":"i4","texto":"El primer experimento demostró que la lluvia duplica el crecimiento"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Una buena conclusión dice lo que los datos muestran, con sus límites."}},{"slug":"ciencia-1.s7.p8","orden":8,"grupo":"ciencia-1.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"El curso escribe su informe final. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"En el primer diseño cambiaron varias variables a la vez."},{"id":"s2","texto":"El primer experimento probó que la lluvia duplica el crecimiento."},{"id":"s3","texto":"Con el diseño corregido, la diferencia fue muy chica."},{"id":"s4","texto":"Como no encontramos diferencia, la ciencia no sirve."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Reconocer los errores del primer diseño y aceptar un resultado \"aburrido\" es hacer ciencia de verdad.","por_opcion":{"s2":"No probó nada sobre el agua: la luz y la especie también cambiaban.","s4":"No encontrar diferencia también es un resultado válido: responde la pregunta."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"ciencia-2","rama":"ciencia","orden":2,"nivel":1,"titulo_es":"Leer gráficos y datos","bajada_es":"Un gráfico puede aclarar o engañar. Cómo elegir el gráfico justo, ver una tendencia en medio del ruido y no caer en trampas con porcentajes.","objetivos_es":["Elegir el tipo de gráfico adecuado para cada pregunta","Distinguir una tendencia de la variabilidad de corto plazo","Detectar recursos visuales que distorsionan un gráfico","Elegir entre promedio y mediana según los datos","Interpretar porcentajes, puntos porcentuales y tasas por persona"],"repasa":["ciencia-1","tronco-2"],"requiere_tronco":1,"fuentes":["noaa-co2","nasa-evidencia","owid-co2","chequeado","ipcc-ar6-syr"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-2.s1","orden":1,"tipo":"leccion","titulo_es":"Cada gráfico para su pregunta","bajada_es":"Barras, líneas, tortas y puntos: qué muestra bien cada uno y cuándo conviene una tabla.","minutos":11,"pasos":[{"slug":"ciencia-2.s1.p1","orden":1,"grupo":"ciencia-2.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuatro gráficos básicos","cuerpo":["Los gráficos de barras sirven para comparar cantidades entre categorías: emisiones de distintos países, consumo de distintos aparatos. Los gráficos de líneas muestran cómo cambia algo en el tiempo: la temperatura año a año, el CO₂ mes a mes. Los gráficos de torta muestran partes de un todo, y funcionan bien solo con pocas partes. Los gráficos de dispersión (puntos) muestran si dos variables se relacionan.","Cuando hay que ver números exactos, a veces una tabla es mejor que cualquier gráfico."]},"solucion":{}},{"slug":"ciencia-2.s1.p2","orden":2,"grupo":"ciencia-2.s1.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pregunta con el gráfico más adecuado.","izquierda":[{"id":"a1","texto":"¿Cómo cambió la temperatura media entre 1900 y hoy?"},{"id":"a2","texto":"¿Qué aparato de la casa consume más energía?"},{"id":"a3","texto":"¿Qué parte de la basura son orgánicos, plásticos y papel?"},{"id":"a4","texto":"¿Tienen menos temperatura las cuadras con más árboles?"}],"derecha":[{"id":"b1","texto":"Líneas"},{"id":"b2","texto":"Barras"},{"id":"b3","texto":"Torta"},{"id":"b4","texto":"Dispersión (puntos)"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Tiempo con líneas, comparación con barras, partes con torta, relación con puntos."}},{"slug":"ciencia-2.s1.p3","orden":3,"grupo":"ciencia-2.s1.p3","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de gráfico conviene para mostrar esto?","grupos":[{"id":"g1","nombre":"Líneas"},{"id":"g2","nombre":"Barras"},{"id":"g3","nombre":"Dispersión"}],"items":[{"id":"i1","texto":"El nivel del río Paraná mes a mes durante cinco años"},{"id":"i2","texto":"Huella de carbono de cinco alimentos"},{"id":"i3","texto":"Relación entre árboles por cuadra y temperatura"},{"id":"i4","texto":"El CO₂ del aire desde 1960"},{"id":"i5","texto":"Lluvia total de cada provincia en un año"},{"id":"i6","texto":"Relación entre tamaño de la casa y consumo de gas"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"La pregunta define el gráfico. Un gráfico lindo pero equivocado confunde."}},{"slug":"ciencia-2.s1.p4","orden":4,"grupo":"ciencia-2.s1.p4","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un gráfico de torta es una buena opción para mostrar cómo cambió la temperatura año a año.","razones":[{"id":"r1","texto":"Porque las tortas muestran partes de un todo, no cambios en el tiempo"},{"id":"r2","texto":"Porque la temperatura no se puede graficar"},{"id":"r3","texto":"Porque las tortas solo sirven para mostrar dinero"}]},"solucion":{"valor":false,"explicacion":"Las tortas muestran partes de un todo en un momento. Para cambios en el tiempo, lo adecuado es un gráfico de líneas.","clave":["r1"]}},{"slug":"ciencia-2.s1.p5","orden":5,"grupo":"ciencia-2.s1.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las partes de un gráfico","cuerpo":["Antes de interpretar un gráfico hay que leer sus partes: el título (qué muestra), los ejes (qué variable va en cada uno), las unidades (grados, toneladas, porcentaje), la escala (de cuánto en cuánto van las marcas) y la fuente (de dónde salen los datos).","Muchos errores de interpretación vienen de saltear estos pasos y mirar solo la forma del dibujo."]},"solucion":{}},{"slug":"ciencia-2.s1.p6","orden":6,"grupo":"ciencia-2.s1.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená cómo conviene leer un gráfico nuevo.","items":[{"id":"i1","texto":"Leer el título"},{"id":"i2","texto":"Ver qué variable va en cada eje y sus unidades"},{"id":"i3","texto":"Mirar la escala de los ejes"},{"id":"i4","texto":"Buscar la fuente de los datos"},{"id":"i5","texto":"Recién ahí, interpretar la forma"}],"extremos":["Primero","Último"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Primero entender qué muestra; después, qué dice."}},{"slug":"ciencia-2.s1.p7","orden":7,"grupo":"ciencia-2.s1.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico de barras sobre emisiones no dice las unidades. ¿Cuál es el problema?","opciones":[{"id":"o1","texto":"No se sabe si son totales o por persona"},{"id":"o2","texto":"Las barras quedan de un color menos lindo"},{"id":"o3","texto":"Ninguno: las barras hablan por sí solas"},{"id":"o4","texto":"Que el gráfico tiene que ser de torta"}]},"solucion":{"clave":["o1"],"explicacion":"Sin unidades, un gráfico puede comparar peras con manzanas sin que se note.","por_opcion":{"o3":"Sin unidades, el mismo dibujo puede significar cosas muy distintas."}}},{"slug":"ciencia-2.s1.p8","orden":8,"grupo":"ciencia-2.s1.p8","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué tiene que tener un buen gráfico? Marcá todo.","opciones":[{"id":"o1","texto":"Un título claro"},{"id":"o2","texto":"Ejes con nombre y unidades"},{"id":"o3","texto":"La fuente de los datos"},{"id":"o4","texto":"Una escala que no distorsione"},{"id":"o5","texto":"Efectos en 3D para que se vea más moderno"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Los efectos 3D suelen deformar las proporciones. La claridad le gana al adorno."}},{"slug":"ciencia-2.s1.p9","orden":9,"grupo":"ciencia-2.s1.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Leer barras","cuerpo":["En un gráfico de barras, la longitud de la barra representa la cantidad. Por eso el eje de las barras tiene que empezar en cero: si empieza en otro número, la diferencia entre barras parece mucho mayor de lo que es."],"datos":{"tipo":"barras","titulo":"Consumo mensual de electricidad de cuatro casas","unidad":"kWh","filas":[{"etiqueta":"Casa A","valor":180},{"etiqueta":"Casa B","valor":240},{"etiqueta":"Casa C","valor":320},{"etiqueta":"Casa D","valor":150}],"nota":"Datos de ejemplo."}},"solucion":{}},{"slug":"ciencia-2.s1.p10","orden":10,"grupo":"ciencia-2.s1.p10","tipo":"ranking","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Según ese gráfico, ordená las casas por consumo, de más a menos.","items":[{"id":"i1","texto":"Casa C"},{"id":"i2","texto":"Casa B"},{"id":"i3","texto":"Casa A"},{"id":"i4","texto":"Casa D"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Barras que empiezan en cero: la longitud es proporcional a la cantidad.","valores":{"i1":"320 kWh","i2":"240 kWh","i3":"180 kWh","i4":"150 kWh"}}},{"slug":"ciencia-2.s1.p11","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 320 kWh y otra 150 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":2.1,"tolerancia":0.1,"explicacion":"320 ÷ 150 ≈ 2,1 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p11.v2","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 240 kWh y otra 180 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":1.3,"tolerancia":0.1,"explicacion":"240 ÷ 180 ≈ 1,3 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p11.v3","orden":11,"grupo":"ciencia-2.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En ese gráfico, una casa consume 180 kWh y otra 150 kWh. ¿Cuántas veces más consume la primera? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":1.2,"tolerancia":0.1,"explicacion":"180 ÷ 150 ≈ 1,2 veces. Si el eje empieza en cero, la barra más larga debería verse ese número de veces más larga."}},{"slug":"ciencia-2.s1.p12","orden":12,"grupo":"ciencia-2.s1.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un gráfico y marcá lo que falta o está mal.","segmentos":[{"id":"s1","texto":"Título: \"Emisiones de CO₂ de cinco países, 2023\"."},{"id":"s2","texto":"El eje vertical no tiene unidades."},{"id":"s3","texto":"La fuente es el Global Carbon Project."},{"id":"s4","texto":"El eje de las barras empieza en 400 para que se note la diferencia."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un gráfico honesto muestra unidades, fuente y un eje que no distorsiona.","por_opcion":{"s2":"Sin unidades no se sabe si son toneladas, millones de toneladas o toneladas por persona.","s4":"En barras, el eje tiene que empezar en cero; si no, exagera las diferencias."}}},{"slug":"ciencia-2.s1.p13","orden":13,"grupo":"ciencia-2.s1.p13","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para mostrar cambios en el tiempo se usa un gráfico de {{0}}; para comparar categorías, de {{1}}; y el eje de las barras tiene que empezar en {{2}}.","banco":[{"id":"w1","texto":"líneas"},{"id":"w2","texto":"barras"},{"id":"w3","texto":"cero"},{"id":"w4","texto":"torta"},{"id":"w5","texto":"puntos"},{"id":"w6","texto":"diez"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres reglas básicas para elegir y leer gráficos."}}]},{"slug":"ciencia-2.s2","orden":2,"tipo":"leccion","titulo_es":"Ver la tendencia entre el ruido","bajada_es":"Subidas y bajadas de corto plazo contra cambios de largo plazo: la curva del CO₂ y la diferencia entre tiempo y clima.","minutos":14,"pasos":[{"slug":"ciencia-2.s2.p1","orden":1,"grupo":"ciencia-2.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tendencia y variabilidad","cuerpo":["Muchos datos ambientales suben y bajan todo el tiempo: la temperatura de cada día, la lluvia de cada mes. Esa variación de corto plazo se llama variabilidad o \"ruido\". La tendencia es la dirección general a lo largo de muchos años.","Un día frío no dice nada sobre la tendencia del clima, igual que un mal día no dice nada del promedio de un año. Para ver una tendencia hacen falta muchos años de datos."]},"solucion":{}},{"slug":"ciencia-2.s2.p2","orden":2,"grupo":"ciencia-2.s2.p2","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"La curva del CO₂","cuerpo":["Desde 1958 se mide el CO₂ del aire en el observatorio de Mauna Loa, en Hawái. La curva sube y baja cada año unos pocos ppm: baja en el verano del hemisferio norte, cuando los bosques del norte crecen y absorben CO₂, y sube en su invierno. Pero debajo de ese zigzag hay una tendencia clara: pasó de unas 315 ppm en 1958 a más de 420 ppm hoy."],"datos":{"tipo":"tabla","titulo":"CO₂ en Mauna Loa (promedio anual aproximado)","columnas":["Año","ppm"],"filas":[["1960","317"],["1980","339"],["2000","370"],["2020","414"],["2024","425"]],"nota":"Valores redondeados de la NOAA."}},"solucion":{}},{"slug":"ciencia-2.s2.p3","orden":3,"grupo":"ciencia-2.s2.p3","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué la curva del CO₂ de Mauna Loa sube y baja un poco cada año?","opciones":[{"id":"o1","texto":"Por la vegetación del norte en cada estación"},{"id":"o2","texto":"Porque los instrumentos fallan en invierno"},{"id":"o3","texto":"Porque las personas emiten menos CO₂ en verano"},{"id":"o4","texto":"Porque el volcán emite CO₂ solo algunos meses"}]},"solucion":{"clave":["o1"],"explicacion":"La vegetación del norte \"respira\" con las estaciones. La tendencia de fondo, en cambio, la marcan las emisiones.","por_opcion":{"o3":"Las emisiones cambian poco en el año; el zigzag viene de la vegetación."}}},{"slug":"ciencia-2.s2.p4","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 317 ppm en 1960 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":1.6,"tolerancia":0.1,"explicacion":"(414 − 317) ÷ (2020 − 1960) = 97 ÷ 60 ≈ 1,6 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p4.v2","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 339 ppm en 1980 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":1.9,"tolerancia":0.1,"explicacion":"(414 − 339) ÷ (2020 − 1980) = 75 ÷ 40 ≈ 1,9 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p4.v3","orden":4,"grupo":"ciencia-2.s2.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Según la tabla, el CO₂ era de 370 ppm en 2000 y de 414 ppm en 2020. ¿Cuántas ppm por año subió en promedio en ese período? Redondeá a un decimal.","unidad":"ppm por año","decimales":1},"solucion":{"valor":2.2,"tolerancia":0.1,"explicacion":"(414 − 370) ÷ (2020 − 2000) = 44 ÷ 20 ≈ 2,2 ppm por año. Y el ritmo fue acelerándose con las décadas."}},{"slug":"ciencia-2.s2.p5","orden":5,"grupo":"ciencia-2.s2.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si este invierno fue más frío que el anterior, el calentamiento global se detuvo.","razones":[{"id":"r1","texto":"Porque un año es variabilidad y la tendencia se mide en décadas"},{"id":"r2","texto":"Porque el calentamiento global solo ocurre en verano"},{"id":"r3","texto":"Porque un solo invierno define el clima"}]},"solucion":{"valor":false,"explicacion":"Un invierno es tiempo, no clima. La tendencia se mira en décadas: puede haber años fríos dentro de una tendencia de calentamiento.","clave":["r1"]}},{"slug":"ciencia-2.s2.p6","orden":6,"grupo":"ciencia-2.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tiempo y clima","cuerpo":["El tiempo es lo que pasa en la atmósfera en un lugar y un momento: la temperatura de hoy, la lluvia de esta semana. El clima es el promedio del tiempo durante muchos años, en general 30 o más.","Una forma de recordarlo: el tiempo es tu humor de hoy; el clima es tu personalidad."]},"solucion":{}},{"slug":"ciencia-2.s2.p7","orden":7,"grupo":"ciencia-2.s2.p7","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es un dato de tiempo o de clima?","grupos":[{"id":"g1","nombre":"Tiempo"},{"id":"g2","nombre":"Clima"}],"items":[{"id":"i1","texto":"Mañana va a llover en Rosario"},{"id":"i2","texto":"Mendoza recibe en promedio unos 200 mm de lluvia por año"},{"id":"i3","texto":"Ayer hizo 38 °C en Santiago del Estero"},{"id":"i4","texto":"En los últimos 30 años aumentaron los días de calor extremo"},{"id":"i5","texto":"Esta semana hubo mucho viento"},{"id":"i6","texto":"El noreste es más húmedo que el oeste del país"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"Clima son promedios y tendencias de muchos años. Tiempo, lo que pasa hoy."}},{"slug":"ciencia-2.s2.p8","orden":8,"grupo":"ciencia-2.s2.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué elegir un período corto puede ocultar una tendencia.","items":[{"id":"i1","texto":"Se elige un período que empieza en un año muy caluroso"},{"id":"i2","texto":"Los años siguientes son algo más fríos por variabilidad"},{"id":"i3","texto":"En ese tramo corto parece que la temperatura baja"},{"id":"i4","texto":"Se oculta la tendencia de largo plazo, que es de calentamiento"},{"id":"i5","texto":"Los años calurosos hacen que la tendencia cambie de signo"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Elegir el punto de partida a conveniencia es una trampa clásica. Por eso las tendencias se miran en décadas."}},{"slug":"ciencia-2.s2.p9","orden":9,"grupo":"ciencia-2.s2.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Promedios móviles","cuerpo":["Para ver mejor una tendencia se usan promedios móviles: en vez de graficar cada año, se grafica el promedio de, por ejemplo, 5 años alrededor de cada año. Así el zigzag se suaviza y la dirección general se ve mejor."]},"solucion":{}},{"slug":"ciencia-2.s2.p10","orden":10,"grupo":"ciencia-2.s2.p10","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Un promedio móvil de 3 años","planteo":"Temperaturas medias (°C) de cinco años seguidos: 16,1; 16,5; 16,0; 16,6; 16,8.","pasos":["Promedio de los años 1 a 3: (16,1 + 16,5 + 16,0) ÷ 3 = 16,2.","Promedio de los años 2 a 4: (16,5 + 16,0 + 16,6) ÷ 3 = 16,37.","Promedio de los años 3 a 5: (16,0 + 16,6 + 16,8) ÷ 3 = 16,47."],"resultado":"Los años sueltos suben y bajan; los promedios móviles suben de forma más pareja. Así se ve la tendencia."},"solucion":{}},{"slug":"ciencia-2.s2.p11","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 16,5; 16; 16,6 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":16.37,"tolerancia":0.02,"explicacion":"(16,5 + 16 + 16,6) ÷ 3 ≈ 16,37 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p11.v2","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 15,2; 15,8; 15,5 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":15.5,"tolerancia":0.02,"explicacion":"(15,2 + 15,8 + 15,5) ÷ 3 ≈ 15,5 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p11.v3","orden":11,"grupo":"ciencia-2.s2.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de tres años con temperaturas medias de 18; 18,4; 18,2 °C. Redondeá a dos decimales.","unidad":"°C","decimales":2},"solucion":{"valor":18.2,"tolerancia":0.02,"explicacion":"(18 + 18,4 + 18,2) ÷ 3 ≈ 18,2 °C. Promediar varios años suaviza la variabilidad."}},{"slug":"ciencia-2.s2.p12","orden":12,"grupo":"ciencia-2.s2.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a ver una tendencia real en datos ambientales? Marcá todo.","opciones":[{"id":"o1","texto":"Mirar muchos años de datos"},{"id":"o2","texto":"Usar promedios móviles"},{"id":"o3","texto":"No elegir el punto de partida a conveniencia"},{"id":"o4","texto":"Comparar con la variabilidad normal"},{"id":"o5","texto":"Mirar solo el último mes"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un mes es ruido. Décadas, promedios y honestidad con el período muestran la tendencia."}},{"slug":"ciencia-2.s2.p13","orden":13,"grupo":"ciencia-2.s2.p13","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico muestra la lluvia de un año muy seco en una provincia. ¿Qué se puede concluir sobre su clima?","opciones":[{"id":"o1","texto":"Poco: hacen falta muchos años para ver una tendencia"},{"id":"o2","texto":"Que la provincia se está convirtiendo en un desierto"},{"id":"o3","texto":"Que el cambio climático no existe en esa provincia"},{"id":"o4","texto":"Que el año siguiente también va a ser seco"}]},"solucion":{"clave":["o1"],"explicacion":"Un año es tiempo acumulado, no clima. El clima se lee en décadas.","por_opcion":{"o3":"Un año no alcanza para concluir nada sobre el clima, ni a favor ni en contra."}}},{"slug":"ciencia-2.s2.p14","orden":14,"grupo":"ciencia-2.s2.p14","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su significado.","izquierda":[{"id":"a1","texto":"Variabilidad"},{"id":"a2","texto":"Tendencia"},{"id":"a3","texto":"Promedio móvil"},{"id":"a4","texto":"Clima"}],"derecha":[{"id":"b1","texto":"Subidas y bajadas de corto plazo"},{"id":"b2","texto":"Dirección general a lo largo de muchos años"},{"id":"b3","texto":"Promedio de varios años alrededor de cada año"},{"id":"b4","texto":"Promedio del tiempo durante 30 años o más"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro términos para leer cualquier serie de datos ambientales."}},{"slug":"ciencia-2.s2.p15","orden":15,"grupo":"ciencia-2.s2.p15","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este tuit y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El CO₂ en Mauna Loa pasó de unas 315 ppm en 1958 a más de 420 ppm hoy."},{"id":"s2","texto":"Esta semana hizo frío: el calentamiento global es un invento."},{"id":"s3","texto":"La curva del CO₂ sube y baja cada año por la vegetación."},{"id":"s4","texto":"Si tomo solo de 2016 a 2018, la temperatura bajó, así que no hay calentamiento."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Tiempo contra clima, y tramos elegidos a conveniencia: las dos trampas más comunes.","por_opcion":{"s2":"Una semana es tiempo, no clima. La tendencia se mide en décadas.","s4":"Elegir un tramo corto que empieza en un año muy caluroso oculta la tendencia."}}},{"slug":"ciencia-2.s2.p16","orden":16,"grupo":"ciencia-2.s2.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"El {{0}} es lo que pasa hoy; el {{1}} es el promedio de muchos años; y para ver una tendencia se usan promedios {{2}}.","banco":[{"id":"w1","texto":"tiempo"},{"id":"w2","texto":"clima"},{"id":"w3","texto":"móviles"},{"id":"w4","texto":"viento"},{"id":"w5","texto":"pronóstico"},{"id":"w6","texto":"fijos"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"La diferencia clave para leer cualquier dato del clima."}}]},{"slug":"ciencia-2.s3","orden":3,"tipo":"leccion","titulo_es":"Gráficos que engañan","bajada_es":"Ejes recortados, escalas dobles, tramos elegidos y dibujos en 3D: cómo un gráfico puede decir algo que los datos no dicen.","minutos":11,"pasos":[{"slug":"ciencia-2.s3.p1","orden":1,"grupo":"ciencia-2.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El eje recortado","cuerpo":["Si el eje vertical de un gráfico de barras empieza en un número alto en vez de en cero, diferencias chicas parecen enormes. Una barra de 102 y otra de 100 pueden verse una el doble que la otra si el eje empieza en 98.","En los gráficos de líneas no siempre es obligatorio empezar en cero, pero hay que mirar la escala para no exagerar ni esconder un cambio."]},"solucion":{}},{"slug":"ciencia-2.s3.p2","orden":2,"grupo":"ciencia-2.s3.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El mismo dato, dos impresiones","planteo":"Un municipio reciclaba 20 toneladas por mes y pasó a 22.","pasos":["Con el eje desde 0: la barra de 22 es apenas un 10 % más alta que la de 20.","Con el eje desde 19: la barra de 20 mide 1 unidad y la de 22 mide 3: parece el triple."],"resultado":"El dato es el mismo: 10 % más. El eje recortado hace que parezca un triunfo enorme."},"solucion":{}},{"slug":"ciencia-2.s3.p3","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 20 y 22. Si el eje empieza en 19, ¿cuántas veces más alta se ve la barra de 22 que la de 20? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3,"tolerancia":0.1,"explicacion":"Se ven 3 contra 1: 3 veces. En realidad, 22 es solo 10 % más que 20."}},{"slug":"ciencia-2.s3.p3.v2","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 100 y 105. Si el eje empieza en 98, ¿cuántas veces más alta se ve la barra de 105 que la de 100? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"Se ven 7 contra 2: 3,5 veces. En realidad, 105 es solo 5 % más que 100."}},{"slug":"ciencia-2.s3.p3.v3","orden":3,"grupo":"ciencia-2.s3.p3","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Dos barras valen 50 y 55. Si el eje empieza en 48, ¿cuántas veces más alta se ve la barra de 55 que la de 50? Redondeá a un decimal.","unidad":"veces","decimales":1},"solucion":{"valor":3.5,"tolerancia":0.1,"explicacion":"Se ven 7 contra 2: 3,5 veces. En realidad, 55 es solo 10 % más que 50."}},{"slug":"ciencia-2.s3.p4","orden":4,"grupo":"ciencia-2.s3.p4","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si el eje de un gráfico de barras empieza en un número alto, las diferencias parecen más grandes de lo que son.","razones":[{"id":"r1","texto":"Porque se pierde la proporción entre las barras"},{"id":"r2","texto":"Porque las barras se vuelven más finas"},{"id":"r3","texto":"Porque el eje recortado achica las diferencias"}]},"solucion":{"valor":true,"explicacion":"Las barras recortadas pierden la proporción: diferencias chicas parecen enormes. En barras, el eje debe empezar en cero.","clave":["r1"]}},{"slug":"ciencia-2.s3.p5","orden":5,"grupo":"ciencia-2.s3.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Otras trampas","cuerpo":["Hay otros recursos que distorsionan: usar dos ejes verticales con escalas distintas para que dos líneas parezcan moverse juntas; elegir solo el tramo de años que conviene; comparar totales de países con poblaciones muy distintas sin pasar a \"por persona\"; usar íconos o dibujos en 3D donde el área crece mucho más que el valor; y no mostrar la fuente."]},"solucion":{}},{"slug":"ciencia-2.s3.p6","orden":6,"grupo":"ciencia-2.s3.p6","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada trampa con su efecto.","izquierda":[{"id":"a1","texto":"Eje de barras que no empieza en cero"},{"id":"a2","texto":"Dos ejes con escalas distintas"},{"id":"a3","texto":"Tramo de años elegido a conveniencia"},{"id":"a4","texto":"Íconos que crecen en alto y en ancho"}],"derecha":[{"id":"b1","texto":"Exagera diferencias chicas"},{"id":"b2","texto":"Hace parecer relacionadas dos cosas"},{"id":"b3","texto":"Oculta la tendencia de largo plazo"},{"id":"b4","texto":"El área crece mucho más que el valor"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro trampas frecuentes. Reconocerlas es la mejor defensa."}},{"slug":"ciencia-2.s3.p7","orden":7,"grupo":"ciencia-2.s3.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de por qué un ícono que duplica su altura engaña.","items":[{"id":"i1","texto":"Un valor se duplica"},{"id":"i2","texto":"El dibujo se agranda al doble de alto y al doble de ancho"},{"id":"i3","texto":"Su área queda cuatro veces más grande"},{"id":"i4","texto":"El ojo percibe que el valor se cuadruplicó"},{"id":"i5","texto":"El ojo solo mira la altura de los dibujos"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Por eso los gráficos con dibujos agrandados exageran los cambios."}},{"slug":"ciencia-2.s3.p8","orden":8,"grupo":"ciencia-2.s3.p8","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una práctica honesta o engañosa?","grupos":[{"id":"g1","nombre":"Honesta"},{"id":"g2","nombre":"Engañosa"}],"items":[{"id":"i1","texto":"Mostrar la serie completa de años disponibles"},{"id":"i2","texto":"Recortar el eje de un gráfico de barras"},{"id":"i3","texto":"Aclarar si los valores son totales o por persona"},{"id":"i4","texto":"Mostrar solo los años que confirman la idea"},{"id":"i5","texto":"Citar la fuente de los datos"},{"id":"i6","texto":"Usar dibujos en 3D que deforman las proporciones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La honestidad en un gráfico es mostrar todo lo necesario para interpretarlo bien."}},{"slug":"ciencia-2.s3.p9","orden":9,"grupo":"ciencia-2.s3.p9","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un gráfico compara las emisiones totales de Argentina y de Uruguay y concluye que Argentina contamina mucho más. ¿Qué falta?","opciones":[{"id":"o1","texto":"Comparar por persona, porque las poblaciones son muy distintas"},{"id":"o2","texto":"Ponerle colores más fuertes al gráfico"},{"id":"o3","texto":"Nada: el total es la única forma válida de comparar"},{"id":"o4","texto":"Comparar con el año en que Uruguay ganó un Mundial"}]},"solucion":{"clave":["o1"],"explicacion":"Argentina tiene más de diez veces la población de Uruguay. El total y el \"por persona\" responden preguntas distintas.","por_opcion":{"o3":"El total es útil, pero con poblaciones tan distintas, el dato por persona cambia la lectura."}}},{"slug":"ciencia-2.s3.p10","orden":10,"grupo":"ciencia-2.s3.p10","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué preguntas conviene hacerle a un gráfico sospechoso? Marcá todas.","opciones":[{"id":"o1","texto":"¿Dónde empieza el eje?"},{"id":"o2","texto":"¿De qué período son los datos y por qué ese?"},{"id":"o3","texto":"¿Son totales o por persona?"},{"id":"o4","texto":"¿Cuál es la fuente?"},{"id":"o5","texto":"¿Qué tan moderno es el diseño?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas que desarman la mayoría de los gráficos engañosos."}},{"slug":"ciencia-2.s3.p11","orden":11,"grupo":"ciencia-2.s3.p11","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta descripción de un afiche y marcá lo que es engañoso.","segmentos":[{"id":"s1","texto":"Muestra el reciclaje de la ciudad de 2015 a 2024."},{"id":"s2","texto":"El eje de las barras empieza en 18 toneladas."},{"id":"s3","texto":"Cita como fuente al área de ambiente del municipio."},{"id":"s4","texto":"Las bolsas dibujadas crecen en alto y en ancho según el valor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"El dato puede ser real y el dibujo, engañoso.","por_opcion":{"s2":"Así, pasar de 20 a 22 parece triplicarse.","s4":"El área crece mucho más que el valor y exagera el cambio."}}},{"slug":"ciencia-2.s3.p12","orden":12,"grupo":"ciencia-2.s3.p12","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En un gráfico de barras el eje tiene que empezar en {{0}}; comparar países sin pasar a \"por {{1}}\" puede engañar; y elegir solo algunos {{2}} oculta la tendencia.","banco":[{"id":"w1","texto":"cero"},{"id":"w2","texto":"persona"},{"id":"w3","texto":"años"},{"id":"w4","texto":"cien"},{"id":"w5","texto":"kilómetro"},{"id":"w6","texto":"colores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres trampas para detectar en cualquier gráfico."}},{"slug":"ciencia-2.s3.p13","orden":13,"grupo":"ciencia-2.s3.p13","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos cambios reales de menor a mayor, aunque un gráfico recortado los muestre distinto.","items":[{"id":"i1","texto":"De 100 a 102"},{"id":"i2","texto":"De 20 a 22"},{"id":"i3","texto":"De 50 a 60"},{"id":"i4","texto":"De 10 a 15"}],"extremos":["Menor cambio","Mayor cambio"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Calcular el cambio porcentual es la mejor forma de no depender del dibujo.","valores":{"i1":"+2 %","i2":"+10 %","i3":"+20 %","i4":"+50 %"}}}]},{"slug":"ciencia-2.s4","orden":4,"tipo":"leccion","titulo_es":"Promedio, mediana y extremos","bajada_es":"Cuándo el promedio engaña, qué es la mediana y por qué los valores extremos importan.","minutos":11,"pasos":[{"slug":"ciencia-2.s4.p1","orden":1,"grupo":"ciencia-2.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Promedio y mediana","cuerpo":["El promedio (o media) se calcula sumando todos los valores y dividiendo por la cantidad. La mediana es el valor del medio cuando se ordenan los datos de menor a mayor: la mitad está por debajo y la mitad por encima.","Si hay valores muy extremos, el promedio se mueve mucho y deja de representar a la mayoría. La mediana, en cambio, casi no cambia."]},"solucion":{}},{"slug":"ciencia-2.s4.p2","orden":2,"grupo":"ciencia-2.s4.p2","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"El consumo de agua de una cuadra","planteo":"Diez casas usan por día (litros): 300, 320, 350, 360, 380, 400, 420, 450, 480 y 5.000 (una casa con pileta y pérdida).","pasos":["Promedio: la suma es 8.460; ÷ 10 = 846 litros.","Mediana: ordenadas, las del medio son 380 y 400: (380 + 400) ÷ 2 = 390 litros."],"resultado":"El promedio (846) no representa a ninguna casa real: lo infla una sola. La mediana (390) describe mejor a la casa típica."},"solucion":{}},{"slug":"ciencia-2.s4.p3","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 3, 5, 7, 9, 41.","unidad":"","decimales":1},"solucion":{"valor":13,"tolerancia":0.26,"explicacion":"(3 + 5 + 7 + 9 + 41) ÷ 5 = 13. Un solo valor alto (41) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p3.v2","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 10, 12, 14, 16, 98.","unidad":"","decimales":1},"solucion":{"valor":30,"tolerancia":0.6,"explicacion":"(10 + 12 + 14 + 16 + 98) ÷ 5 = 30. Un solo valor alto (98) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p3.v3","orden":3,"grupo":"ciencia-2.s4.p3","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Calculá el promedio de estos datos: 2, 4, 4, 6, 24.","unidad":"","decimales":1},"solucion":{"valor":8,"tolerancia":0.16,"explicacion":"(2 + 4 + 4 + 6 + 24) ÷ 5 = 8. Un solo valor alto (24) tira el promedio muy arriba de la mayoría."}},{"slug":"ciencia-2.s4.p4","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 3, 5, 7, 9, 41?","unidad":"","decimales":0},"solucion":{"valor":7,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 7. La mediana no se deja arrastrar por el valor extremo (41)."}},{"slug":"ciencia-2.s4.p4.v2","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 10, 12, 14, 16, 98?","unidad":"","decimales":0},"solucion":{"valor":14,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 14. La mediana no se deja arrastrar por el valor extremo (98)."}},{"slug":"ciencia-2.s4.p4.v3","orden":4,"grupo":"ciencia-2.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuál es la mediana de estos datos: 2, 4, 4, 6, 24?","unidad":"","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Ordenados, el del medio es 4. La mediana no se deja arrastrar por el valor extremo (24)."}},{"slug":"ciencia-2.s4.p5","orden":5,"grupo":"ciencia-2.s4.p5","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"El promedio siempre describe bien al caso típico.","razones":[{"id":"r1","texto":"Porque los valores extremos lo arrastran"},{"id":"r2","texto":"Porque el promedio nunca cambia"},{"id":"r3","texto":"Porque la mediana y el promedio son siempre iguales"}]},"solucion":{"valor":false,"explicacion":"Si hay valores extremos, el promedio puede quedar lejos de casi todos los casos. Por eso, con datos muy desparejos, se usa la mediana.","clave":["r1"]}},{"slug":"ciencia-2.s4.p6","orden":6,"grupo":"ciencia-2.s4.p6","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Conviene usar el promedio o la mediana?","grupos":[{"id":"g1","nombre":"Mediana"},{"id":"g2","nombre":"Promedio"}],"items":[{"id":"i1","texto":"Ingresos de las familias de un país"},{"id":"i2","texto":"Temperatura media de un mes"},{"id":"i3","texto":"Consumo de agua de una cuadra con una casa que tiene pileta"},{"id":"i4","texto":"Altura de plantas de un experimento sin valores raros"},{"id":"i5","texto":"Precio de las casas de un barrio con algunas mansiones"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Con datos desparejos, la mediana. Con datos parejos, el promedio funciona bien y usa toda la información."}},{"slug":"ciencia-2.s4.p7","orden":7,"grupo":"ciencia-2.s4.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los extremos importan","cuerpo":["A veces lo más importante no es el valor típico sino los extremos. En el clima, un aumento chico del promedio de temperatura puede significar muchos más días de calor extremo. En la contaminación del aire, un promedio aceptable puede esconder días peligrosos.","Por eso, además del promedio o la mediana, conviene mirar el rango (del mínimo al máximo) y cuántas veces se supera un umbral."]},"solucion":{}},{"slug":"ciencia-2.s4.p8","orden":8,"grupo":"ciencia-2.s4.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un aumento chico del promedio multiplica los días extremos.","items":[{"id":"i1","texto":"La temperatura promedio de un lugar sube 1 °C"},{"id":"i2","texto":"Toda la distribución de días se corre hacia arriba"},{"id":"i3","texto":"Días que antes eran apenas calurosos pasan a ser extremos"},{"id":"i4","texto":"Los días de calor extremo se vuelven mucho más frecuentes"},{"id":"i5","texto":"Si sube el promedio, desaparecen los días fríos para siempre"}],"largo":4},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un corrimiento chico del centro cambia mucho las colas. Por eso 1 °C más importa tanto."}},{"slug":"ciencia-2.s4.p9","orden":9,"grupo":"ciencia-2.s4.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos conviene informar para describir bien la calidad del aire de un año? Marcá todos.","opciones":[{"id":"o1","texto":"El promedio anual"},{"id":"o2","texto":"La cantidad de días que se superó el valor guía"},{"id":"o3","texto":"El valor máximo"},{"id":"o4","texto":"En qué condiciones ocurrieron los picos"},{"id":"o5","texto":"Solo el dato del día más limpio"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Un solo número no alcanza. El típico y los extremos cuentan historias distintas."}},{"slug":"ciencia-2.s4.p10","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 12, 18, 25, 9, 30, 14, 20 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":4,"tolerancia":0.5,"explicacion":"Superan 15: 18, 25, 30, 20. Son 4 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p10.v2","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 8, 16, 22, 17, 11, 19, 26 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"Superan 15: 16, 22, 17, 19, 26. Son 5 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p10.v3","orden":10,"grupo":"ciencia-2.s4.p10","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El PM2,5 de siete días fue: 5, 7, 18, 20, 9, 3, 16 µg/m³. ¿Cuántos días superó el valor guía diario de 15 µg/m³?","unidad":"días","decimales":0},"solucion":{"valor":3,"tolerancia":0.5,"explicacion":"Superan 15: 18, 20, 16. Son 3 días de 7. Contar superaciones dice más que un promedio."}},{"slug":"ciencia-2.s4.p11","orden":11,"grupo":"ciencia-2.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En un barrio, casi todas las casas usan entre 300 y 450 litros por día y dos usan más de 4.000. ¿Qué número describe mejor a la casa típica?","opciones":[{"id":"o1","texto":"La mediana"},{"id":"o2","texto":"El promedio"},{"id":"o3","texto":"El valor máximo"},{"id":"o4","texto":"La suma de todas las casas"}]},"solucion":{"clave":["o1"],"explicacion":"Con dos valores extremos, la mediana representa mejor a la mayoría.","por_opcion":{"o3":"El máximo describe a la casa que más usa, no a la típica."}}},{"slug":"ciencia-2.s4.p12","orden":12,"grupo":"ciencia-2.s4.p12","tipo":"ordenar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Para encontrar la mediana, ordená estos consumos diarios (litros) de menor a mayor.","items":[{"id":"i1","texto":"300"},{"id":"i2","texto":"380"},{"id":"i3","texto":"420"},{"id":"i4","texto":"480"},{"id":"i5","texto":"5.000"}],"extremos":["Menor","Mayor"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Ordenados, el del medio es 420: esa es la mediana. El promedio, en cambio, sería 1.316, arrastrado por la casa de 5.000."}},{"slug":"ciencia-2.s4.p13","orden":13,"grupo":"ciencia-2.s4.p13","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este informe y marcá lo cuestionable.","segmentos":[{"id":"s1","texto":"La mediana del consumo de agua de la cuadra es 390 litros."},{"id":"s2","texto":"El promedio de 846 litros muestra que cada casa usa 846 litros."},{"id":"s3","texto":"Una casa usa 5.000 litros por día."},{"id":"s4","texto":"Como el promedio anual de PM2,5 es aceptable, nunca hubo días malos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Promedio, mediana y extremos: tres miradas que se complementan.","por_opcion":{"s2":"Una sola casa con pileta y pérdida infla el promedio: ninguna casa típica usa eso.","s4":"El promedio puede esconder picos: hay que contar los días que superan el valor guía."}}},{"slug":"ciencia-2.s4.p14","orden":14,"grupo":"ciencia-2.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La {{0}} es el valor del medio; el {{1}} se deja arrastrar por los extremos; y a veces importa contar cuántas veces se supera un {{2}}.","banco":[{"id":"w1","texto":"mediana"},{"id":"w2","texto":"promedio"},{"id":"w3","texto":"umbral"},{"id":"w4","texto":"moda"},{"id":"w5","texto":"rango"},{"id":"w6","texto":"color"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para describir datos sin engañar."}}]},{"slug":"ciencia-2.s5","orden":5,"tipo":"leccion","titulo_es":"Porcentajes, puntos y tasas","bajada_es":"El doble de un riesgo mínimo, puntos porcentuales y datos por persona: las trampas de los números relativos.","minutos":11,"pasos":[{"slug":"ciencia-2.s5.p1","orden":1,"grupo":"ciencia-2.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Porcentaje y puntos porcentuales","cuerpo":["Si el reciclaje de una ciudad pasa del 10 % al 15 %, subió 5 puntos porcentuales, pero en términos relativos subió un 50 % (porque 5 es la mitad de 10). Las dos frases son ciertas, pero suenan muy distintas.","Los puntos porcentuales miden la diferencia entre dos porcentajes; el cambio porcentual mide cuánto cambió respecto del valor inicial."]},"solucion":{}},{"slug":"ciencia-2.s5.p2","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 10 % al 15 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"15 − 10 = 5 puntos porcentuales. En términos relativos, subió un 50 %."}},{"slug":"ciencia-2.s5.p2.v2","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 20 % al 25 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"25 − 20 = 5 puntos porcentuales. En términos relativos, subió un 25 %."}},{"slug":"ciencia-2.s5.p2.v3","orden":2,"grupo":"ciencia-2.s5.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"El reciclaje de una ciudad pasó del 4 % al 6 %. ¿En cuántos puntos porcentuales subió?","unidad":"puntos porcentuales","decimales":0},"solucion":{"valor":2,"tolerancia":0.5,"explicacion":"6 − 4 = 2 puntos porcentuales. En términos relativos, subió un 50 %."}},{"slug":"ciencia-2.s5.p3","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 10 % al 15 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(15 − 10) ÷ 10 × 100 = 50 %. Mismo cambio, contado de otra forma: 5 puntos o 50 % más."}},{"slug":"ciencia-2.s5.p3.v2","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 20 % al 25 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":25,"tolerancia":0.5,"explicacion":"(25 − 20) ÷ 20 × 100 = 25 %. Mismo cambio, contado de otra forma: 5 puntos o 25 % más."}},{"slug":"ciencia-2.s5.p3.v3","orden":3,"grupo":"ciencia-2.s5.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si el reciclaje pasó del 4 % al 6 %, ¿en qué porcentaje aumentó respecto del valor inicial?","unidad":"%","decimales":0},"solucion":{"valor":50,"tolerancia":1,"explicacion":"(6 − 4) ÷ 4 × 100 = 50 %. Mismo cambio, contado de otra forma: 2 puntos o 50 % más."}},{"slug":"ciencia-2.s5.p4","orden":4,"grupo":"ciencia-2.s5.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Riesgo relativo y absoluto","cuerpo":["Un titular dice: \"tal cosa duplica el riesgo de una enfermedad\". Suena alarmante, pero depende del riesgo de partida. Si el riesgo pasa de 1 en 100.000 a 2 en 100.000, se duplicó (riesgo relativo), pero el aumento real es de 1 caso cada 100.000 personas (riesgo absoluto).","Para entender un riesgo hacen falta los dos números: cuánto cambia y desde dónde."]},"solucion":{}},{"slug":"ciencia-2.s5.p5","orden":5,"grupo":"ciencia-2.s5.p5","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"\"Un producto duplica el riesgo de una enfermedad que afecta a 1 de cada 100.000 personas.\" ¿Qué significa en números absolutos?","opciones":[{"id":"o1","texto":"Pasa de 1 a 2 casos cada 100.000 personas"},{"id":"o2","texto":"La mitad de las personas se va a enfermar"},{"id":"o3","texto":"Pasa de 1 a 200.000 casos"},{"id":"o4","texto":"El 2 % de las personas se va a enfermar"}]},"solucion":{"clave":["o1"],"explicacion":"El riesgo relativo impresiona; el absoluto dimensiona. Los dos juntos informan.","por_opcion":{"o3":"Duplicar 1 es 2: el aumento absoluto es muy chico."}}},{"slug":"ciencia-2.s5.p6","orden":6,"grupo":"ciencia-2.s5.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si un riesgo se duplica, siempre es un riesgo grande.","razones":[{"id":"r1","texto":"Porque depende de cuál era el riesgo de partida"},{"id":"r2","texto":"Porque duplicar un riesgo lo hace del 100 %"},{"id":"r3","texto":"Porque los riesgos nunca se duplican"}]},"solucion":{"valor":false,"explicacion":"Depende del valor inicial. Duplicar un riesgo mínimo sigue siendo un riesgo chico en términos absolutos; duplicar uno alto es grave.","clave":["r1"]}},{"slug":"ciencia-2.s5.p7","orden":7,"grupo":"ciencia-2.s5.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por persona","cuerpo":["Comparar totales entre lugares de distinto tamaño engaña. China emite mucho más CO₂ total que Argentina, pero por persona la comparación cambia; y países chicos con mucho consumo pueden tener emisiones por persona muy altas aunque sus totales sean chicos.","Las tasas por persona, por habitante o por cada 100.000 habitantes permiten comparar lugares de tamaños distintos. Los totales responden cuánto aporta cada lugar al problema global. Las dos miradas son útiles, para preguntas distintas."]},"solucion":{}},{"slug":"ciencia-2.s5.p8","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 180 millones de toneladas de CO₂ por año y tiene 45 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":4,"tolerancia":0.1,"explicacion":"180 ÷ 45 ≈ 4 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p8.v2","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 12 millones de toneladas de CO₂ por año y tiene 3,5 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":3.4,"tolerancia":0.1,"explicacion":"12 ÷ 3,5 ≈ 3,4 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p8.v3","orden":8,"grupo":"ciencia-2.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un país emite 5.000 millones de toneladas de CO₂ por año y tiene 1.400 millones de habitantes. ¿Cuántas toneladas por persona emite? Redondeá a un decimal.","unidad":"t por persona","decimales":1},"solucion":{"valor":3.6,"tolerancia":0.1,"explicacion":"5.000 ÷ 1.400 ≈ 3,6 t por persona. El total y el \"por persona\" responden preguntas distintas."}},{"slug":"ciencia-2.s5.p9","orden":9,"grupo":"ciencia-2.s5.p9","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Para esta pregunta conviene el total o el dato por persona?","grupos":[{"id":"g1","nombre":"Total"},{"id":"g2","nombre":"Por persona"}],"items":[{"id":"i1","texto":"¿Qué países aportan más al calentamiento global?"},{"id":"i2","texto":"¿En qué país se consume más energía por habitante?"},{"id":"i3","texto":"¿Cuánta basura tiene que procesar el relleno de la ciudad?"},{"id":"i4","texto":"¿Qué ciudad genera más basura por vecino?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"Cada pregunta tiene su número. El error es usar uno para la pregunta del otro."}},{"slug":"ciencia-2.s5.p10","orden":10,"grupo":"ciencia-2.s5.p10","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada frase con lo que realmente mide.","izquierda":[{"id":"a1","texto":"Subió 5 puntos porcentuales"},{"id":"a2","texto":"Subió un 50 %"},{"id":"a3","texto":"Duplica el riesgo"},{"id":"a4","texto":"2 casos cada 100.000"}],"derecha":[{"id":"b1","texto":"La diferencia entre dos porcentajes"},{"id":"b2","texto":"El cambio respecto del valor inicial"},{"id":"b3","texto":"El riesgo relativo"},{"id":"b4","texto":"El riesgo absoluto"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro formas de hablar de cambios. Confundirlas es muy fácil y muy común."}},{"slug":"ciencia-2.s5.p11","orden":11,"grupo":"ciencia-2.s5.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conviene preguntar ante un titular con porcentajes? Marcá todo.","opciones":[{"id":"o1","texto":"¿Es un cambio en puntos o en porcentaje?"},{"id":"o2","texto":"¿Cuál era el valor de partida?"},{"id":"o3","texto":"¿Es un total o un dato por persona?"},{"id":"o4","texto":"¿Cuál es el riesgo absoluto?"},{"id":"o5","texto":"¿Cuántas veces se compartió la nota?"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Cuatro preguntas para no dejarse llevar por un número suelto."}},{"slug":"ciencia-2.s5.p12","orden":12,"grupo":"ciencia-2.s5.p12","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo engañoso.","segmentos":[{"id":"s1","texto":"El reciclaje pasó del 10 % al 12 % de los residuos."},{"id":"s2","texto":"Es decir, el reciclaje subió 20 puntos porcentuales."},{"id":"s3","texto":"La ciudad tiene 500.000 habitantes."},{"id":"s4","texto":"Como la ciudad vecina recicla más toneladas, recicla mejor por vecino."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Puntos contra porcentaje y total contra por persona: las dos confusiones más frecuentes.","por_opcion":{"s2":"Subió 2 puntos porcentuales; en términos relativos, un 20 %.","s4":"Si tiene más habitantes, más toneladas no significa más por vecino."}}},{"slug":"ciencia-2.s5.p13","orden":13,"grupo":"ciencia-2.s5.p13","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Pasar del 10 % al 15 % es subir 5 puntos {{0}}; duplicar un riesgo es un cambio {{1}}; y para comparar países de distinto tamaño se usan datos por {{2}}.","banco":[{"id":"w1","texto":"porcentuales"},{"id":"w2","texto":"relativo"},{"id":"w3","texto":"persona"},{"id":"w4","texto":"decimales"},{"id":"w5","texto":"absoluto"},{"id":"w6","texto":"kilómetro"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para leer números relativos."}}]},{"slug":"ciencia-2.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: leer gráficos y datos","bajada_es":"Tipos de gráficos, tendencias, trampas, promedios y porcentajes, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-2.s6.p1","orden":1,"grupo":"ciencia-2.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Leer gráficos y datos». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-2.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el gráfico del concejal","bajada_es":"Un concejal presenta un gráfico para mostrar un éxito ambiental. Revisalo con todo lo que aprendiste.","minutos":10,"pasos":[{"slug":"ciencia-2.s7.p1","orden":1,"grupo":"ciencia-2.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El gráfico","cuerpo":["El concejal muestra un gráfico de barras titulado \"¡Triplicamos el reciclaje!\". Las barras muestran 20 toneladas por mes en 2023 y 22 toneladas por mes en 2024. El eje vertical empieza en 19. No dice la fuente.","Según datos del municipio, la ciudad genera unas 400 toneladas de residuos por mes, y la población creció de 100.000 a 104.000 habitantes entre esos años."]},"solucion":{}},{"slug":"ciencia-2.s7.p2","orden":2,"grupo":"ciencia-2.s7.p2","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿En qué porcentaje aumentó realmente el reciclaje, de 20 a 22 toneladas por mes?","unidad":"%","decimales":0,"contexto":"Reciclaje: 20 t/mes en 2023, 22 t/mes en 2024."},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"(22 − 20) ÷ 20 × 100 = 10 %. No se triplicó: aumentó un 10 %."}},{"slug":"ciencia-2.s7.p3","orden":3,"grupo":"ciencia-2.s7.p3","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Qué porcentaje de los residuos de la ciudad se recicla en 2024? (22 de 400 toneladas por mes)","unidad":"%","decimales":1,"contexto":"La ciudad genera 400 t/mes; recicla 22 t/mes."},"solucion":{"valor":5.5,"tolerancia":0.11,"explicacion":"22 ÷ 400 × 100 = 5,5 %. El 94,5 % sigue yendo a disposición final."}},{"slug":"ciencia-2.s7.p4","orden":4,"grupo":"ciencia-2.s7.p4","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Con 22 toneladas por mes y 104.000 habitantes, ¿cuántos kilos por habitante por mes se reciclan? Redondeá a dos decimales.","unidad":"kg por habitante","decimales":2},"solucion":{"valor":0.21,"tolerancia":0.01,"explicacion":"22 t = 22.000 kg; ÷ 104.000 ≈ 0,21 kg por habitante por mes. En 2023, con 100.000 habitantes y 20 t, eran 0,2 kg: la mejora por persona es todavía menor."}},{"slug":"ciencia-2.s7.p5","orden":5,"grupo":"ciencia-2.s7.p5","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué problemas tiene el gráfico del concejal? Marcá todos.","opciones":[{"id":"o1","texto":"El eje de las barras empieza en 19, no en cero"},{"id":"o2","texto":"El título dice \"triplicamos\" cuando el aumento fue del 10 %"},{"id":"o3","texto":"No cita la fuente"},{"id":"o4","texto":"No aclara qué parte del total de residuos representa"},{"id":"o5","texto":"Usa barras para comparar dos años"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Comparar dos años con barras está bien. Lo engañoso es el eje recortado, el título y la falta de contexto."}},{"slug":"ciencia-2.s7.p6","orden":6,"grupo":"ciencia-2.s7.p6","tipo":"opcion","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál sería un título honesto para el gráfico?","opciones":[{"id":"o1","texto":"El reciclaje subió un 10 %, a 22 toneladas por mes"},{"id":"o2","texto":"¡Triplicamos el reciclaje de la ciudad en un año!"},{"id":"o3","texto":"La ciudad ya recicla casi todo"},{"id":"o4","texto":"Somos la ciudad que más recicla del país"}]},"solucion":{"clave":["o1"],"explicacion":"Un título honesto dice el cambio real, con su magnitud.","por_opcion":{"o3":"Recicla el 5,5 % de sus residuos: está muy lejos de casi todo."}}},{"slug":"ciencia-2.s7.p7","orden":7,"grupo":"ciencia-2.s7.p7","tipo":"ranking","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas formas de presentar el dato de la más honesta a la más engañosa.","items":[{"id":"i1","texto":"Barras desde cero, con fuente y el porcentaje del total"},{"id":"i2","texto":"Barras desde cero, sin fuente"},{"id":"i3","texto":"Barras desde 19 con título \"subimos un 10 %\""},{"id":"i4","texto":"Barras desde 19 con título \"¡triplicamos!\""}],"extremos":["Más honesta","Más engañosa"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La honestidad está en el dibujo, en el título y en el contexto.","valores":{"i1":"honesta y con contexto","i2":"correcta pero incompleta","i3":"título honesto, dibujo exagerado","i4":"engañosa"}}},{"slug":"ciencia-2.s7.p8","orden":8,"grupo":"ciencia-2.s7.p8","tipo":"detectar","dificultad":4,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Un medio publica su análisis del gráfico. Marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El reciclaje aumentó un 10 %, no se triplicó."},{"id":"s2","texto":"El eje recortado hace que la barra de 2024 parezca el triple de la de 2023."},{"id":"s3","texto":"El reciclaje subió 10 puntos porcentuales."},{"id":"s4","texto":"Como el reciclaje subió, el problema de la basura está resuelto."}]},"solucion":{"clave":["s3","s4"],"explicacion":"Hasta un buen análisis puede confundir puntos con porcentajes. Revisar cada número es la tarea.","por_opcion":{"s3":"Subió un 10 % en toneladas; como porcentaje de los residuos, pasó de 5 % a 5,5 %: medio punto.","s4":"Se recicla el 5,5 %: el resto sigue yendo a disposición final."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"ciencia-3","rama":"ciencia","orden":3,"nivel":2,"titulo_es":"Fuentes y desinformación","bajada_es":"Estudios, notas, posteos y cadenas: cómo saber cuánto confiar en cada fuente, reconocer las trampas de la desinformación y verificar antes de compartir.","objetivos_es":["Distinguir fuentes primarias, secundarias y de síntesis, y su peso como evidencia","Evaluar una fuente con lectura lateral","Reconocer las técnicas más comunes de la desinformación","Explicar por qué lo falso se difunde más rápido","Verificar un contenido y responderlo sin amplificarlo"],"repasa":["ciencia-1","ciencia-2","tronco-3","consumo-2"],"requiere_tronco":2,"fuentes":["chequeado","lectura-lateral","first-draft-tipos","flicc-cook","vosoughi-2018","inoculacion","cochrane","ipcc-ar6-syr"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-3.s1","orden":1,"tipo":"leccion","titulo_es":"No todas las fuentes pesan igual","bajada_es":"De la anécdota a la revisión sistemática: tipos de fuentes y cuánta evidencia aporta cada una.","minutos":12,"pasos":[{"slug":"ciencia-3.s1.p1","orden":1,"grupo":"ciencia-3.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Primarias, secundarias y de síntesis","cuerpo":["Una fuente primaria es donde aparece por primera vez un dato o un resultado: un artículo científico con una investigación original, una base de datos oficial, un informe de mediciones. Una fuente secundaria cuenta o interpreta fuentes primarias: una nota periodística, un libro de divulgación, un video explicativo. Y hay fuentes de síntesis que reúnen y evalúan muchas investigaciones a la vez, como las revisiones sistemáticas o los informes del IPCC, que evalúan miles de estudios."]},"solucion":{}},{"slug":"ciencia-3.s1.p2","orden":2,"grupo":"ciencia-3.s1.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué tipo de fuente es cada una?","grupos":[{"id":"g1","nombre":"Primaria"},{"id":"g2","nombre":"Secundaria"},{"id":"g3","nombre":"De síntesis"}],"items":[{"id":"i1","texto":"Artículo científico con un experimento original"},{"id":"i2","texto":"Nota de un diario sobre un estudio"},{"id":"i3","texto":"Revisión sistemática de 200 estudios"},{"id":"i4","texto":"Datos de una estación que mide el CO₂"},{"id":"i5","texto":"Video de divulgación que explica una investigación"},{"id":"i6","texto":"Informe del IPCC"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Cada tipo sirve para algo: la primaria para ver el dato original, la secundaria para entender, la de síntesis para saber qué dice el conjunto."}},{"slug":"ciencia-3.s1.p3","orden":3,"grupo":"ciencia-3.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Una escalera de evidencia","cuerpo":["No todas las afirmaciones tienen el mismo respaldo. En la parte más baja están las opiniones y las anécdotas (\"a mi tío le pasó\"). Un poco más arriba, los estudios de un solo caso. Luego, los estudios observacionales, que comparan grupos sin intervenir. Después, los experimentos controlados. Y arriba de todo, las revisiones sistemáticas y los metaanálisis, que combinan muchos estudios con un método explícito.","Un estudio aislado, aunque sea bueno, puede estar equivocado. Lo más confiable es lo que muestran muchos estudios juntos."]},"solucion":{}},{"slug":"ciencia-3.s1.p4","orden":4,"grupo":"ciencia-3.s1.p4","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estas fuentes de evidencia de la más débil a la más fuerte.","items":[{"id":"i1","texto":"Anécdota de un conocido"},{"id":"i2","texto":"Estudio de un solo caso"},{"id":"i3","texto":"Estudio que compara dos grupos grandes"},{"id":"i4","texto":"Experimento controlado"},{"id":"i5","texto":"Revisión sistemática de muchos estudios"}],"extremos":["Más débil","Más fuerte"]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La escalera no dice que lo de abajo sea falso: dice cuánto peso tiene como prueba.","valores":{"i1":"opinión","i2":"un caso","i3":"observacional","i4":"experimental","i5":"síntesis"}}},{"slug":"ciencia-3.s1.p5","orden":5,"grupo":"ciencia-3.s1.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Un titular dice: \"Un estudio demuestra que el café alarga la vida\". ¿Qué conviene preguntarse primero?","opciones":[{"id":"o1","texto":"¿Qué dicen los demás estudios sobre el tema?"},{"id":"o2","texto":"¿Cuántas veces lo compartieron en redes?"},{"id":"o3","texto":"¿El periodista toma café?"},{"id":"o4","texto":"¿La foto del artículo es linda?"}]},"solucion":{"clave":["o1"],"explicacion":"Un estudio aislado es una pieza. Para saber cuánto pesa, hay que ver el conjunto de la evidencia.","por_opcion":{"o3":"Lo que importa es la evidencia, no los gustos de quien escribe."}}},{"slug":"ciencia-3.s1.p6","orden":6,"grupo":"ciencia-3.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Revisión por pares y preprints","cuerpo":["Antes de publicarse en una revista científica, un artículo suele pasar por revisión por pares: otros especialistas lo leen, piden correcciones y pueden rechazarlo. No es perfecta, pero filtra muchos errores. Un preprint, en cambio, es un artículo que se publica antes de esa revisión: sirve para compartir resultados rápido, pero hay que leerlo con más cautela. También existen revistas \"depredadoras\", que cobran por publicar sin revisar en serio."]},"solucion":{}},{"slug":"ciencia-3.s1.p7","orden":7,"grupo":"ciencia-3.s1.p7","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada término con su definición.","izquierda":[{"id":"a1","texto":"Revisión por pares"},{"id":"a2","texto":"Preprint"},{"id":"a3","texto":"Metaanálisis"},{"id":"a4","texto":"Revista depredadora"}],"derecha":[{"id":"b1","texto":"Especialistas evalúan un artículo antes de publicarlo"},{"id":"b2","texto":"Artículo publicado antes de ser revisado"},{"id":"b3","texto":"Combina estadísticamente los datos de muchos estudios"},{"id":"b4","texto":"Cobra por publicar sin revisar en serio"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Conocer estos términos ayuda a saber cuánta confianza darle a una publicación."}},{"slug":"ciencia-3.s1.p8","orden":8,"grupo":"ciencia-3.s1.p8","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si algo está publicado en una revista científica, es verdad y ya no se discute.","razones":[{"id":"r1","texto":"Porque un resultado se vuelve sólido cuando otros lo confirman"},{"id":"r2","texto":"Porque las revistas científicas publican cualquier cosa"},{"id":"r3","texto":"Porque la ciencia nunca cambia de opinión"}]},"solucion":{"valor":false,"explicacion":"La revisión por pares filtra errores, pero no garantiza que un resultado sea correcto. La confianza crece cuando otros estudios lo confirman.","clave":["r1"]}},{"slug":"ciencia-3.s1.p9","orden":9,"grupo":"ciencia-3.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una revisión encontró 40 estudios sobre un tema; 36 muestran el mismo resultado. ¿Qué porcentaje coincide? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"36 de 40 estudios muestran el mismo resultado."},"solucion":{"valor":90,"tolerancia":1,"explicacion":"36 ÷ 40 × 100 ≈ 90 %. Si alguien cita solo uno de los estudios que no coinciden, muestra una parte chica de la evidencia."}},{"slug":"ciencia-3.s1.p9.v2","orden":9,"grupo":"ciencia-3.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una revisión encontró 25 estudios sobre un tema; 21 muestran el mismo resultado. ¿Qué porcentaje coincide? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"21 de 25 estudios muestran el mismo resultado."},"solucion":{"valor":84,"tolerancia":1,"explicacion":"21 ÷ 25 × 100 ≈ 84 %. Si alguien cita solo uno de los estudios que no coinciden, muestra una parte chica de la evidencia."}},{"slug":"ciencia-3.s1.p9.v3","orden":9,"grupo":"ciencia-3.s1.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una revisión encontró 60 estudios sobre un tema; 57 muestran el mismo resultado. ¿Qué porcentaje coincide? Redondeá al entero.","unidad":"%","decimales":0,"contexto":"57 de 60 estudios muestran el mismo resultado."},"solucion":{"valor":95,"tolerancia":1,"explicacion":"57 ÷ 60 × 100 ≈ 95 %. Si alguien cita solo uno de los estudios que no coinciden, muestra una parte chica de la evidencia."}},{"slug":"ciencia-3.s1.p10","orden":10,"grupo":"ciencia-3.s1.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidado con el \"un estudio dice\"","cuerpo":["Cuando un tema tiene cientos de estudios, siempre va a haber alguno que diga lo contrario, por azar, por errores o por un diseño distinto. Elegir justo ese y presentarlo como \"la prueba\" es una trampa común. La pregunta útil no es \"¿hay algún estudio que diga X?\", sino \"¿qué dice la mayoría de la evidencia de buena calidad?\"."]},"solucion":{}},{"slug":"ciencia-3.s1.p11","orden":11,"grupo":"ciencia-3.s1.p11","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el razonamiento correcto frente a un estudio sorprendente.","items":[{"id":"i1","texto":"Aparece un estudio con un resultado sorprendente"},{"id":"i2","texto":"Se revisa cómo se hizo y quién lo hizo"},{"id":"i3","texto":"Se buscan otros estudios sobre el mismo tema"},{"id":"i4","texto":"Se compara con lo que muestra el conjunto"},{"id":"i5","texto":"Se le da el peso que corresponde"},{"id":"i6","texto":"Se comparte enseguida porque es sorprendente"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La sorpresa es una razón para mirar mejor, no para creer más rápido."}},{"slug":"ciencia-3.s1.p12","orden":12,"grupo":"ciencia-3.s1.p12","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales aumentan la confianza en un resultado científico? Marcá todas.","opciones":[{"id":"o1","texto":"Otros equipos lo replicaron"},{"id":"o2","texto":"Pasó revisión por pares"},{"id":"o3","texto":"Coincide con revisiones de muchos estudios"},{"id":"o4","texto":"Se volvió viral en redes"},{"id":"o5","texto":"Lo contradice todo lo anterior sin explicar por qué"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Lo viral no es evidencia, y un resultado que contradice todo exige pruebas extraordinarias."}},{"slug":"ciencia-3.s1.p13","orden":13,"grupo":"ciencia-3.s1.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este comentario y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Un informe del IPCC reúne y evalúa miles de estudios."},{"id":"s2","texto":"Un preprint ya pasó revisión por pares."},{"id":"s3","texto":"Una anécdota tiene menos peso que un experimento controlado."},{"id":"s4","texto":"Si encuentro un estudio que dice lo que pienso, ya está probado."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Saber cuánto pesa cada fuente evita tanto la credulidad como la desconfianza total.","por_opcion":{"s2":"Es al revés: un preprint se publica antes de la revisión.","s4":"Un estudio aislado puede estar equivocado; importa el conjunto."}}},{"slug":"ciencia-3.s1.p14","orden":14,"grupo":"ciencia-3.s1.p14","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántas referencias científicas cita el informe del Grupo de Trabajo I del IPCC (2021).","min":10,"max":1000000,"paso":1,"unidad":"referencias","escala":"log"},"solucion":{"valor":14000,"banda":"log","explicacion":"Más de 14.000. Por eso un informe del IPCC pesa mucho más que cualquier estudio aislado: resume la evidencia de miles."}},{"slug":"ciencia-3.s1.p15","orden":15,"grupo":"ciencia-3.s1.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Una nota que cuenta un estudio es una fuente {{0}}; un artículo publicado antes de ser revisado es un {{1}}; y la evidencia más fuerte viene de revisiones {{2}}.","banco":[{"id":"w1","texto":"secundaria"},{"id":"w2","texto":"preprint"},{"id":"w3","texto":"sistemáticas"},{"id":"w4","texto":"primaria"},{"id":"w5","texto":"titular"},{"id":"w6","texto":"aisladas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres términos para ubicar cualquier fuente en la escalera de evidencia."}}]},{"slug":"ciencia-3.s2","orden":2,"tipo":"leccion","titulo_es":"Leer de costado","bajada_es":"Quién lo dice, cómo lo sabe y qué dicen otros: la lectura lateral que usan los verificadores profesionales.","minutos":11,"pasos":[{"slug":"ciencia-3.s2.p1","orden":1,"grupo":"ciencia-3.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Lo que hacen los verificadores","cuerpo":["Investigadores de la Universidad de Stanford compararon cómo evaluaban sitios web desconocidos tres grupos: historiadores, estudiantes universitarios y verificadores de datos profesionales. Los dos primeros leían el sitio de arriba abajo, miraban el diseño, el \"quiénes somos\" y los logos. Los verificadores, en cambio, salían enseguida del sitio y abrían otras pestañas para averiguar quién estaba detrás. Llegaron a conclusiones correctas más rápido.","A esa estrategia se la llama lectura lateral: para saber si confiar en una fuente, se busca qué dicen otros sobre ella."]},"solucion":{}},{"slug":"ciencia-3.s2.p2","orden":2,"grupo":"ciencia-3.s2.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es la lectura lateral?","opciones":[{"id":"o1","texto":"Salir del sitio para ver qué dicen otros de la fuente"},{"id":"o2","texto":"Leer el texto completo con mucha atención"},{"id":"o3","texto":"Mirar si el diseño del sitio es profesional"},{"id":"o4","texto":"Leer solo los títulos y los subtítulos"}]},"solucion":{"clave":["o1"],"explicacion":"Leer de arriba abajo no revela quién está detrás. Buscar afuera, sí.","por_opcion":{"o3":"Un buen diseño se compra fácil: no dice nada de la confiabilidad."}}},{"slug":"ciencia-3.s2.p3","orden":3,"grupo":"ciencia-3.s2.p3","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Un sitio con buen diseño, logos y un \"quiénes somos\" prolijo es confiable.","razones":[{"id":"r1","texto":"Porque la apariencia se puede fabricar fácilmente"},{"id":"r2","texto":"Porque los sitios prolijos siempre mienten"},{"id":"r3","texto":"Porque el diseño no se puede evaluar"}]},"solucion":{"valor":false,"explicacion":"Cualquiera puede armar un sitio prolijo. Muchas organizaciones que defienden intereses particulares tienen sitios muy profesionales. Hay que averiguar quién está detrás.","clave":["r1"]}},{"slug":"ciencia-3.s2.p4","orden":4,"grupo":"ciencia-3.s2.p4","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Tres preguntas","cuerpo":["Para evaluar cualquier fuente sirven tres preguntas. ¿Quién está detrás? Una persona, una empresa, una ONG, un organismo público; qué experiencia tiene y qué intereses. ¿Cuál es la evidencia? Si cita datos, estudios o documentos que se puedan revisar. ¿Qué dicen otras fuentes? Si fuentes independientes y confiables confirman lo mismo."]},"solucion":{}},{"slug":"ciencia-3.s2.p5","orden":5,"grupo":"ciencia-3.s2.p5","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para evaluar una nota que te llega.","items":[{"id":"i1","texto":"Frenar antes de reaccionar o compartir"},{"id":"i2","texto":"Averiguar quién está detrás de la fuente"},{"id":"i3","texto":"Revisar qué evidencia presenta"},{"id":"i4","texto":"Buscar qué dicen otras fuentes independientes"},{"id":"i5","texto":"Decidir cuánto confiar y si compartir"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El primer paso es el más difícil: frenar. Las emociones empujan a compartir rápido."}},{"slug":"ciencia-3.s2.p6","orden":6,"grupo":"ciencia-3.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Intereses y conflictos","cuerpo":["Que una fuente tenga intereses no la vuelve falsa, pero sí obliga a mirarla con más cuidado. Una empresa petrolera que financia un estudio sobre clima, un fabricante que evalúa su propio producto, una ONG que necesita donaciones: todos pueden tener sesgos. Por eso las revistas científicas piden declarar los conflictos de interés y las fuentes de financiamiento."]},"solucion":{}},{"slug":"ciencia-3.s2.p7","orden":7,"grupo":"ciencia-3.s2.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Hay un posible conflicto de interés?","grupos":[{"id":"g1","nombre":"Posible conflicto"},{"id":"g2","nombre":"Sin conflicto evidente"}],"items":[{"id":"i1","texto":"Una marca de agua embotellada financia un estudio sobre agua de red"},{"id":"i2","texto":"Un organismo estadístico publica datos de censo"},{"id":"i3","texto":"Una empresa evalúa su propio producto"},{"id":"i4","texto":"Un equipo universitario sin financiamiento privado replica un estudio"},{"id":"i5","texto":"Un sitio que vende suplementos publica sus beneficios"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Detectar intereses no es acusar: es saber qué verificar con más cuidado."}},{"slug":"ciencia-3.s2.p8","orden":8,"grupo":"ciencia-3.s2.p8","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pregunta con lo que busca responder.","izquierda":[{"id":"a1","texto":"¿Quién está detrás?"},{"id":"a2","texto":"¿Cuál es la evidencia?"},{"id":"a3","texto":"¿Qué dicen otros?"},{"id":"a4","texto":"¿De cuándo es?"}],"derecha":[{"id":"b1","texto":"Autoría, experiencia e intereses"},{"id":"b2","texto":"Datos o estudios que se puedan revisar"},{"id":"b3","texto":"Confirmación por fuentes independientes"},{"id":"b4","texto":"Si la información está actualizada"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro preguntas rápidas que evitan la mayoría de los engaños."}},{"slug":"ciencia-3.s2.p9","orden":9,"grupo":"ciencia-3.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una web llamada \"Instituto para la Energía Limpia y Barata\" dice que los autos eléctricos contaminan más que los de nafta. ¿Qué hacés primero?","opciones":[{"id":"o1","texto":"Buscar quién financia ese instituto"},{"id":"o2","texto":"Confiar, porque el nombre suena científico"},{"id":"o3","texto":"Descartarlo sin mirar, porque seguro miente"},{"id":"o4","texto":"Compartirlo para ver qué opinan tus amigos"}]},"solucion":{"clave":["o1"],"explicacion":"Los nombres institucionales pueden esconder intereses. La lectura lateral lo revela en minutos.","por_opcion":{"o3":"No hay que creer ni descartar a ciegas: hay que averiguar."}}},{"slug":"ciencia-3.s2.p10","orden":10,"grupo":"ciencia-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si chequear una fuente con lectura lateral lleva 2 minutos y hoy te llegaron 5 notas dudosas, ¿cuántos minutos te lleva chequearlas todas?","unidad":"minutos","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"2 × 5 = 10 minutos. Un costo chico comparado con el de difundir algo falso a todos tus contactos."}},{"slug":"ciencia-3.s2.p10.v2","orden":10,"grupo":"ciencia-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si chequear una fuente con lectura lateral lleva 3 minutos y hoy te llegaron 4 notas dudosas, ¿cuántos minutos te lleva chequearlas todas?","unidad":"minutos","decimales":0},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"3 × 4 = 12 minutos. Un costo chico comparado con el de difundir algo falso a todos tus contactos."}},{"slug":"ciencia-3.s2.p10.v3","orden":10,"grupo":"ciencia-3.s2.p10","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si chequear una fuente con lectura lateral lleva 1 minuto y hoy te llegaron 10 notas dudosas, ¿cuántos minutos te lleva chequearlas todas?","unidad":"minutos","decimales":0},"solucion":{"valor":10,"tolerancia":0.5,"explicacion":"1 × 10 = 10 minutos. Un costo chico comparado con el de difundir algo falso a todos tus contactos."}},{"slug":"ciencia-3.s2.p11","orden":11,"grupo":"ciencia-3.s2.p11","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué indicios hacen dudar de una fuente? Marcá todos.","opciones":[{"id":"o1","texto":"No se sabe quién la escribió"},{"id":"o2","texto":"No cita ninguna evidencia verificable"},{"id":"o3","texto":"Vende un producto relacionado con lo que afirma"},{"id":"o4","texto":"La publicó un organismo con datos abiertos"},{"id":"o5","texto":"Otras fuentes independientes confirman lo mismo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Autoría oculta, falta de evidencia e intereses directos son señales de alerta."}},{"slug":"ciencia-3.s2.p12","orden":12,"grupo":"ciencia-3.s2.p12","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé cómo evaluó una fuente un compañero y marcá los errores.","segmentos":[{"id":"s1","texto":"Busqué quién financia el sitio."},{"id":"s2","texto":"Como el sitio se ve profesional, decidí confiar."},{"id":"s3","texto":"Revisé si otras fuentes confirman el dato."},{"id":"s4","texto":"Leí solo el \"quiénes somos\" del propio sitio."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La lectura lateral se aprende practicando: salir del sitio es el hábito clave.","por_opcion":{"s2":"El diseño no dice nada de la confiabilidad.","s4":"Hay que ver qué dicen otros, no solo lo que la fuente dice de sí misma."}}},{"slug":"ciencia-3.s2.p13","orden":13,"grupo":"ciencia-3.s2.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una fuente tiene intereses económicos en un tema, todo lo que dice es falso.","razones":[{"id":"r1","texto":"Porque los intereses piden más verificación, no descarte automático"},{"id":"r2","texto":"Porque ninguna fuente tiene intereses"},{"id":"r3","texto":"Porque las empresas nunca publican datos"}]},"solucion":{"valor":false,"explicacion":"Tener intereses no vuelve falsa una afirmación: obliga a verificarla con más cuidado y a buscar confirmación independiente.","clave":["r1"]}},{"slug":"ciencia-3.s2.p14","orden":14,"grupo":"ciencia-3.s2.p14","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Buscar en otras pestañas qué dicen otros de una fuente se llama lectura {{0}}; tener intereses que pueden sesgar un estudio es un conflicto de {{1}}; y el primer paso ante algo que te llega es {{2}}.","banco":[{"id":"w1","texto":"lateral"},{"id":"w2","texto":"interés"},{"id":"w3","texto":"frenar"},{"id":"w4","texto":"vertical"},{"id":"w5","texto":"opinión"},{"id":"w6","texto":"compartir"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para evaluar fuentes como lo hacen los verificadores."}}]},{"slug":"ciencia-3.s3","orden":3,"tipo":"leccion","titulo_es":"Las trampas de la desinformación","bajada_es":"Contexto falso, contenido fabricado, falsos expertos y datos elegidos a dedo: cómo reconocer las técnicas.","minutos":12,"pasos":[{"slug":"ciencia-3.s3.p1","orden":1,"grupo":"ciencia-3.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Error o engaño","cuerpo":["Conviene distinguir la información errónea, que se comparte sin intención de engañar (alguien cree que es cierta), de la desinformación, que se crea o se difunde a propósito para engañar. La diferencia importa para responder: con quien se equivocó, alcanza con mostrar el dato; con una campaña deliberada, hace falta entender a quién beneficia."]},"solucion":{}},{"slug":"ciencia-3.s3.p2","orden":2,"grupo":"ciencia-3.s3.p2","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es información errónea o desinformación?","grupos":[{"id":"g1","nombre":"Información errónea (sin intención)"},{"id":"g2","nombre":"Desinformación (a propósito)"}],"items":[{"id":"i1","texto":"Tu tía comparte una foto vieja creyendo que es de hoy"},{"id":"i2","texto":"Una red de cuentas falsas difunde el mismo mensaje"},{"id":"i3","texto":"Un compañero repite un dato mal recordado"},{"id":"i4","texto":"Una empresa inventa un estudio para vender más"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2"},"explicacion":"La intención cambia la respuesta: corregir con empatía o exponer una estrategia."}},{"slug":"ciencia-3.s3.p3","orden":3,"grupo":"ciencia-3.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Siete formas","cuerpo":["La investigadora Claire Wardle propuso siete tipos de contenido problemático, de menor a mayor intención de engañar: sátira o parodia (no busca engañar, pero puede confundir); conexión falsa (el título no coincide con el contenido); contenido engañoso (usa información real para culpar o encuadrar de forma tramposa); contexto falso (contenido real con fecha, lugar o explicación falsos); contenido impostor (imita a una fuente conocida); contenido manipulado (imagen o dato real alterado); y contenido fabricado (completamente falso)."]},"solucion":{}},{"slug":"ciencia-3.s3.p4","orden":4,"grupo":"ciencia-3.s3.p4","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada tipo con su ejemplo.","izquierda":[{"id":"a1","texto":"Contexto falso"},{"id":"a2","texto":"Contenido impostor"},{"id":"a3","texto":"Conexión falsa"},{"id":"a4","texto":"Contenido fabricado"}],"derecha":[{"id":"b1","texto":"Foto real de una inundación de 2010 presentada como de ayer"},{"id":"b2","texto":"Un sitio que copia el logo de un diario conocido"},{"id":"b3","texto":"Un título alarmante que la nota no respalda"},{"id":"b4","texto":"Una cita inventada atribuida a un científico"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"El contexto falso es de los más comunes: la imagen es real, la historia no."}},{"slug":"ciencia-3.s3.p5","orden":5,"grupo":"ciencia-3.s3.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Una foto real de un incendio en otro país circula como si fuera de Córdoba, hoy. ¿Qué tipo de contenido es?","opciones":[{"id":"o1","texto":"Contexto falso"},{"id":"o2","texto":"Contenido fabricado"},{"id":"o3","texto":"Sátira o parodia"},{"id":"o4","texto":"Contenido impostor"}]},"solucion":{"clave":["o1"],"explicacion":"La imagen es real, pero el lugar y la fecha no: eso es contexto falso, una de las formas más comunes.","por_opcion":{"o3":"No busca hacer humor: se presenta como noticia real."}}},{"slug":"ciencia-3.s3.p6","orden":6,"grupo":"ciencia-3.s3.p6","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos tipos de contenido de menor a mayor intención de engañar, según Wardle.","items":[{"id":"i1","texto":"Sátira o parodia"},{"id":"i2","texto":"Conexión falsa"},{"id":"i3","texto":"Contexto falso"},{"id":"i4","texto":"Contenido fabricado"}],"extremos":["Menos intención","Más intención"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"A mayor intención de engañar, más importante es entender quién lo difunde y para qué.","valores":{"i1":"no busca engañar","i2":"título que no coincide","i3":"contenido real mal ubicado","i4":"totalmente falso"}}},{"slug":"ciencia-3.s3.p7","orden":7,"grupo":"ciencia-3.s3.p7","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Las técnicas del negacionismo","cuerpo":["El investigador John Cook resumió las técnicas más usadas para negar consensos científicos con la sigla FLICC: falsos expertos (presentar a alguien sin experiencia en el tema como autoridad); falacias lógicas (razonamientos que no se sostienen); expectativas imposibles (exigir certeza absoluta antes de actuar); selección de datos (elegir solo los datos que convienen, conocido como cherry picking); y teorías conspirativas (sostener que los científicos se ponen de acuerdo para mentir)."]},"solucion":{}},{"slug":"ciencia-3.s3.p8","orden":8,"grupo":"ciencia-3.s3.p8","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada frase con la técnica que usa.","izquierda":[{"id":"a1","texto":"\"Un ingeniero famoso dice que el clima no cambia\""},{"id":"a2","texto":"\"Hasta que no haya certeza total, no hagamos nada\""},{"id":"a3","texto":"\"Desde aquel año récord no se calentó\""},{"id":"a4","texto":"\"Los científicos inventan todo para cobrar subsidios\""},{"id":"a5","texto":"\"El clima siempre cambió, así que ahora también es natural\""}],"derecha":[{"id":"b1","texto":"Falso experto"},{"id":"b2","texto":"Expectativa imposible"},{"id":"b3","texto":"Selección de datos"},{"id":"b4","texto":"Teoría conspirativa"},{"id":"b5","texto":"Falacia lógica"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4","a5":"b5"},"explicacion":"Reconocer la técnica permite responder aunque no conozcas el dato puntual."}},{"slug":"ciencia-3.s3.p9","orden":9,"grupo":"ciencia-3.s3.p9","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Datos elegidos a dedo","planteo":"Alguien muestra la temperatura global desde 1998, un año muy cálido por El Niño, hasta 2012, y dice: \"no se calentó\".","pasos":["Empezar la serie en un pico hace que lo que sigue parezca plano.","Si se mira desde 1970 hasta hoy, la tendencia al alza es clara.","Y los años posteriores a 2012 fueron todavía más cálidos."],"resultado":"Recortar el período es una forma de mentir con datos reales. Siempre conviene mirar la serie completa."},"solucion":{}},{"slug":"ciencia-3.s3.p10","orden":10,"grupo":"ciencia-3.s3.p10","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué trampa usa quien muestra solo 1998–2012 para decir que el planeta no se calienta?","opciones":[{"id":"o1","texto":"Selección de datos: elige el tramo que le conviene"},{"id":"o2","texto":"Contenido fabricado: los datos son inventados"},{"id":"o3","texto":"Sátira: lo dice en broma"},{"id":"o4","texto":"Falso experto: no cita a nadie"}]},"solucion":{"clave":["o1"],"explicacion":"Los datos son reales; el engaño está en el recorte. Lo viste con los gráficos engañosos.","por_opcion":{"o3":"No es broma: se presenta como un argumento serio."}}},{"slug":"ciencia-3.s3.p11","orden":11,"grupo":"ciencia-3.s3.p11","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si todos los datos de un gráfico son reales, el gráfico no puede engañar.","razones":[{"id":"r1","texto":"Porque el recorte y la escala pueden engañar con datos reales"},{"id":"r2","texto":"Porque todos los gráficos mienten"},{"id":"r3","texto":"Porque los datos reales siempre están mal"}]},"solucion":{"valor":false,"explicacion":"Puede engañar con el recorte del período, la escala de los ejes o lo que deja afuera. Datos reales no garantizan una conclusión correcta.","clave":["r1"]}},{"slug":"ciencia-3.s3.p12","orden":12,"grupo":"ciencia-3.s3.p12","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué técnicas de FLICC aparecen en este mensaje? \"Un médico dice que el cambio climático es un invento de los gobiernos para cobrar impuestos.\" Marcá todas.","opciones":[{"id":"o1","texto":"Falso experto"},{"id":"o2","texto":"Teoría conspirativa"},{"id":"o3","texto":"Selección de datos"},{"id":"o4","texto":"Expectativa imposible"}]},"solucion":{"clave":["o1","o2"],"explicacion":"Un médico no es especialista en clima, y la idea de un invento coordinado es conspirativa. El mensaje no usa datos."}},{"slug":"ciencia-3.s3.p13","orden":13,"grupo":"ciencia-3.s3.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En el tramo elegido, la temperatura media pasó de 14,3 °C a 14,4 °C. Mirando desde 1970 pasó de 14,0 °C a 15,2 °C. ¿Cuántos grados más muestra la serie completa que el tramo elegido?","unidad":"°C","decimales":1,"contexto":"Tramo de 14.3 a 14.4 °C; serie completa de 14,0 a 15,2 °C."},"solucion":{"valor":1.1,"tolerancia":0.05,"explicacion":"Serie completa: 15,2 − 14,0 = 1,2 °C. Tramo: 0,1 °C. Diferencia: 1,1 °C que el recorte esconde. Valores ficticios para practicar."}},{"slug":"ciencia-3.s3.p13.v2","orden":13,"grupo":"ciencia-3.s3.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En el tramo elegido, la temperatura media pasó de 14,5 °C a 14,5 °C. Mirando desde 1970 pasó de 14,0 °C a 15,2 °C. ¿Cuántos grados más muestra la serie completa que el tramo elegido?","unidad":"°C","decimales":1,"contexto":"Tramo de 14.5 a 14.5 °C; serie completa de 14,0 a 15,2 °C."},"solucion":{"valor":1.2,"tolerancia":0.05,"explicacion":"Serie completa: 15,2 − 14,0 = 1,2 °C. Tramo: 0 °C. Diferencia: 1,2 °C que el recorte esconde. Valores ficticios para practicar."}},{"slug":"ciencia-3.s3.p13.v3","orden":13,"grupo":"ciencia-3.s3.p13","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"En el tramo elegido, la temperatura media pasó de 14,4 °C a 14,5 °C. Mirando desde 1970 pasó de 14,0 °C a 15,2 °C. ¿Cuántos grados más muestra la serie completa que el tramo elegido?","unidad":"°C","decimales":1,"contexto":"Tramo de 14.4 a 14.5 °C; serie completa de 14,0 a 15,2 °C."},"solucion":{"valor":1.1,"tolerancia":0.05,"explicacion":"Serie completa: 15,2 − 14,0 = 1,2 °C. Tramo: 0,1 °C. Diferencia: 1,1 °C que el recorte esconde. Valores ficticios para practicar."}},{"slug":"ciencia-3.s3.p14","orden":14,"grupo":"ciencia-3.s3.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este posteo y marcá las trampas.","segmentos":[{"id":"s1","texto":"\"Este dato es del organismo oficial de estadísticas.\""},{"id":"s2","texto":"\"Un actor famoso explicó que reciclar no sirve para nada.\""},{"id":"s3","texto":"\"La nota enlaza el estudio original.\""},{"id":"s4","texto":"\"Como la ciencia no está 100 % segura, no hay que hacer nada.\""}]},"solucion":{"clave":["s2","s4"],"explicacion":"Buscar las técnicas es más rápido que discutir cada dato.","por_opcion":{"s2":"Falso experto: la fama no es experiencia en el tema.","s4":"Expectativa imposible: nunca hay certeza total para actuar."}}},{"slug":"ciencia-3.s3.p15","orden":15,"grupo":"ciencia-3.s3.p15","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Elegir solo los datos que convienen se llama {{0}} de datos; una foto real con fecha falsa es un caso de contexto {{1}}; y exigir certeza total antes de actuar es una expectativa {{2}}.","banco":[{"id":"w1","texto":"selección"},{"id":"w2","texto":"falso"},{"id":"w3","texto":"imposible"},{"id":"w4","texto":"recolección"},{"id":"w5","texto":"impostor"},{"id":"w6","texto":"razonable"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres trampas frecuentes de la desinformación."}}]},{"slug":"ciencia-3.s4","orden":4,"tipo":"leccion","titulo_es":"Por qué lo falso vuela","bajada_es":"Emociones, sesgos, repetición y algoritmos: por qué la desinformación se difunde más rápido que los datos.","minutos":11,"pasos":[{"slug":"ciencia-3.s4.p1","orden":1,"grupo":"ciencia-3.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Más lejos y más rápido","cuerpo":["Un estudio publicado en la revista Science en 2018 analizó alrededor de 126.000 historias que circularon en Twitter entre 2006 y 2017. Las noticias falsas llegaron más lejos, más rápido y a más personas que las verdaderas: tenían un 70 % más de probabilidad de ser compartidas. Las verdaderas tardaban unas seis veces más en llegar a 1.500 personas. Y no eran los bots los que marcaban la diferencia: eran las personas."],"destacado":{"valor":"70 %","texto":"más probabilidad de ser compartidas tenían las noticias falsas que las verdaderas, según un estudio de Science (2018)."}},"solucion":{}},{"slug":"ciencia-3.s4.p2","orden":2,"grupo":"ciencia-3.s4.p2","tipo":"estimar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuánto más probable era que se compartiera una noticia falsa que una verdadera, según el estudio de Science.","min":0,"max":500,"paso":5,"unidad":"% más","escala":"lineal"},"solucion":{"valor":70,"banda":"lineal","explicacion":"Un 70 % más. Lo falso suele ser más novedoso y sorprendente, y eso empuja a compartir."}},{"slug":"ciencia-3.s4.p3","orden":3,"grupo":"ciencia-3.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Por qué pasa","cuerpo":["Lo falso suele ser más novedoso y provocar emociones fuertes: sorpresa, miedo, indignación. Esas emociones empujan a compartir sin pensar. Además, tendemos a creer más lo que confirma lo que ya pensamos (sesgo de confirmación). Y lo que escuchamos muchas veces nos parece más cierto, aunque sea falso: es el efecto de verdad ilusoria.","Los algoritmos de las redes muestran más lo que genera reacciones, así que lo indignante tiene ventaja."]},"solucion":{}},{"slug":"ciencia-3.s4.p4","orden":4,"grupo":"ciencia-3.s4.p4","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada mecanismo con su definición.","izquierda":[{"id":"a1","texto":"Sesgo de confirmación"},{"id":"a2","texto":"Efecto de verdad ilusoria"},{"id":"a3","texto":"Novedad"},{"id":"a4","texto":"Algoritmos de reacción"}],"derecha":[{"id":"b1","texto":"Creer más lo que coincide con lo que ya pensamos"},{"id":"b2","texto":"Lo repetido parece más cierto"},{"id":"b3","texto":"Lo sorprendente llama más la atención"},{"id":"b4","texto":"Muestran más lo que genera interacciones"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Estos mecanismos nos afectan a todos, no solo a \"los demás\"."}},{"slug":"ciencia-3.s4.p5","orden":5,"grupo":"ciencia-3.s4.p5","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo se viraliza un contenido falso.","items":[{"id":"i1","texto":"Un contenido falso provoca indignación"},{"id":"i2","texto":"Muchas personas reaccionan y lo comparten"},{"id":"i3","texto":"El algoritmo lo muestra a más gente"},{"id":"i4","texto":"Aparece muchas veces en distintas fuentes"},{"id":"i5","texto":"Por repetición, parece más creíble"},{"id":"i6","texto":"El algoritmo verifica los datos antes de mostrarlo"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Emoción, algoritmo y repetición se retroalimentan."}},{"slug":"ciencia-3.s4.p6","orden":6,"grupo":"ciencia-3.s4.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Solo las personas poco informadas caen en la desinformación.","razones":[{"id":"r1","texto":"Porque los sesgos afectan a todas las personas"},{"id":"r2","texto":"Porque la desinformación no engaña a nadie"},{"id":"r3","texto":"Porque las personas informadas nunca comparten nada"}]},"solucion":{"valor":false,"explicacion":"Los sesgos de confirmación y de verdad ilusoria afectan a todos, incluidas personas muy educadas. Por eso sirven hábitos como frenar y verificar.","clave":["r1"]}},{"slug":"ciencia-3.s4.p7","orden":7,"grupo":"ciencia-3.s4.p7","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué un titular que te indigna es una señal para frenar?","opciones":[{"id":"o1","texto":"La indignación empuja a compartir sin pensar"},{"id":"o2","texto":"Porque las noticias indignantes siempre son falsas"},{"id":"o3","texto":"Porque indignarse está prohibido"},{"id":"o4","texto":"Porque los titulares no importan"}]},"solucion":{"clave":["o1"],"explicacion":"No todo lo indignante es falso, pero la emoción fuerte es justo cuando más conviene verificar.","por_opcion":{"o3":"No: la emoción es válida, pero conviene verificar antes de actuar."}}},{"slug":"ciencia-3.s4.p8","orden":8,"grupo":"ciencia-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona manda un mensaje a 10 contactos (ronda 1). Cada uno lo reenvía a 10 personas nuevas (ronda 2), y así sigue. ¿Cuántas personas lo reciben en la ronda 3?","unidad":"personas","decimales":0,"contexto":"10 personas nuevas por reenvío; ronda 3."},"solucion":{"valor":1000,"tolerancia":20,"explicacion":"En cada ronda se multiplica por 10: 10 elevado a 3 = 1.000. Por eso cortar la cadena temprano tiene tanto efecto."}},{"slug":"ciencia-3.s4.p8.v2","orden":8,"grupo":"ciencia-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona manda un mensaje a 5 contactos (ronda 1). Cada uno lo reenvía a 5 personas nuevas (ronda 2), y así sigue. ¿Cuántas personas lo reciben en la ronda 4?","unidad":"personas","decimales":0,"contexto":"5 personas nuevas por reenvío; ronda 4."},"solucion":{"valor":625,"tolerancia":12.5,"explicacion":"En cada ronda se multiplica por 5: 5 elevado a 4 = 625. Por eso cortar la cadena temprano tiene tanto efecto."}},{"slug":"ciencia-3.s4.p8.v3","orden":8,"grupo":"ciencia-3.s4.p8","tipo":"numero","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una persona manda un mensaje a 20 contactos (ronda 1). Cada uno lo reenvía a 20 personas nuevas (ronda 2), y así sigue. ¿Cuántas personas lo reciben en la ronda 3?","unidad":"personas","decimales":0,"contexto":"20 personas nuevas por reenvío; ronda 3."},"solucion":{"valor":8000,"tolerancia":160,"explicacion":"En cada ronda se multiplica por 20: 20 elevado a 3 = 8.000. Por eso cortar la cadena temprano tiene tanto efecto."}},{"slug":"ciencia-3.s4.p9","orden":9,"grupo":"ciencia-3.s4.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Burbujas","cuerpo":["Cuando seguimos solo a personas que piensan parecido y los algoritmos nos muestran más de lo mismo, podemos quedar en una \"burbuja\" donde ciertas ideas parecen universales. Diversificar las fuentes, seguir a especialistas y medios con estándares de verificación, y exponerse a argumentos distintos ayuda a ver el panorama completo."]},"solucion":{}},{"slug":"ciencia-3.s4.p10","orden":10,"grupo":"ciencia-3.s4.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hábitos reducen el efecto de los sesgos? Marcá todos.","opciones":[{"id":"o1","texto":"Frenar antes de compartir algo que te emociona"},{"id":"o2","texto":"Seguir fuentes con estándares de verificación"},{"id":"o3","texto":"Buscar a propósito argumentos distintos"},{"id":"o4","texto":"Compartir rápido para ser el primero"},{"id":"o5","texto":"Seguir solo a quienes piensan igual"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"No se trata de desconfiar de todo, sino de tener hábitos que compensen los sesgos."}},{"slug":"ciencia-3.s4.p11","orden":11,"grupo":"ciencia-3.s4.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Según el estudio de Science, ¿qué explica mejor que las noticias falsas se compartan más?","opciones":[{"id":"o1","texto":"Son más novedosas y despiertan emociones fuertes"},{"id":"o2","texto":"Los bots las comparten mucho más que a las verdaderas"},{"id":"o3","texto":"Las verdaderas están prohibidas en las redes"},{"id":"o4","texto":"Las falsas siempre tienen mejores fotos"}]},"solucion":{"clave":["o1"],"explicacion":"El estudio encontró que la novedad y la emoción, y no los bots, explicaban la diferencia.","por_opcion":{"o3":"Nada impide compartir noticias verdaderas; simplemente generan menos reacción."}}},{"slug":"ciencia-3.s4.p12","orden":12,"grupo":"ciencia-3.s4.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos contenidos del que más probablemente se viraliza al que menos.","items":[{"id":"i1","texto":"Titular falso, indignante y sorprendente"},{"id":"i2","texto":"Noticia verdadera con una historia emotiva"},{"id":"i3","texto":"Noticia verdadera con datos sin contexto emocional"},{"id":"i4","texto":"Informe técnico de 200 páginas"}],"extremos":["Más viral","Menos viral"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"La viralidad premia la emoción y la novedad, no la verdad.","valores":{"i1":"emoción + novedad","i2":"emoción","i3":"poca emoción","i4":"casi nada"}}},{"slug":"ciencia-3.s4.p13","orden":13,"grupo":"ciencia-3.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta reflexión y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Las noticias falsas suelen llegar más lejos que las verdaderas."},{"id":"s2","texto":"Si algo lo leí muchas veces, seguro es cierto."},{"id":"s3","texto":"Los algoritmos favorecen lo que genera reacciones."},{"id":"s4","texto":"Los bots explican toda la difusión de lo falso."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Entender por qué funciona la desinformación es el primer paso para no ser parte.","por_opcion":{"s2":"Es el efecto de verdad ilusoria: la repetición no prueba nada.","s4":"El estudio de Science encontró que las personas eran las que más lo difundían."}}},{"slug":"ciencia-3.s4.p14","orden":14,"grupo":"ciencia-3.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Creer más lo que coincide con lo que pensamos es el sesgo de {{0}}; lo repetido parece más cierto por el efecto de verdad {{1}}; y las noticias falsas tenían un {{2}} % más de probabilidad de compartirse.","banco":[{"id":"w1","texto":"confirmación"},{"id":"w2","texto":"ilusoria"},{"id":"w3","texto":"70"},{"id":"w4","texto":"atención"},{"id":"w5","texto":"absoluta"},{"id":"w6","texto":"7"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para entender por qué lo falso se difunde."}}]},{"slug":"ciencia-3.s5","orden":5,"tipo":"leccion","titulo_es":"Verificar y responder","bajada_es":"Búsqueda del origen, imágenes, chequeadores, prebunking y cómo corregir sin darle más alcance al mito.","minutos":11,"pasos":[{"slug":"ciencia-3.s5.p1","orden":1,"grupo":"ciencia-3.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Herramientas de verificación","cuerpo":["Para verificar un contenido se puede buscar su origen (¿quién lo publicó primero?), hacer una búsqueda inversa de la imagen (subirla a un buscador para ver dónde y cuándo apareció antes), buscar el tema en sitios de verificación como Chequeado, y buscar el dato en la fuente original que se cita. Muchas veces, en menos de cinco minutos se descubre que una foto es vieja o que un estudio no dice lo que se afirma."]},"solucion":{}},{"slug":"ciencia-3.s5.p2","orden":2,"grupo":"ciencia-3.s5.p2","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada problema con la herramienta que lo resuelve.","izquierda":[{"id":"a1","texto":"Foto que podría ser vieja"},{"id":"a2","texto":"Dato atribuido a un estudio"},{"id":"a3","texto":"Rumor que circula mucho"},{"id":"a4","texto":"Cuenta desconocida que publica algo"}],"derecha":[{"id":"b1","texto":"Búsqueda inversa de imágenes"},{"id":"b2","texto":"Buscar el estudio original"},{"id":"b3","texto":"Buscar en sitios de verificación"},{"id":"b4","texto":"Lectura lateral sobre quién es"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada tipo de contenido tiene su herramienta de verificación."}},{"slug":"ciencia-3.s5.p3","orden":3,"grupo":"ciencia-3.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Prebunking: vacunarse contra el engaño","cuerpo":["Investigadores de la Universidad de Cambridge estudiaron una estrategia llamada inoculación o prebunking: exponer a las personas, de forma controlada, a las técnicas de manipulación antes de que se encuentren con ellas. Igual que una vacuna, conocer la técnica en versión \"debilitada\" ayuda a reconocerla después. Juegos y videos breves que enseñan técnicas como el falso experto o el lenguaje emocional mejoraron la capacidad de detectar contenido manipulador."]},"solucion":{}},{"slug":"ciencia-3.s5.p4","orden":4,"grupo":"ciencia-3.s5.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué es el prebunking?","opciones":[{"id":"o1","texto":"Enseñar las técnicas de engaño antes de que aparezcan"},{"id":"o2","texto":"Borrar los contenidos falsos antes de que circulen"},{"id":"o3","texto":"Responder a cada mentira después de que se viraliza"},{"id":"o4","texto":"Prohibir las redes sociales"}]},"solucion":{"clave":["o1"],"explicacion":"Conocer las trampas de antemano funciona como una vacuna contra la manipulación.","por_opcion":{"o3":"Eso es desmentir después (debunking); el prebunking es anticiparse."}}},{"slug":"ciencia-3.s5.p5","orden":5,"grupo":"ciencia-3.s5.p5","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Corregir sin amplificar","cuerpo":["Al desmentir un mito, hay que evitar repetirlo tanto que termine reforzándose. Una estructura recomendada por especialistas es el \"sándwich de la verdad\": empezar por el dato correcto, advertir que circula un mito y explicar por qué es engañoso (qué técnica usa), y terminar repitiendo el dato correcto. Así, lo que más queda es la verdad, no el mito."]},"solucion":{}},{"slug":"ciencia-3.s5.p6","orden":6,"grupo":"ciencia-3.s5.p6","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená la estructura del \"sándwich de la verdad\".","items":[{"id":"i1","texto":"Empezar con el dato correcto"},{"id":"i2","texto":"Advertir que circula un mito"},{"id":"i3","texto":"Explicar por qué el mito es engañoso"},{"id":"i4","texto":"Cerrar repitiendo el dato correcto"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El dato correcto va al principio y al final: es lo que más se recuerda."}},{"slug":"ciencia-3.s5.p7","orden":7,"grupo":"ciencia-3.s5.p7","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para desmentir un mito conviene repetirlo en el título, en grande, para que todos lo vean.","razones":[{"id":"r1","texto":"Porque repetirlo en grande puede reforzarlo"},{"id":"r2","texto":"Porque los mitos no se pueden desmentir"},{"id":"r3","texto":"Porque los títulos no se leen"}]},"solucion":{"valor":false,"explicacion":"Repetir el mito en el lugar más visible puede reforzarlo por el efecto de verdad ilusoria. Conviene destacar el dato correcto.","clave":["r1"]}},{"slug":"ciencia-3.s5.p8","orden":8,"grupo":"ciencia-3.s5.p8","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué conviene hacer y qué no al responder a alguien que compartió algo falso?","grupos":[{"id":"g1","nombre":"Conviene"},{"id":"g2","nombre":"No conviene"}],"items":[{"id":"i1","texto":"Responder en privado si es alguien cercano"},{"id":"i2","texto":"Burlarse en público"},{"id":"i3","texto":"Empezar por el dato correcto"},{"id":"i4","texto":"Repetir el mito en mayúsculas"},{"id":"i5","texto":"Incluir una fuente confiable"},{"id":"i6","texto":"Acusar a la persona de mentir a propósito"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1","i6":"g2"},"explicacion":"La mayoría de quienes comparten algo falso creen que es cierto. La empatía abre la conversación."}},{"slug":"ciencia-3.s5.p9","orden":9,"grupo":"ciencia-3.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un mensaje falso llegó a 200 personas de un grupo. Después de una respuesta bien armada, el 30 % dejó de compartirlo. ¿Cuántas personas dejaron de compartirlo?","unidad":"personas","decimales":0,"contexto":"200 personas; el 30 % deja de compartir."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"200 × 30 % = 60 personas. Cada persona que corta la cadena evita que el mensaje llegue a muchas más."}},{"slug":"ciencia-3.s5.p9.v2","orden":9,"grupo":"ciencia-3.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un mensaje falso llegó a 500 personas de un grupo. Después de una respuesta bien armada, el 12 % dejó de compartirlo. ¿Cuántas personas dejaron de compartirlo?","unidad":"personas","decimales":0,"contexto":"500 personas; el 12 % deja de compartir."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"500 × 12 % = 60 personas. Cada persona que corta la cadena evita que el mensaje llegue a muchas más."}},{"slug":"ciencia-3.s5.p9.v3","orden":9,"grupo":"ciencia-3.s5.p9","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un mensaje falso llegó a 150 personas de un grupo. Después de una respuesta bien armada, el 40 % dejó de compartirlo. ¿Cuántas personas dejaron de compartirlo?","unidad":"personas","decimales":0,"contexto":"150 personas; el 40 % deja de compartir."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"150 × 40 % = 60 personas. Cada persona que corta la cadena evita que el mensaje llegue a muchas más."}},{"slug":"ciencia-3.s5.p10","orden":10,"grupo":"ciencia-3.s5.p10","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales de alerta tiene un mensaje de cadena? Marcá todas.","opciones":[{"id":"o1","texto":"Pide compartir \"antes de que lo borren\""},{"id":"o2","texto":"No dice de dónde sale el dato"},{"id":"o3","texto":"Usa muchas mayúsculas y signos de exclamación"},{"id":"o4","texto":"Enlaza a la fuente original y tiene fecha"},{"id":"o5","texto":"Lo publicó un medio con correcciones públicas"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La urgencia, la falta de fuente y el tono alarmista son señales clásicas."}},{"slug":"ciencia-3.s5.p11","orden":11,"grupo":"ciencia-3.s5.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Tu tío compartió en el grupo familiar una foto de un glaciar \"derrumbado ayer\", pero es de hace diez años. ¿Qué respuesta es mejor?","opciones":[{"id":"o1","texto":"Contarle en privado de cuándo es la foto y darle la fuente"},{"id":"o2","texto":"Escribir en el grupo que siempre comparte mentiras"},{"id":"o3","texto":"Ignorarlo, porque no vale la pena"},{"id":"o4","texto":"Compartir otra foto falsa para equilibrar"}]},"solucion":{"clave":["o1"],"explicacion":"Privado, con respeto y con la fuente: así es más probable que corrija sin sentirse atacado.","por_opcion":{"o3":"Puede ser una opción, pero perdés la oportunidad de cortar la cadena."}}},{"slug":"ciencia-3.s5.p12","orden":12,"grupo":"ciencia-3.s5.p12","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá los pasos para verificar una foto sospechosa.","items":[{"id":"i1","texto":"Guardar la imagen o una captura"},{"id":"i2","texto":"Hacer una búsqueda inversa de la imagen"},{"id":"i3","texto":"Encontrar la primera vez que apareció"},{"id":"i4","texto":"Comparar esa fecha y lugar con lo que dice el mensaje"},{"id":"i5","texto":"Concluir si el contexto es real o falso"},{"id":"i6","texto":"Contar cuántos \"me gusta\" tiene la foto"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La popularidad no dice nada; el origen de la imagen sí."}},{"slug":"ciencia-3.s5.p13","orden":13,"grupo":"ciencia-3.s5.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta respuesta a un mito y marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"\"Los datos de la NASA muestran que el planeta se calentó 1,2 °C.\""},{"id":"s2","texto":"\"¡¡¡EL CAMBIO CLIMÁTICO ES FALSO!!! es lo que dice este mensaje.\""},{"id":"s3","texto":"\"Ese mensaje usa un falso experto: no es especialista en clima.\""},{"id":"s4","texto":"\"Sos un ignorante por creer eso.\""}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una buena respuesta es precisa, breve, respetuosa y deja el dato correcto como lo más visible.","por_opcion":{"s2":"Repite el mito en grande; conviene mencionarlo breve y sin destacar.","s4":"El insulto cierra la conversación; la empatía la abre."}}},{"slug":"ciencia-3.s5.p14","orden":14,"grupo":"ciencia-3.s5.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Para saber si una foto es vieja se hace una búsqueda {{0}}; enseñar las trampas antes de que aparezcan se llama {{1}}; y el \"sándwich de la verdad\" empieza y termina con el dato {{2}}.","banco":[{"id":"w1","texto":"inversa"},{"id":"w2","texto":"prebunking"},{"id":"w3","texto":"correcto"},{"id":"w4","texto":"rápida"},{"id":"w5","texto":"bloqueo"},{"id":"w6","texto":"viral"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres herramientas para verificar y responder sin amplificar."}}]},{"slug":"ciencia-3.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: fuentes y desinformación","bajada_es":"Tipos de fuentes, lectura lateral, técnicas de engaño, viralidad y verificación, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-3.s6.p1","orden":1,"grupo":"ciencia-3.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Fuentes y desinformación». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-3.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: la cadena del grupo","bajada_es":"Llega un mensaje viral a un grupo de la escuela. Analizalo, verificalo y armá la respuesta.","minutos":10,"pasos":[{"slug":"ciencia-3.s7.p1","orden":1,"grupo":"ciencia-3.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El mensaje","cuerpo":["\"URGENTE: un ingeniero reconocido demostró que los paneles solares contaminan más de lo que ahorran. Un estudio de la Universidad Internacional de Energía lo confirma. Los medios lo ocultan. Compartilo antes de que lo borren!!!\" El mensaje no tiene enlaces ni fecha. Al buscar, encontrás que la \"Universidad Internacional de Energía\" es un sitio creado hace dos meses, sin autores identificables, y que las revisiones de estudios sobre el ciclo de vida de los paneles solares muestran que, en pocos años de funcionamiento, compensan la energía y las emisiones de su fabricación."]},"solucion":{}},{"slug":"ciencia-3.s7.p2","orden":2,"grupo":"ciencia-3.s7.p2","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué señales de alerta tiene el mensaje? Marcá todas.","opciones":[{"id":"o1","texto":"Pide compartir con urgencia \"antes de que lo borren\""},{"id":"o2","texto":"Cita un \"ingeniero reconocido\" sin nombre"},{"id":"o3","texto":"Dice que \"los medios lo ocultan\""},{"id":"o4","texto":"No tiene enlaces ni fecha"},{"id":"o5","texto":"Cita un estudio con autores identificables"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Urgencia, experto anónimo, conspiración y falta de fuentes: cuatro alertas en un solo mensaje."}},{"slug":"ciencia-3.s7.p3","orden":3,"grupo":"ciencia-3.s7.p3","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada parte del mensaje con la técnica que usa.","izquierda":[{"id":"a1","texto":"\"Un ingeniero reconocido demostró\""},{"id":"a2","texto":"\"Los medios lo ocultan\""},{"id":"a3","texto":"\"Universidad Internacional de Energía\""},{"id":"a4","texto":"\"Compartilo antes de que lo borren\""}],"derecha":[{"id":"b1","texto":"Falso experto"},{"id":"b2","texto":"Teoría conspirativa"},{"id":"b3","texto":"Contenido impostor"},{"id":"b4","texto":"Urgencia emocional"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Reconocer las técnicas permite responder aunque no seas especialista en energía."}},{"slug":"ciencia-3.s7.p4","orden":4,"grupo":"ciencia-3.s7.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos de verificación que conviene seguir.","items":[{"id":"i1","texto":"Frenar y no reenviar todavía"},{"id":"i2","texto":"Buscar quién está detrás de la \"universidad\""},{"id":"i3","texto":"Buscar qué dicen las revisiones de estudios sobre paneles"},{"id":"i4","texto":"Consultar si un sitio de verificación ya lo analizó"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Frenar, averiguar la fuente, mirar la evidencia de conjunto y apoyarse en verificadores."}},{"slug":"ciencia-3.s7.p5","orden":5,"grupo":"ciencia-3.s7.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"La \"universidad\" es un sitio creado hace dos meses, sin autores. ¿Qué conclusión es más razonable?","opciones":[{"id":"o1","texto":"No es una fuente confiable para ese dato"},{"id":"o2","texto":"Es confiable, porque tiene la palabra \"universidad\""},{"id":"o3","texto":"Es falso todo lo que dice sobre cualquier tema"},{"id":"o4","texto":"Hay que esperar a que la borren para saberlo"}]},"solucion":{"clave":["o1"],"explicacion":"Sin autores, sin historia y sin evidencia verificable, no puede sostener una afirmación que contradice muchas revisiones.","por_opcion":{"o3":"No hace falta ir tan lejos: basta con no usarla como prueba."}}},{"slug":"ciencia-3.s7.p6","orden":6,"grupo":"ciencia-3.s7.p6","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Si un panel tarda 2 años en compensar las emisiones de su fabricación y funciona 25 años, ¿cuántos años funciona \"en positivo\"?","unidad":"años","decimales":0,"contexto":"2 años para compensar; vida útil de 25 años."},"solucion":{"valor":23,"tolerancia":0.5,"explicacion":"25 − 2 = 23 años. Durante la mayor parte de su vida útil, el panel genera energía sin las emisiones de su fabricación ya compensadas. El valor de 2 años es aproximado y varía según el lugar."}},{"slug":"ciencia-3.s7.p7","orden":7,"grupo":"ciencia-3.s7.p7","tipo":"ordenar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená tu respuesta al grupo con la estructura del sándwich de la verdad.","items":[{"id":"i1","texto":"Las revisiones muestran que los paneles compensan su fabricación en pocos años"},{"id":"i2","texto":"Circula un mensaje que dice lo contrario"},{"id":"i3","texto":"Usa un experto sin nombre y una \"universidad\" sin autores"},{"id":"i4","texto":"Los paneles solares reducen emisiones a lo largo de su vida útil"}]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"El dato correcto abre y cierra la respuesta. El mito aparece breve, en el medio, con la explicación de por qué engaña."}},{"slug":"ciencia-3.s7.p8","orden":8,"grupo":"ciencia-3.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Revisá la respuesta que escribió un compañero y marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Los paneles compensan su fabricación en pocos años de uso."},{"id":"s2","texto":"El que compartió esto es un burro."},{"id":"s3","texto":"La \"universidad\" no tiene autores ni historia verificable."},{"id":"s4","texto":"¡¡¡LOS PANELES CONTAMINAN MÁS!!! dice el mensaje, y es mentira."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Una respuesta efectiva es respetuosa, breve y deja el dato correcto como lo más visible.","por_opcion":{"s2":"El insulto cierra la conversación y no convence a nadie.","s4":"Repite el mito en grande; conviene mencionarlo breve."}}}]}]}$ac$::jsonb);
select ac_cargar_unidad($ac${"slug":"ciencia-4","rama":"ciencia","orden":4,"nivel":2,"titulo_es":"Ciencia ciudadana","bajada_es":"Aves, vinchucas, bichos del arroyo y lluvia: cómo cualquier persona puede aportar datos útiles a la ciencia, y cómo hacerlo bien.","objetivos_es":["Explicar qué es la ciencia ciudadana y qué aporta a la investigación","Registrar una observación con los datos que la vuelven útil","Aplicar un protocolo y calcular tasas según el esfuerzo","Reconocer sesgos de muestreo y cómo se corrigen","Diseñar un proyecto de ciencia ciudadana con criterios éticos"],"repasa":["ciencia-1","ciencia-2","animales-2","ciencia-3"],"requiere_tronco":2,"fuentes":["ecsa-principios","ebird","argentinat","inaturalist-calidad","gbif","geovin","aves-argentinas"],"age_groups":["kid","teen","adult"],"lecciones":[{"slug":"ciencia-4.s1","orden":1,"tipo":"leccion","titulo_es":"Qué es la ciencia ciudadana","bajada_es":"Personas sin título de científicas que observan, registran y aportan datos a investigaciones reales.","minutos":12,"pasos":[{"slug":"ciencia-4.s1.p1","orden":1,"grupo":"ciencia-4.s1.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Muchos ojos","cuerpo":["La ciencia ciudadana es la participación de personas del público en investigaciones científicas: observan, miden, registran o analizan datos, en colaboración con equipos de investigación. No es nueva: el Conteo Navideño de Aves, en el que voluntarios cuentan aves durante un día, empezó en Estados Unidos en 1900 y sigue haciéndose cada año en muchos países.","Su gran aporte es la escala: ningún equipo de científicos puede estar en miles de lugares a la vez, todos los días, durante décadas. Miles de voluntarios sí."]},"solucion":{}},{"slug":"ciencia-4.s1.p2","orden":2,"grupo":"ciencia-4.s1.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Cuál es el principal aporte de la ciencia ciudadana?","opciones":[{"id":"o1","texto":"Datos de muchos lugares y momentos a la vez"},{"id":"o2","texto":"Reemplazar por completo a los científicos"},{"id":"o3","texto":"Hacer experimentos de laboratorio más precisos"},{"id":"o4","texto":"Evitar que los datos se publiquen"}]},"solucion":{"clave":["o1"],"explicacion":"La escala en el espacio y en el tiempo es lo que ningún equipo profesional puede lograr solo.","por_opcion":{"o3":"Su fuerte no es el laboratorio sino la cobertura en el territorio."}}},{"slug":"ciencia-4.s1.p3","orden":3,"grupo":"ciencia-4.s1.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Proyectos que funcionan","cuerpo":["eBird, creado en 2002 por el Laboratorio de Ornitología de Cornell, reúne listas de aves de observadores de todo el mundo, y ya supera los mil millones de registros. ArgentiNat, la versión argentina de iNaturalist, recibe fotos de cualquier ser vivo, que la comunidad ayuda a identificar. GeoVin, un proyecto de investigadores del CONICET, recibe reportes de vinchucas, los insectos que transmiten el parásito de la enfermedad de Chagas, para mapear dónde están."]},"solucion":{}},{"slug":"ciencia-4.s1.p4","orden":4,"grupo":"ciencia-4.s1.p4","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada proyecto con lo que registra.","izquierda":[{"id":"a1","texto":"eBird"},{"id":"a2","texto":"ArgentiNat"},{"id":"a3","texto":"GeoVin"},{"id":"a4","texto":"Conteo Navideño de Aves"}],"derecha":[{"id":"b1","texto":"Listas de aves observadas"},{"id":"b2","texto":"Fotos de cualquier ser vivo"},{"id":"b3","texto":"Reportes de vinchucas"},{"id":"b4","texto":"Aves contadas en un día fijo cada año"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada proyecto tiene una pregunta y un tipo de dato. Elegir bien dónde aportar es el primer paso."}},{"slug":"ciencia-4.s1.p5","orden":5,"grupo":"ciencia-4.s1.p5","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos registros de aves reunió eBird desde 2002.","min":1000,"max":100000000000,"paso":1,"unidad":"registros","escala":"log"},"solucion":{"valor":1000000000,"banda":"log","explicacion":"Más de mil millones de registros. Con esos datos se hacen mapas de distribución y migración que antes eran imposibles."}},{"slug":"ciencia-4.s1.p6","orden":6,"grupo":"ciencia-4.s1.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Niveles de participación","cuerpo":["La participación puede ser de distintos niveles. En los proyectos contributivos, el público aporta datos siguiendo un protocolo diseñado por científicos. En los colaborativos, además ayuda a analizar o a mejorar el diseño. En los co-creados, la comunidad y los científicos definen juntos la pregunta, por ejemplo, vecinos preocupados por un arroyo que se asocian con una universidad."]},"solucion":{}},{"slug":"ciencia-4.s1.p7","orden":7,"grupo":"ciencia-4.s1.p7","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué nivel de participación tiene cada proyecto?","grupos":[{"id":"g1","nombre":"Contributivo"},{"id":"g2","nombre":"Colaborativo"},{"id":"g3","nombre":"Co-creado"}],"items":[{"id":"i1","texto":"Subir fotos de aves a una plataforma"},{"id":"i2","texto":"Voluntarios que además ayudan a identificar fotos de otros"},{"id":"i3","texto":"Vecinos y una universidad diseñan juntos un monitoreo del arroyo"},{"id":"i4","texto":"Reportar vinchucas con una app"},{"id":"i5","texto":"Participantes que proponen mejoras al protocolo"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2"},"explicacion":"Cuanto más co-creado, más responde el proyecto a las preguntas de la propia comunidad."}},{"slug":"ciencia-4.s1.p8","orden":8,"grupo":"ciencia-4.s1.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Diez principios","cuerpo":["La Asociación Europea de Ciencia Ciudadana propuso diez principios. Entre ellos: los participantes contribuyen activamente a la ciencia; el proyecto produce resultados científicos genuinos; tanto científicos como voluntarios se benefician; los participantes reciben devoluciones sobre cómo se usan sus datos; los datos se comparten de forma abierta cuando es posible; se reconoce a quienes participan; y se consideran los aspectos éticos y legales."]},"solucion":{}},{"slug":"ciencia-4.s1.p9","orden":9,"grupo":"ciencia-4.s1.p9","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué principios debería cumplir un buen proyecto de ciencia ciudadana? Marcá todos.","opciones":[{"id":"o1","texto":"Dar devoluciones a quienes aportan datos"},{"id":"o2","texto":"Reconocer la participación de los voluntarios"},{"id":"o3","texto":"Producir resultados científicos genuinos"},{"id":"o4","texto":"Usar a los voluntarios sin contarles para qué"},{"id":"o5","texto":"Guardar los datos en secreto para siempre"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"La ciencia ciudadana es una colaboración: si los voluntarios no ven resultados, dejan de participar."}},{"slug":"ciencia-4.s1.p10","orden":10,"grupo":"ciencia-4.s1.p10","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"La ciencia ciudadana solo sirve para entretenerse; los datos no se usan en investigaciones reales.","razones":[{"id":"r1","texto":"Porque sus datos se usan en investigaciones y decisiones reales"},{"id":"r2","texto":"Porque los voluntarios no pueden observar nada"},{"id":"r3","texto":"Porque los científicos no aceptan datos externos"}]},"solucion":{"valor":false,"explicacion":"Los datos de eBird, iNaturalist y muchos otros proyectos se usan en miles de artículos científicos, mapas de distribución y decisiones de conservación.","clave":["r1"]}},{"slug":"ciencia-4.s1.p11","orden":11,"grupo":"ciencia-4.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto tiene 500 voluntarios que registran en promedio 12 observaciones por mes. ¿Cuántas observaciones reúne en un año?","unidad":"observaciones","decimales":0},"solucion":{"valor":72000,"tolerancia":1440,"explicacion":"500 × 12 × 12 = 72.000. Ningún equipo profesional podría reunir tantos datos en tantos lugares."}},{"slug":"ciencia-4.s1.p11.v2","orden":11,"grupo":"ciencia-4.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto tiene 1.200 voluntarios que registran en promedio 8 observaciones por mes. ¿Cuántas observaciones reúne en un año?","unidad":"observaciones","decimales":0},"solucion":{"valor":115200,"tolerancia":2304,"explicacion":"1.200 × 8 × 12 = 115.200. Ningún equipo profesional podría reunir tantos datos en tantos lugares."}},{"slug":"ciencia-4.s1.p11.v3","orden":11,"grupo":"ciencia-4.s1.p11","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un proyecto tiene 300 voluntarios que registran en promedio 25 observaciones por mes. ¿Cuántas observaciones reúne en un año?","unidad":"observaciones","decimales":0},"solucion":{"valor":90000,"tolerancia":1800,"explicacion":"300 × 25 × 12 = 90.000. Ningún equipo profesional podría reunir tantos datos en tantos lugares."}},{"slug":"ciencia-4.s1.p12","orden":12,"grupo":"ciencia-4.s1.p12","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un reporte de vinchuca se vuelve útil.","items":[{"id":"i1","texto":"Una familia encuentra un insecto sospechoso en su casa"},{"id":"i2","texto":"Le saca una foto y la envía al proyecto con la ubicación"},{"id":"i3","texto":"Especialistas confirman si es una vinchuca y de qué especie"},{"id":"i4","texto":"El registro se suma al mapa de distribución"},{"id":"i5","texto":"Las autoridades de salud pueden priorizar zonas"},{"id":"i6","texto":"La familia aplasta el insecto y no lo reporta"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Un reporte bien hecho conecta una casa con la salud pública de toda una región."}},{"slug":"ciencia-4.s1.p13","orden":13,"grupo":"ciencia-4.s1.p13","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Para participar en un proyecto de ciencia ciudadana hace falta un título universitario.","razones":[{"id":"r1","texto":"Porque alcanza con seguir el protocolo con cuidado"},{"id":"r2","texto":"Porque solo pueden participar científicos"},{"id":"r3","texto":"Porque los datos de voluntarios se descartan"}]},"solucion":{"valor":false,"explicacion":"La idea es justamente que cualquier persona pueda aportar. Lo que hace falta es seguir el protocolo y registrar con cuidado.","clave":["r1"]}},{"slug":"ciencia-4.s1.p14","orden":14,"grupo":"ciencia-4.s1.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta nota y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"El Conteo Navideño de Aves empezó en 1900."},{"id":"s2","texto":"La ciencia ciudadana es un invento de los últimos cinco años."},{"id":"s3","texto":"GeoVin recibe reportes de vinchucas."},{"id":"s4","texto":"En un proyecto co-creado, los científicos deciden todo solos."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La ciencia ciudadana tiene historia, métodos y principios propios.","por_opcion":{"s2":"Existe hace más de un siglo; las apps la hicieron masiva.","s4":"En uno co-creado, la comunidad y los científicos definen juntos la pregunta."}}},{"slug":"ciencia-4.s1.p15","orden":15,"grupo":"ciencia-4.s1.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La participación del público en investigaciones se llama ciencia {{0}}; el proyecto argentino que recibe fotos de seres vivos es {{1}}; y un buen proyecto da {{2}} a quienes participan.","banco":[{"id":"w1","texto":"ciudadana"},{"id":"w2","texto":"ArgentiNat"},{"id":"w3","texto":"devoluciones"},{"id":"w4","texto":"privada"},{"id":"w5","texto":"GeoVin"},{"id":"w6","texto":"multas"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres ideas para entender qué es la ciencia ciudadana y cómo funciona."}}]},{"slug":"ciencia-4.s2","orden":2,"tipo":"leccion","titulo_es":"Una observación que sirve","bajada_es":"Qué, dónde, cuándo y con qué evidencia: los datos que convierten una foto en un registro científico.","minutos":14,"pasos":[{"slug":"ciencia-4.s2.p1","orden":1,"grupo":"ciencia-4.s2.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos mínimos","cuerpo":["Una observación útil responde cuatro preguntas: qué (qué organismo o fenómeno), dónde (ubicación precisa, idealmente con coordenadas), cuándo (fecha y hora) y con qué evidencia (foto, audio o descripción). También importa quién observó, para poder consultar dudas. Una foto hermosa sin fecha ni lugar sirve muy poco para la ciencia."]},"solucion":{}},{"slug":"ciencia-4.s2.p2","orden":2,"grupo":"ciencia-4.s2.p2","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué datos necesita una observación para ser útil? Marcá todos.","opciones":[{"id":"o1","texto":"Qué organismo se observó"},{"id":"o2","texto":"Dónde, con la ubicación más precisa posible"},{"id":"o3","texto":"Cuándo: fecha y hora"},{"id":"o4","texto":"Evidencia, como una foto o un audio"},{"id":"o5","texto":"El filtro que se usó en la foto"}]},"solucion":{"clave":["o1","o2","o3","o4"],"explicacion":"Sin lugar y fecha, un registro no puede sumarse a un mapa ni a una tendencia."}},{"slug":"ciencia-4.s2.p3","orden":3,"grupo":"ciencia-4.s2.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El grado de investigación","cuerpo":["En iNaturalist y ArgentiNat, una observación alcanza el \"grado de investigación\" cuando tiene fecha, ubicación y foto o sonido, no es de un organismo en cautiverio o cultivado, y más de dos tercios de quienes la identificaron coinciden en la especie. Esas observaciones se comparten con GBIF, la red mundial de datos de biodiversidad, donde las usan investigadores de todo el mundo."]},"solucion":{}},{"slug":"ciencia-4.s2.p4","orden":4,"grupo":"ciencia-4.s2.p4","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Esta observación puede llegar a grado de investigación?","grupos":[{"id":"g1","nombre":"Puede llegar"},{"id":"g2","nombre":"No puede llegar"}],"items":[{"id":"i1","texto":"Foto de un zorzal en una plaza, con fecha y ubicación"},{"id":"i2","texto":"Foto de un loro en una jaula"},{"id":"i3","texto":"Audio de una rana en una laguna, con fecha y ubicación"},{"id":"i4","texto":"Foto de un árbol sin ubicación"},{"id":"i5","texto":"Foto de una planta de maceta en un balcón"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"Los organismos en cautiverio o cultivados no informan sobre la distribución natural de las especies."}},{"slug":"ciencia-4.s2.p5","orden":5,"grupo":"ciencia-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"6 personas identificaron una foto; 5 coinciden en la especie. ¿Qué fracción coincide, en porcentaje? Redondeá al entero. (Para grado de investigación hace falta más de dos tercios, unos 67 %.)","unidad":"%","decimales":0,"contexto":"5 de 6 identificaciones coinciden."},"solucion":{"valor":83,"tolerancia":1,"explicacion":"5 ÷ 6 × 100 ≈ 83 %. Supera los dos tercios: alcanza el acuerdo necesario."}},{"slug":"ciencia-4.s2.p5.v2","orden":5,"grupo":"ciencia-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"9 personas identificaron una foto; 6 coinciden en la especie. ¿Qué fracción coincide, en porcentaje? Redondeá al entero. (Para grado de investigación hace falta más de dos tercios, unos 67 %.)","unidad":"%","decimales":0,"contexto":"6 de 9 identificaciones coinciden."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"6 ÷ 9 × 100 ≈ 67 %. No supera los dos tercios: todavía no alcanza el acuerdo necesario."}},{"slug":"ciencia-4.s2.p5.v3","orden":5,"grupo":"ciencia-4.s2.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"3 personas identificaron una foto; 2 coinciden en la especie. ¿Qué fracción coincide, en porcentaje? Redondeá al entero. (Para grado de investigación hace falta más de dos tercios, unos 67 %.)","unidad":"%","decimales":0,"contexto":"2 de 3 identificaciones coinciden."},"solucion":{"valor":67,"tolerancia":1,"explicacion":"2 ÷ 3 × 100 ≈ 67 %. No supera los dos tercios: todavía no alcanza el acuerdo necesario."}},{"slug":"ciencia-4.s2.p6","orden":6,"grupo":"ciencia-4.s2.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Buenas fotos","cuerpo":["Para que otros puedan identificar un organismo, conviene sacar varias fotos: de distintos ángulos, de los detalles que distinguen a la especie (en una planta, hojas, flores y frutos; en un insecto, el dorso y las patas), con algo que dé idea del tamaño, y del ambiente. Sin tocar ni molestar a los animales: la foto nunca vale más que su bienestar."]},"solucion":{}},{"slug":"ciencia-4.s2.p7","orden":7,"grupo":"ciencia-4.s2.p7","tipo":"multiple","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace más identificable una foto de un insecto? Marcá todo.","opciones":[{"id":"o1","texto":"Fotos de varios ángulos"},{"id":"o2","texto":"Algo que indique el tamaño"},{"id":"o3","texto":"Detalles como alas y patas"},{"id":"o4","texto":"Aplicar un filtro de colores"},{"id":"o5","texto":"Atraparlo y encerrarlo para la foto"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Más información visual, sin dañar al animal."}},{"slug":"ciencia-4.s2.p8","orden":8,"grupo":"ciencia-4.s2.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Identificar con honestidad","cuerpo":["Cuando no se está seguro de la especie, es mejor identificar a un nivel más general (por ejemplo, \"mariposa\" o \"familia de los picaflores\") que adivinar. Un error confiado puede confundir a otros y meter datos falsos en un mapa. Decir \"no sé\" también es buena ciencia."]},"solucion":{}},{"slug":"ciencia-4.s2.p9","orden":9,"grupo":"ciencia-4.s2.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Viste un pájaro rápido y no estás seguro de la especie. ¿Qué conviene registrar?","opciones":[{"id":"o1","texto":"Un nivel más general, como \"picaflor\""},{"id":"o2","texto":"La especie más común, por las dudas"},{"id":"o3","texto":"La especie más rara, para que sea más interesante"},{"id":"o4","texto":"Nada, porque no sirve si no sabés la especie"}]},"solucion":{"clave":["o1"],"explicacion":"Un registro general correcto vale más que uno específico equivocado.","por_opcion":{"o3":"Registrar lo raro sin certeza mete datos falsos en los mapas."}}},{"slug":"ciencia-4.s2.p10","orden":10,"grupo":"ciencia-4.s2.p10","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Registrar lo que no está","cuerpo":["En eBird se pide indicar si la lista es completa, es decir, si se anotaron todas las especies que se pudieron identificar. Así, si una especie no aparece en una lista completa, se sabe que no se la detectó, y no solo que no se la anotó. Esos \"ceros\" son muy valiosos para saber dónde una especie es rara o desapareció."]},"solucion":{}},{"slug":"ciencia-4.s2.p11","orden":11,"grupo":"ciencia-4.s2.p11","tipo":"vf","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si en una lista completa no aparece el cardenal, eso también es un dato útil.","razones":[{"id":"r1","texto":"Porque en una lista completa la ausencia significa no detectado"},{"id":"r2","texto":"Porque las listas completas no existen"},{"id":"r3","texto":"Porque solo sirven los registros de especies raras"}]},"solucion":{"valor":true,"explicacion":"En una lista completa, la ausencia indica que no se lo detectó. Con muchas listas, esos ceros permiten estimar dónde una especie es rara o está desapareciendo.","clave":["r1"]}},{"slug":"ciencia-4.s2.p12","orden":12,"grupo":"ciencia-4.s2.p12","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"Sacaste una foto de una planta en una maceta de tu balcón. ¿Qué conviene indicar al subirla?","opciones":[{"id":"o1","texto":"Que es un organismo cultivado"},{"id":"o2","texto":"Que es una especie silvestre muy rara"},{"id":"o3","texto":"Una ubicación falsa para proteger tu casa"},{"id":"o4","texto":"Nada, porque las plantas no cuentan"}]},"solucion":{"clave":["o1"],"explicacion":"Marcarla como cultivada evita que se confunda con la distribución natural de la especie.","por_opcion":{"o3":"Mejor ocultar la ubicación con la opción de la plataforma, no inventarla."}}},{"slug":"ciencia-4.s2.p13","orden":13,"grupo":"ciencia-4.s2.p13","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada pregunta con el dato que la responde.","izquierda":[{"id":"a1","texto":"¿Qué?"},{"id":"a2","texto":"¿Dónde?"},{"id":"a3","texto":"¿Cuándo?"},{"id":"a4","texto":"¿Con qué evidencia?"}],"derecha":[{"id":"b1","texto":"Especie u organismo observado"},{"id":"b2","texto":"Coordenadas o ubicación precisa"},{"id":"b3","texto":"Fecha y hora"},{"id":"b4","texto":"Foto, audio o descripción"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cuatro preguntas que convierten una observación en un registro."}},{"slug":"ciencia-4.s2.p14","orden":14,"grupo":"ciencia-4.s2.p14","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé cómo registró una observación un compañero y marcá los errores.","segmentos":[{"id":"s1","texto":"Anotó la fecha y la hora."},{"id":"s2","texto":"Como no sabía la especie, puso la más rara que conocía."},{"id":"s3","texto":"Sacó fotos de varios ángulos."},{"id":"s4","texto":"Agarró al sapo y lo llevó a su casa para fotografiarlo mejor."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen registro es preciso, honesto y respetuoso con los seres vivos.","por_opcion":{"s2":"Conviene identificar a un nivel más general si no hay certeza.","s4":"Nunca hay que llevarse ni molestar a los animales."}}},{"slug":"ciencia-4.s2.p15","orden":15,"grupo":"ciencia-4.s2.p15","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená los pasos para registrar una observación en ArgentiNat.","items":[{"id":"i1","texto":"Observar sin molestar al organismo"},{"id":"i2","texto":"Sacar varias fotos con detalles y escala"},{"id":"i3","texto":"Anotar o dejar que el teléfono registre fecha y ubicación"},{"id":"i4","texto":"Subir la observación con la identificación más segura posible"},{"id":"i5","texto":"Revisar las identificaciones que sugiere la comunidad"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"El registro sigue vivo después de subirlo: la comunidad ayuda a confirmarlo."}},{"slug":"ciencia-4.s2.p16","orden":16,"grupo":"ciencia-4.s2.p16","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"En ArgentiNat, una observación confirmada por la comunidad alcanza el grado de {{0}}; un organismo en {{1}} no sirve para mapear su distribución natural; y en una lista {{2}} la ausencia también es un dato.","banco":[{"id":"w1","texto":"investigación"},{"id":"w2","texto":"cautiverio"},{"id":"w3","texto":"completa"},{"id":"w4","texto":"belleza"},{"id":"w5","texto":"libertad"},{"id":"w6","texto":"parcial"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para que tus observaciones sirvan a la ciencia."}}]},{"slug":"ciencia-4.s3","orden":3,"tipo":"leccion","titulo_es":"Protocolos, esfuerzo y sesgos","bajada_es":"Contar igual en todos lados, medir cuánto se buscó y corregir los datos que se amontonan donde hay más gente.","minutos":14,"pasos":[{"slug":"ciencia-4.s3.p1","orden":1,"grupo":"ciencia-4.s3.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un protocolo","cuerpo":["Para que los datos de distintas personas se puedan comparar, hace falta un protocolo: reglas fijas sobre cómo observar. Por ejemplo, en un conteo por puntos de aves, cada participante se queda 10 minutos en un punto fijo y anota todas las aves que ve u oye dentro de un radio de 50 metros. Si cada uno contara como quisiera, las diferencias podrían deberse al método y no a las aves."]},"solucion":{}},{"slug":"ciencia-4.s3.p2","orden":2,"grupo":"ciencia-4.s3.p2","tipo":"opcion","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Para qué sirve un protocolo en ciencia ciudadana?","opciones":[{"id":"o1","texto":"Para poder comparar datos de distintas personas"},{"id":"o2","texto":"Para que los voluntarios no se distraigan tanto"},{"id":"o3","texto":"Para que solo puedan participar los expertos"},{"id":"o4","texto":"Para juntar menos datos pero más ordenados"}]},"solucion":{"clave":["o1"],"explicacion":"Lo viste con los experimentos: hay que controlar lo que no se quiere comparar.","por_opcion":{"o3":"Al contrario: un buen protocolo permite que cualquiera aporte datos útiles."}}},{"slug":"ciencia-4.s3.p3","orden":3,"grupo":"ciencia-4.s3.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"El esfuerzo","cuerpo":["No es lo mismo ver 20 aves en 10 minutos que en 3 horas. Por eso se registra el esfuerzo: cuánto tiempo se observó, qué distancia se recorrió y cuántas personas participaron. Con eso se calculan tasas, como aves por hora, que sí se pueden comparar entre lugares y fechas."]},"solucion":{}},{"slug":"ciencia-4.s3.p4","orden":4,"grupo":"ciencia-4.s3.p4","tipo":"ejemplo","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"ejemplo","titulo":"Aves por hora","planteo":"Grupo A contó 60 aves en 2 horas en el parque. Grupo B contó 45 aves en 1 hora en la costanera.","pasos":["Grupo A: 60 ÷ 2 = 30 aves por hora.","Grupo B: 45 ÷ 1 = 45 aves por hora.","Aunque el grupo A contó más aves en total, la costanera tuvo más aves por hora de búsqueda."],"resultado":"Comparar totales sin considerar el esfuerzo lleva a conclusiones equivocadas."},"solucion":{}},{"slug":"ciencia-4.s3.p5","orden":5,"grupo":"ciencia-4.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un grupo contó 84 aves en 120 minutos. ¿Cuántas aves por hora es eso? Redondeá al entero.","unidad":"aves por hora","decimales":0,"contexto":"84 aves en 120 minutos."},"solucion":{"valor":42,"tolerancia":1,"explicacion":"84 ÷ 120 × 60 ≈ 42 aves por hora. Pasar a tasa permite comparar grupos que observaron distinto tiempo."}},{"slug":"ciencia-4.s3.p5.v2","orden":5,"grupo":"ciencia-4.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un grupo contó 36 aves en 45 minutos. ¿Cuántas aves por hora es eso? Redondeá al entero.","unidad":"aves por hora","decimales":0,"contexto":"36 aves en 45 minutos."},"solucion":{"valor":48,"tolerancia":1,"explicacion":"36 ÷ 45 × 60 ≈ 48 aves por hora. Pasar a tasa permite comparar grupos que observaron distinto tiempo."}},{"slug":"ciencia-4.s3.p5.v3","orden":5,"grupo":"ciencia-4.s3.p5","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Un grupo contó 150 aves en 90 minutos. ¿Cuántas aves por hora es eso? Redondeá al entero.","unidad":"aves por hora","decimales":0,"contexto":"150 aves en 90 minutos."},"solucion":{"valor":100,"tolerancia":1,"explicacion":"150 ÷ 90 × 60 ≈ 100 aves por hora. Pasar a tasa permite comparar grupos que observaron distinto tiempo."}},{"slug":"ciencia-4.s3.p6","orden":6,"grupo":"ciencia-4.s3.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Sesgos de muestreo","cuerpo":["Los datos de ciencia ciudadana tienen sesgos conocidos: hay muchos más registros cerca de ciudades, rutas y senderos que en lugares remotos; más los fines de semana; y más de especies grandes, coloridas o fáciles de ver que de especies chicas o nocturnas. Si no se corrige, un mapa podría mostrar \"más biodiversidad\" donde en realidad hay más gente mirando."]},"solucion":{}},{"slug":"ciencia-4.s3.p7","orden":7,"grupo":"ciencia-4.s3.p7","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué sesgo aparece en cada caso?","grupos":[{"id":"g1","nombre":"Sesgo de lugar"},{"id":"g2","nombre":"Sesgo de especie"},{"id":"g3","nombre":"Sesgo de tiempo"}],"items":[{"id":"i1","texto":"Muchos registros junto a la ruta y casi ninguno lejos"},{"id":"i2","texto":"Muchas fotos de mariposas coloridas y pocas de polillas"},{"id":"i3","texto":"Muchos más registros los domingos"},{"id":"i4","texto":"Mapas con más especies cerca de las ciudades"},{"id":"i5","texto":"Muchos registros de aves grandes y pocos de ranas nocturnas"},{"id":"i6","texto":"Casi ningún registro de noche"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g3","i4":"g1","i5":"g2","i6":"g3"},"explicacion":"Conocer los sesgos permite corregirlos con el esfuerzo y con buen diseño."}},{"slug":"ciencia-4.s3.p8","orden":8,"grupo":"ciencia-4.s3.p8","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo un sesgo puede confundir un mapa.","items":[{"id":"i1","texto":"La gente observa más cerca de las ciudades"},{"id":"i2","texto":"Hay muchos más registros en esas zonas"},{"id":"i3","texto":"El mapa muestra más especies cerca de las ciudades"},{"id":"i4","texto":"Parece que las ciudades tienen más biodiversidad"},{"id":"i5","texto":"En realidad, lo que cambia es el esfuerzo de observación"},{"id":"i6","texto":"Las especies se mudan a las ciudades para ser fotografiadas"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Sin tener en cuenta el esfuerzo, el mapa muestra dónde hay observadores, no dónde hay especies."}},{"slug":"ciencia-4.s3.p9","orden":9,"grupo":"ciencia-4.s3.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Bichos que indican el agua","cuerpo":["Algunos protocolos usan bioindicadores: organismos cuya presencia dice algo del ambiente. En los arroyos, las larvas de efímeras, plecópteros y tricópteros son muy sensibles a la contaminación: si abundan, el agua suele estar en buen estado. Otros, como algunas larvas de mosquito y ciertos gusanos, toleran agua contaminada. Contar qué grupos aparecen en una muestra da una idea de la calidad del agua, sin laboratorio."]},"solucion":{}},{"slug":"ciencia-4.s3.p10","orden":10,"grupo":"ciencia-4.s3.p10","tipo":"clasificar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Qué indica encontrar muchos de estos organismos en un arroyo?","grupos":[{"id":"g1","nombre":"Agua en buen estado"},{"id":"g2","nombre":"Agua posiblemente contaminada"}],"items":[{"id":"i1","texto":"Larvas de plecópteros"},{"id":"i2","texto":"Muchos gusanos rojos del barro"},{"id":"i3","texto":"Larvas de efímeras"},{"id":"i4","texto":"Muchas larvas de mosquito y ninguna sensible"},{"id":"i5","texto":"Larvas de tricópteros"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Los bioindicadores integran lo que pasó en el agua durante semanas, no solo el día del muestreo."}},{"slug":"ciencia-4.s3.p11","orden":11,"grupo":"ciencia-4.s3.p11","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"En una muestra de un arroyo aparecen muchas larvas de efímeras y plecópteros. ¿Qué sugiere?","opciones":[{"id":"o1","texto":"Que el agua probablemente está en buen estado"},{"id":"o2","texto":"Que el agua está muy contaminada con cloacas"},{"id":"o3","texto":"Que hay que fumigar el arroyo enseguida"},{"id":"o4","texto":"Que el arroyo está completamente seco"}]},"solucion":{"clave":["o1"],"explicacion":"Estos grupos son sensibles a la contaminación: su presencia abundante es buena señal.","por_opcion":{"o3":"Son organismos nativos y buenos indicadores: no hay que eliminarlos."}}},{"slug":"ciencia-4.s3.p12","orden":12,"grupo":"ciencia-4.s3.p12","tipo":"emparejar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada sesgo con una forma de corregirlo.","izquierda":[{"id":"a1","texto":"Muchos registros junto a rutas"},{"id":"a2","texto":"Más registros los fines de semana"},{"id":"a3","texto":"Pocas fotos de especies nocturnas"},{"id":"a4","texto":"Totales con distinto tiempo de búsqueda"}],"derecha":[{"id":"b1","texto":"Organizar salidas a zonas poco visitadas"},{"id":"b2","texto":"Calcular tasas según el esfuerzo"},{"id":"b3","texto":"Hacer muestreos específicos de noche"},{"id":"b4","texto":"Comparar aves por hora"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada sesgo tiene una corrección: por diseño del muestreo o por cómo se analizan los datos."}},{"slug":"ciencia-4.s3.p13","orden":13,"grupo":"ciencia-4.s3.p13","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una zona tiene más registros en ArgentiNat, seguro tiene más especies.","razones":[{"id":"r1","texto":"Porque puede tener más observadores, no más especies"},{"id":"r2","texto":"Porque los registros no dicen nada"},{"id":"r3","texto":"Porque todas las zonas tienen las mismas especies"}]},"solucion":{"valor":false,"explicacion":"Puede tener simplemente más observadores. Para comparar zonas hay que considerar el esfuerzo de muestreo.","clave":["r1"]}},{"slug":"ciencia-4.s3.p14","orden":14,"grupo":"ciencia-4.s3.p14","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué ayuda a reducir los sesgos de muestreo? Marcá todo.","opciones":[{"id":"o1","texto":"Registrar el tiempo y la distancia de cada salida"},{"id":"o2","texto":"Organizar salidas a lugares poco visitados"},{"id":"o3","texto":"Usar un protocolo fijo de conteo"},{"id":"o4","texto":"Registrar solo las especies más lindas"},{"id":"o5","texto":"Observar siempre en el mismo lugar cómodo"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"El diseño y el registro del esfuerzo permiten comparar datos de forma justa."}},{"slug":"ciencia-4.s3.p15","orden":15,"grupo":"ciencia-4.s3.p15","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé esta conclusión de un grupo y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Registramos cuántos minutos observamos en cada punto."},{"id":"s2","texto":"El parque A tiene más aves porque contamos más, aunque estuvimos el triple de tiempo."},{"id":"s3","texto":"Usamos el mismo radio de 50 metros en todos los puntos."},{"id":"s4","texto":"Como vimos muchas mariposas coloridas, casi no hay polillas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Las conclusiones tienen que respetar cómo se tomaron los datos.","por_opcion":{"s2":"Hay que comparar tasas por hora, no totales con distinto esfuerzo.","s4":"Las polillas son más difíciles de ver; es un sesgo de especie."}}},{"slug":"ciencia-4.s3.p16","orden":16,"grupo":"ciencia-4.s3.p16","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Las reglas fijas para observar forman un {{0}}; el tiempo y la distancia de búsqueda son el {{1}}; y los organismos que indican el estado del ambiente son {{2}}.","banco":[{"id":"w1","texto":"protocolo"},{"id":"w2","texto":"esfuerzo"},{"id":"w3","texto":"bioindicadores"},{"id":"w4","texto":"reglamento"},{"id":"w5","texto":"premio"},{"id":"w6","texto":"invasores"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres conceptos para tomar datos comparables."}}]},{"slug":"ciencia-4.s4","orden":4,"tipo":"leccion","titulo_es":"De los datos a los resultados","bajada_es":"Controles de calidad, mapas, tendencias y datos abiertos, cuidando a las especies y a las personas.","minutos":12,"pasos":[{"slug":"ciencia-4.s4.p1","orden":1,"grupo":"ciencia-4.s4.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Control de calidad","cuerpo":["Los proyectos grandes tienen filtros: en eBird, si alguien registra una especie muy rara para esa zona y fecha, o una cantidad inusual, el registro queda marcado para que lo revise una persona experta de la región, que puede pedir más evidencia. En iNaturalist, la comunidad confirma o corrige las identificaciones. Así, los errores individuales se detectan y los datos ganan confiabilidad."]},"solucion":{}},{"slug":"ciencia-4.s4.p2","orden":2,"grupo":"ciencia-4.s4.p2","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el camino de un registro inusual en eBird.","items":[{"id":"i1","texto":"Alguien registra una especie rara para esa zona"},{"id":"i2","texto":"El sistema marca el registro como inusual"},{"id":"i3","texto":"Un revisor experto de la región lo evalúa"},{"id":"i4","texto":"Pide evidencia, como una foto o una descripción"},{"id":"i5","texto":"El registro se acepta o se descarta"},{"id":"i6","texto":"El registro se publica sin revisión porque es raro"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Lo raro no se descarta ni se acepta a ciegas: se revisa."}},{"slug":"ciencia-4.s4.p3","orden":3,"grupo":"ciencia-4.s4.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Mapas y tendencias","cuerpo":["Con miles de registros se pueden hacer mapas de distribución, ver por dónde migran las especies y en qué fechas, y detectar tendencias: si una especie aparece cada vez en menos listas completas, puede estar disminuyendo. También se estudia la fenología, es decir, cuándo florecen las plantas o llegan las aves cada año, y si esas fechas se adelantan con el calentamiento."]},"solucion":{}},{"slug":"ciencia-4.s4.p4","orden":4,"grupo":"ciencia-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una especie aparecía en el 42 % de las listas completas de una región hace 10 años y hoy en el 30 %. ¿En cuántos puntos porcentuales bajó?","unidad":"puntos porcentuales","decimales":0,"contexto":"Del 42 % al 30 % de las listas completas."},"solucion":{"valor":12,"tolerancia":0.5,"explicacion":"42 − 30 = 12 puntos porcentuales. Como son listas completas con esfuerzo registrado, la baja puede indicar una disminución real de la especie."}},{"slug":"ciencia-4.s4.p4.v2","orden":4,"grupo":"ciencia-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una especie aparecía en el 25 % de las listas completas de una región hace 10 años y hoy en el 20 %. ¿En cuántos puntos porcentuales bajó?","unidad":"puntos porcentuales","decimales":0,"contexto":"Del 25 % al 20 % de las listas completas."},"solucion":{"valor":5,"tolerancia":0.5,"explicacion":"25 − 20 = 5 puntos porcentuales. Como son listas completas con esfuerzo registrado, la baja puede indicar una disminución real de la especie."}},{"slug":"ciencia-4.s4.p4.v3","orden":4,"grupo":"ciencia-4.s4.p4","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Una especie aparecía en el 60 % de las listas completas de una región hace 10 años y hoy en el 39 %. ¿En cuántos puntos porcentuales bajó?","unidad":"puntos porcentuales","decimales":0,"contexto":"Del 60 % al 39 % de las listas completas."},"solucion":{"valor":21,"tolerancia":0.5,"explicacion":"60 − 39 = 21 puntos porcentuales. Como son listas completas con esfuerzo registrado, la baja puede indicar una disminución real de la especie."}},{"slug":"ciencia-4.s4.p5","orden":5,"grupo":"ciencia-4.s4.p5","tipo":"emparejar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada resultado con lo que permite estudiar.","izquierda":[{"id":"a1","texto":"Mapa de distribución"},{"id":"a2","texto":"Serie de muchos años"},{"id":"a3","texto":"Fechas de floración"},{"id":"a4","texto":"Registros de especies nuevas en una zona"}],"derecha":[{"id":"b1","texto":"Dónde vive una especie"},{"id":"b2","texto":"Si una especie aumenta o disminuye"},{"id":"b3","texto":"Cambios en la fenología"},{"id":"b4","texto":"Llegada de especies invasoras"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Los mismos datos responden muchas preguntas distintas."}},{"slug":"ciencia-4.s4.p6","orden":6,"grupo":"ciencia-4.s4.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Datos abiertos","cuerpo":["Muchos proyectos comparten sus datos en GBIF, una infraestructura internacional que reúne miles de millones de registros de biodiversidad de museos, universidades y ciencia ciudadana. Cualquier persona puede descargarlos y usarlos, citando la fuente. Así, un registro de una plaza de Rosario puede formar parte de un estudio mundial."]},"solucion":{}},{"slug":"ciencia-4.s4.p7","orden":7,"grupo":"ciencia-4.s4.p7","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Los datos de ciencia ciudadana solo los puede usar el proyecto que los recolectó.","razones":[{"id":"r1","texto":"Porque muchos se comparten como datos abiertos"},{"id":"r2","texto":"Porque está prohibido compartir datos"},{"id":"r3","texto":"Porque los datos se borran después de un año"}]},"solucion":{"valor":false,"explicacion":"Muchos se comparten como datos abiertos en GBIF, donde cualquier investigador puede usarlos citando la fuente.","clave":["r1"]}},{"slug":"ciencia-4.s4.p8","orden":8,"grupo":"ciencia-4.s4.p8","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Cuidar a las especies y a las personas","cuerpo":["Compartir datos también tiene riesgos. La ubicación exacta de una especie amenazada o muy buscada por traficantes puede ponerla en peligro: por eso iNaturalist oculta automáticamente las coordenadas precisas de las especies amenazadas. Y las observaciones hechas en una casa pueden revelar dónde vive alguien: conviene poder ocultar la ubicación. La ética es parte del método."]},"solucion":{}},{"slug":"ciencia-4.s4.p9","orden":9,"grupo":"ciencia-4.s4.p9","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Por qué iNaturalist oculta la ubicación exacta de las especies amenazadas?","opciones":[{"id":"o1","texto":"Para evitar que las encuentren traficantes o curiosos"},{"id":"o2","texto":"Porque esas especies no tienen ubicación"},{"id":"o3","texto":"Porque los datos de especies amenazadas no sirven"},{"id":"o4","texto":"Porque las especies amenazadas son todas marinas"}]},"solucion":{"clave":["o1"],"explicacion":"Un dato abierto puede ser un riesgo. Proteger a la especie está por encima de mostrar el punto exacto.","por_opcion":{"o3":"Sirven mucho; por eso se comparten con precisión solo con quien investiga."}}},{"slug":"ciencia-4.s4.p10","orden":10,"grupo":"ciencia-4.s4.p10","tipo":"clasificar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Conviene publicar la ubicación exacta o protegerla?","grupos":[{"id":"g1","nombre":"Publicar exacta"},{"id":"g2","nombre":"Proteger"}],"items":[{"id":"i1","texto":"Un gorrión en una plaza"},{"id":"i2","texto":"Un nido de cardenal amarillo"},{"id":"i3","texto":"Un árbol de paraíso en una vereda"},{"id":"i4","texto":"Una orquídea rara muy buscada"},{"id":"i5","texto":"Un registro hecho en el patio de tu casa"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g2"},"explicacion":"La ubicación de especies buscadas por traficantes y de hogares particulares merece protección."}},{"slug":"ciencia-4.s4.p11","orden":11,"grupo":"ciencia-4.s4.p11","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué hace confiables los datos de un gran proyecto de ciencia ciudadana? Marcá todo.","opciones":[{"id":"o1","texto":"Revisión de registros inusuales por expertos"},{"id":"o2","texto":"Identificaciones confirmadas por la comunidad"},{"id":"o3","texto":"Registro del esfuerzo de muestreo"},{"id":"o4","texto":"Que todos los registros sean de especies raras"},{"id":"o5","texto":"Que nadie revise nada para no desalentar"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Muchas personas más buenos controles producen datos que la ciencia puede usar con confianza."}},{"slug":"ciencia-4.s4.p12","orden":12,"grupo":"ciencia-4.s4.p12","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Si una especie de ave llega cada primavera algunos días antes que hace 30 años, eso puede ser una señal del calentamiento.","razones":[{"id":"r1","texto":"Porque es un cambio de fenología asociado al calentamiento"},{"id":"r2","texto":"Porque las aves llegan siempre el mismo día exacto"},{"id":"r3","texto":"Porque la fenología no tiene relación con el clima"}]},"solucion":{"valor":true,"explicacion":"Es un cambio de fenología que se observa en muchas especies. Para atribuirlo al clima hacen falta series largas y descartar otros cambios, como el esfuerzo de observación.","clave":["r1"]}},{"slug":"ciencia-4.s4.p13","orden":13,"grupo":"ciencia-4.s4.p13","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé este resumen de un proyecto y marcá lo equivocado.","segmentos":[{"id":"s1","texto":"Los registros inusuales se revisan antes de aceptarlos."},{"id":"s2","texto":"Publicamos la ubicación exacta de todos los nidos de especies amenazadas."},{"id":"s3","texto":"Compartimos los datos en GBIF citando a los participantes."},{"id":"s4","texto":"Como son voluntarios, sus datos nunca sirven para estudiar tendencias."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Calidad, apertura y cuidado: las tres patas de un buen proyecto.","por_opcion":{"s2":"Puede facilitar su captura; conviene protegerla.","s4":"Con listas completas y esfuerzo registrado, sí sirven."}}},{"slug":"ciencia-4.s4.p14","orden":14,"grupo":"ciencia-4.s4.p14","tipo":"completar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"La red mundial que reúne registros de biodiversidad se llama {{0}}; el estudio de cuándo florecen las plantas o llegan las aves es la {{1}}; y la ubicación de especies amenazadas se {{2}}.","banco":[{"id":"w1","texto":"GBIF"},{"id":"w2","texto":"fenología"},{"id":"w3","texto":"oculta"},{"id":"w4","texto":"NASA"},{"id":"w5","texto":"geología"},{"id":"w6","texto":"duplica"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Tres claves para entender qué pasa con los datos después de registrarlos."}},{"slug":"ciencia-4.s4.p15","orden":15,"grupo":"ciencia-4.s4.p15","tipo":"estimar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"estimar","enunciado":"Estimá cuántos registros de biodiversidad reúne GBIF en total.","min":1000000,"max":1000000000000,"paso":1,"unidad":"registros","escala":"log"},"solucion":{"valor":3000000000,"banda":"log","explicacion":"Miles de millones: más de tres mil millones de registros de museos, universidades y ciencia ciudadana de todo el mundo."}}]},{"slug":"ciencia-4.s5","orden":5,"tipo":"leccion","titulo_es":"Tu propio proyecto","bajada_es":"De una pregunta del barrio a un monitoreo con protocolo, prueba piloto, datos abiertos y devolución.","minutos":12,"pasos":[{"slug":"ciencia-4.s5.p1","orden":1,"grupo":"ciencia-4.s5.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Empezar por la pregunta","cuerpo":["Un proyecto de ciencia ciudadana empieza con una pregunta que se pueda responder con datos que la gente pueda tomar. \"¿Cómo cambia la cantidad de aves de la plaza a lo largo del año?\" o \"¿El arroyo está peor aguas abajo de la fábrica?\" son buenas preguntas. \"¿Cómo salvar el planeta?\" es importante, pero no se responde con un monitoreo."]},"solucion":{}},{"slug":"ciencia-4.s5.p2","orden":2,"grupo":"ciencia-4.s5.p2","tipo":"clasificar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"clasificar","enunciado":"¿Es una buena pregunta para un proyecto de ciencia ciudadana?","grupos":[{"id":"g1","nombre":"Buena pregunta"},{"id":"g2","nombre":"Demasiado amplia o no medible"}],"items":[{"id":"i1","texto":"¿Qué polinizadores visitan las flores de la plaza en primavera?"},{"id":"i2","texto":"¿Cómo salvar el planeta?"},{"id":"i3","texto":"¿Cuánto llueve en cada barrio del pueblo?"},{"id":"i4","texto":"¿Es buena la naturaleza?"},{"id":"i5","texto":"¿Hay vinchucas en las casas del paraje?"}]},"solucion":{"clave":{"i1":"g1","i2":"g2","i3":"g1","i4":"g2","i5":"g1"},"explicacion":"Una buena pregunta es concreta, medible y cercana a lo que la gente puede observar."}},{"slug":"ciencia-4.s5.p3","orden":3,"grupo":"ciencia-4.s5.p3","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los pasos","cuerpo":["Después de la pregunta, se diseña un protocolo simple y claro; se hace una prueba piloto con pocas personas para detectar problemas; se capacita a los participantes; se recolectan los datos con el esfuerzo registrado; se revisa la calidad; se analizan los resultados; y se devuelven a la comunidad. Si es posible, conviene asociarse con un equipo de investigación que ayude con el diseño y el análisis."]},"solucion":{}},{"slug":"ciencia-4.s5.p4","orden":4,"grupo":"ciencia-4.s5.p4","tipo":"ordenar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ordenar","enunciado":"Ordená las etapas de un proyecto de ciencia ciudadana.","items":[{"id":"i1","texto":"Definir una pregunta concreta"},{"id":"i2","texto":"Diseñar un protocolo simple"},{"id":"i3","texto":"Hacer una prueba piloto"},{"id":"i4","texto":"Capacitar y recolectar datos"},{"id":"i5","texto":"Analizar y devolver los resultados"}]},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"La prueba piloto ahorra muchos errores: es mejor descubrirlos con 5 personas que con 500."}},{"slug":"ciencia-4.s5.p5","orden":5,"grupo":"ciencia-4.s5.p5","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Para qué sirve una prueba piloto?","opciones":[{"id":"o1","texto":"Para encontrar problemas del protocolo antes de escalar"},{"id":"o2","texto":"Para que los resultados salgan como uno quiere"},{"id":"o3","texto":"Para no tener que capacitar a nadie"},{"id":"o4","texto":"Para publicar resultados más rápido"}]},"solucion":{"clave":["o1"],"explicacion":"Un protocolo confuso produce datos inservibles. El piloto lo revela a tiempo y a bajo costo.","por_opcion":{"o3":"La capacitación sigue siendo necesaria; el piloto la mejora."}}},{"slug":"ciencia-4.s5.p6","orden":6,"grupo":"ciencia-4.s5.p6","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Un ejemplo: pluviómetros del barrio","cuerpo":["Un grupo de vecinos quiere saber si llueve distinto en cada zona de su pueblo. Instalan pluviómetros caseros iguales, a la misma altura y lejos de techos y árboles. Leen el agua acumulada cada mañana a las 9, anotan en una planilla compartida y vacían el pluviómetro. Con meses de datos pueden comparar barrios y aportar información al municipio para planificar desagües."]},"solucion":{}},{"slug":"ciencia-4.s5.p7","orden":7,"grupo":"ciencia-4.s5.p7","tipo":"multiple","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué detalles del protocolo de los pluviómetros hacen comparables los datos? Marcá todos.","opciones":[{"id":"o1","texto":"Pluviómetros iguales en todos los barrios"},{"id":"o2","texto":"Misma altura y lejos de techos y árboles"},{"id":"o3","texto":"Lectura todos los días a la misma hora"},{"id":"o4","texto":"Que cada vecino elija su propio recipiente"},{"id":"o5","texto":"Leer cuando uno se acuerda"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Igual instrumento, igual ubicación, igual horario: así las diferencias se deben a la lluvia."}},{"slug":"ciencia-4.s5.p8","orden":8,"grupo":"ciencia-4.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cuatro pluviómetros del pueblo midieron 12, 18, 9, 21 mm en la misma tormenta. ¿Cuál es el promedio? Redondeá a un decimal.","unidad":"mm","decimales":1,"contexto":"Mediciones de 12, 18, 9, 21 mm."},"solucion":{"valor":15,"tolerancia":0.1,"explicacion":"(12 + 18 + 9 + 21) ÷ 4 = 15 mm. Pero el promedio esconde que un barrio recibió más del doble que otro: por eso sirve tener varios puntos."}},{"slug":"ciencia-4.s5.p8.v2","orden":8,"grupo":"ciencia-4.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cuatro pluviómetros del pueblo midieron 30, 24, 36, 30 mm en la misma tormenta. ¿Cuál es el promedio? Redondeá a un decimal.","unidad":"mm","decimales":1,"contexto":"Mediciones de 30, 24, 36, 30 mm."},"solucion":{"valor":30,"tolerancia":0.1,"explicacion":"(30 + 24 + 36 + 30) ÷ 4 = 30 mm. Pero el promedio esconde que un barrio recibió más del doble que otro: por eso sirve tener varios puntos."}},{"slug":"ciencia-4.s5.p8.v3","orden":8,"grupo":"ciencia-4.s5.p8","tipo":"numero","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"Cuatro pluviómetros del pueblo midieron 5, 11, 8, 12 mm en la misma tormenta. ¿Cuál es el promedio? Redondeá a un decimal.","unidad":"mm","decimales":1,"contexto":"Mediciones de 5, 11, 8, 12 mm."},"solucion":{"valor":9,"tolerancia":0.1,"explicacion":"(5 + 11 + 8 + 12) ÷ 4 = 9 mm. Pero el promedio esconde que un barrio recibió más del doble que otro: por eso sirve tener varios puntos."}},{"slug":"ciencia-4.s5.p9","orden":9,"grupo":"ciencia-4.s5.p9","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Ética del proyecto","cuerpo":["Un proyecto responsable cuida a las personas: explica para qué se usan los datos, pide permiso para publicarlos, protege la privacidad y no pone a nadie en riesgo (por ejemplo, no pide muestrear un arroyo en crecida). Cuida al ambiente: no molesta a la fauna ni extrae más de lo necesario. Y cumple las normas: algunas actividades, como capturar animales, necesitan permisos oficiales."]},"solucion":{}},{"slug":"ciencia-4.s5.p10","orden":10,"grupo":"ciencia-4.s5.p10","tipo":"detectar","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"Leé el protocolo que armó un grupo y marcá lo que conviene cambiar.","segmentos":[{"id":"s1","texto":"Explicamos a cada participante para qué se usan los datos."},{"id":"s2","texto":"Vamos a muestrear el arroyo también en los días de crecida."},{"id":"s3","texto":"Registramos hora, lugar y duración de cada observación."},{"id":"s4","texto":"Capturaremos ranas para contarlas en casa y después soltarlas."}]},"solucion":{"clave":["s2","s4"],"explicacion":"La seguridad de las personas y el bienestar de la fauna van antes que los datos.","por_opcion":{"s2":"Pone en riesgo a las personas; hay que evitarlo.","s4":"Molesta a la fauna y puede requerir permisos; se cuentan en el lugar."}}},{"slug":"ciencia-4.s5.p11","orden":11,"grupo":"ciencia-4.s5.p11","tipo":"vf","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Devolver los resultados a quienes participaron es opcional y no cambia nada.","razones":[{"id":"r1","texto":"Porque motiva a participar y permite usar los resultados"},{"id":"r2","texto":"Porque los participantes no quieren saber nada"},{"id":"r3","texto":"Porque los resultados son secretos"}]},"solucion":{"valor":false,"explicacion":"La devolución es uno de los principios de la ciencia ciudadana: motiva a seguir participando y permite que la comunidad use los resultados.","clave":["r1"]}},{"slug":"ciencia-4.s5.p12","orden":12,"grupo":"ciencia-4.s5.p12","tipo":"ranking","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená estos proyectos del más al menos factible para una escuela.","items":[{"id":"i1","texto":"Contar polinizadores en las flores del patio con un protocolo de 10 minutos"},{"id":"i2","texto":"Medir la lluvia con pluviómetros caseros en las casas"},{"id":"i3","texto":"Monitorear aves en una reserva a 50 km cada semana"},{"id":"i4","texto":"Estudiar el cambio climático global con datos propios"}],"extremos":["Más factible","Menos factible"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Un buen primer proyecto es cercano, simple y sostenible en el tiempo.","valores":{"i1":"muy factible","i2":"factible","i3":"difícil","i4":"inviable"}}},{"slug":"ciencia-4.s5.p13","orden":13,"grupo":"ciencia-4.s5.p13","tipo":"cadena","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá la cadena de cómo los datos de los pluviómetros pueden llegar a una decisión.","items":[{"id":"i1","texto":"Los vecinos notan que algunas calles se inundan más"},{"id":"i2","texto":"Instalan pluviómetros con un protocolo común"},{"id":"i3","texto":"Registran la lluvia durante varios meses"},{"id":"i4","texto":"Encuentran que un barrio recibe más lluvias intensas"},{"id":"i5","texto":"Presentan los datos al municipio para planificar desagües"},{"id":"i6","texto":"El municipio decide sin mirar ningún dato"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Los datos ciudadanos, bien tomados, pueden orientar decisiones públicas."}},{"slug":"ciencia-4.s5.p14","orden":14,"grupo":"ciencia-4.s5.p14","tipo":"emparejar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"emparejar","enunciado":"Uní cada etapa con su propósito.","izquierda":[{"id":"a1","texto":"Pregunta"},{"id":"a2","texto":"Protocolo"},{"id":"a3","texto":"Prueba piloto"},{"id":"a4","texto":"Devolución"}],"derecha":[{"id":"b1","texto":"Definir qué se quiere saber"},{"id":"b2","texto":"Hacer comparables los datos"},{"id":"b3","texto":"Detectar problemas a tiempo"},{"id":"b4","texto":"Compartir resultados con la comunidad"}]},"solucion":{"clave":{"a1":"b1","a2":"b2","a3":"b3","a4":"b4"},"explicacion":"Cada etapa cumple una función. Saltarse una suele costar caro después."}},{"slug":"ciencia-4.s5.p15","orden":15,"grupo":"ciencia-4.s5.p15","tipo":"completar","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"completar","enunciado":"Completá.","texto":"Un proyecto empieza con una {{0}} concreta; antes de escalar conviene hacer una prueba {{1}}; y al final hay que hacer una {{2}} a la comunidad.","banco":[{"id":"w1","texto":"pregunta"},{"id":"w2","texto":"piloto"},{"id":"w3","texto":"devolución"},{"id":"w4","texto":"respuesta"},{"id":"w5","texto":"final"},{"id":"w6","texto":"factura"}]},"solucion":{"clave":["w1","w2","w3"],"explicacion":"Las etapas clave para armar un proyecto propio."}}]},{"slug":"ciencia-4.s6","orden":6,"tipo":"practica","titulo_es":"Práctica: ciencia ciudadana","bajada_es":"Proyectos, observaciones, protocolos, sesgos, datos abiertos y diseño de proyectos, mezclados.","minutos":8,"pasos":[{"slug":"ciencia-4.s6.p1","orden":1,"grupo":"ciencia-4.s6.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Todo junto, a tu ritmo","cuerpo":["Esta práctica mezcla lo de toda la unidad «Ciencia ciudadana». No hay nada nuevo: es para que lo que aprendiste se quede.","Arranca por lo que más te costó en las sesiones anteriores y termina con algo más exigente. Si algo sale mal, vuelve al final para que lo arregles."]},"solucion":{}}]},{"slug":"ciencia-4.s7","orden":7,"tipo":"desafio","titulo_es":"Desafío: el conteo de la plaza","bajada_es":"Cuatro grupos de una escuela contaron aves en distintos sectores de la plaza. Analizá los datos con cuidado.","minutos":10,"pasos":[{"slug":"ciencia-4.s7.p1","orden":1,"grupo":"ciencia-4.s7.p1","tipo":"teoria","dificultad":1,"concepto":null,"repasable":false,"payload":{"tipo":"teoria","titulo":"Los datos","cuerpo":["Los cuatro grupos debían seguir el mismo protocolo: 20 minutos por sector, anotando todas las aves que se ven u oyen. Pero no todos lo cumplieron."],"datos":{"tipo":"tabla","titulo":"Conteo de aves por sector","columnas":["Sector","Aves contadas","Minutos observados","Especies"],"filas":[["Norte (árboles nativos)","48","20","11"],["Sur (césped)","30","20","4"],["Este (junto a la calle)","60","60","6"],["Oeste (estanque)","40","20","9"]],"nota":"Datos ficticios para el ejercicio."}},"solucion":{}},{"slug":"ciencia-4.s7.p2","orden":2,"grupo":"ciencia-4.s7.p2","tipo":"numero","dificultad":1,"concepto":null,"repasable":true,"payload":{"tipo":"numero","enunciado":"¿Cuántas aves por hora contó el grupo del sector este?","unidad":"aves por hora","decimales":0,"contexto":"Sector este: 60 aves en 60 minutos."},"solucion":{"valor":60,"tolerancia":1.2,"explicacion":"60 aves en 60 minutos = 60 por hora. Parece mucho, pero el grupo observó el triple de tiempo que el resto: hay que comparar tasas."}},{"slug":"ciencia-4.s7.p3","orden":3,"grupo":"ciencia-4.s7.p3","tipo":"ranking","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"ranking","enunciado":"Ordená los sectores por aves por hora, de mayor a menor.","items":[{"id":"i1","texto":"Norte"},{"id":"i2","texto":"Oeste"},{"id":"i3","texto":"Sur"},{"id":"i4","texto":"Este"}],"extremos":["Más","Menos"]},"solucion":{"clave":["i1","i2","i3","i4"],"explicacion":"Norte: 48 × 3 = 144; Oeste: 40 × 3 = 120; Sur: 30 × 3 = 90; Este: 60. El este, que tenía el mayor total, queda último en la tasa.","valores":{"i1":"144 por hora","i2":"120 por hora","i3":"90 por hora","i4":"60 por hora"}}},{"slug":"ciencia-4.s7.p4","orden":4,"grupo":"ciencia-4.s7.p4","tipo":"opcion","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"opcion","enunciado":"¿Qué error cometería quien dijera que el sector este tiene más aves?","opciones":[{"id":"o1","texto":"Comparar totales sin tener en cuenta el esfuerzo"},{"id":"o2","texto":"Confundir especies de aves nativas y exóticas"},{"id":"o3","texto":"Contar las aves que se oyen"},{"id":"o4","texto":"Usar datos de una sola plaza"}]},"solucion":{"clave":["o1"],"explicacion":"El grupo este observó 60 minutos en lugar de 20. Por tiempo de búsqueda, es el sector con menos aves.","por_opcion":{"o3":"El protocolo pedía contarlas: no es un error."}}},{"slug":"ciencia-4.s7.p5","orden":5,"grupo":"ciencia-4.s7.p5","tipo":"multiple","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"multiple","enunciado":"¿Qué conclusiones se pueden sacar con cuidado? Marcá todas.","opciones":[{"id":"o1","texto":"El sector norte, con árboles nativos, tuvo más especies"},{"id":"o2","texto":"El césped tuvo pocas especies"},{"id":"o3","texto":"Habría que repetir el conteo en otras fechas"},{"id":"o4","texto":"La calle atrae más aves que el estanque"},{"id":"o5","texto":"Los árboles nativos no influyen en las aves"}]},"solucion":{"clave":["o1","o2","o3"],"explicacion":"Un solo conteo da pistas, no certezas: repetir en distintas fechas fortalece las conclusiones."}},{"slug":"ciencia-4.s7.p6","orden":6,"grupo":"ciencia-4.s7.p6","tipo":"vf","dificultad":2,"concepto":null,"repasable":true,"payload":{"tipo":"vf","enunciado":"¿Verdadero o falso?","afirmacion":"Con un solo día de conteo se puede afirmar que el sector norte siempre tiene más aves.","razones":[{"id":"r1","texto":"Porque un solo día puede estar influido por el azar"},{"id":"r2","texto":"Porque los conteos de aves no sirven"},{"id":"r3","texto":"Porque las aves no vuelven nunca al mismo lugar"}]},"solucion":{"valor":false,"explicacion":"Un solo día puede estar influido por el clima, la hora o el azar. Hacen falta conteos repetidos para hablar de un patrón.","clave":["r1"]}},{"slug":"ciencia-4.s7.p7","orden":7,"grupo":"ciencia-4.s7.p7","tipo":"cadena","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"cadena","enunciado":"Armá el plan para mejorar el próximo conteo.","items":[{"id":"i1","texto":"Recordar a todos los grupos el protocolo de 20 minutos"},{"id":"i2","texto":"Contar en la misma franja horaria en todos los sectores"},{"id":"i3","texto":"Repetir el conteo una vez por mes durante un año"},{"id":"i4","texto":"Cargar los datos con el esfuerzo registrado"},{"id":"i5","texto":"Comparar tasas por hora entre sectores y estaciones"},{"id":"i6","texto":"Dejar que cada grupo elija cuánto tiempo contar"}],"largo":5},"solucion":{"clave":["i1","i2","i3","i4","i5"],"explicacion":"Mismo protocolo, misma hora, repeticiones y esfuerzo registrado: así los datos responden la pregunta."}},{"slug":"ciencia-4.s7.p8","orden":8,"grupo":"ciencia-4.s7.p8","tipo":"detectar","dificultad":3,"concepto":null,"repasable":true,"payload":{"tipo":"detectar","enunciado":"La escuela escribe el informe. Marcá lo que conviene corregir.","segmentos":[{"id":"s1","texto":"El sector norte tuvo la mayor tasa de aves por hora."},{"id":"s2","texto":"El sector este tiene más aves porque contó 60."},{"id":"s3","texto":"Recomendamos plantar más árboles nativos, aunque hay que confirmarlo con más conteos."},{"id":"s4","texto":"Ya está demostrado para siempre; no hace falta repetir."}]},"solucion":{"clave":["s2","s4"],"explicacion":"Un buen informe de ciencia ciudadana es honesto sobre lo que los datos muestran y lo que no.","por_opcion":{"s2":"Contó 60 en el triple de tiempo: su tasa es la más baja.","s4":"Un solo conteo no alcanza; hay que repetir para confirmar."}}}]}]}$ac$::jsonb);
